// ---------- varint / wire ----------
fn read_varint(b: &mut &[u8]) -> Option<i64> {
    let input = *b;
    let (v, n) = megu_core::varint::read_varlong_i64(input).ok()?;
    *b = &input[n..];
    Some(v)
}
/// Protocol VarInt is at most five bytes; the save reader also supports wider values.
fn read_protocol_i32(b: &mut &[u8]) -> Option<i32> {
    let before = b.len();
    let value = read_varint(b)?;
    if before - b.len() > 5 || value > u32::MAX as i64 {
        return None;
    }
    Some(value as u32 as i32)
}
fn write_varint(out: &mut Vec<u8>, v: i64) {
    // i32-range values encode as VarInt (5-byte u32 LEB128); wider as VarLong.
    if v >= i32::MIN as i64 && v <= i32::MAX as i64 {
        megu_core::varint::write_varint_i32(v as i32, out);
    } else {
        megu_core::varint::write_varlong_i64(v, out);
    }
}
fn write_str(out: &mut Vec<u8>, s: &str) {
    megu_core::varint::write_mc_string(s, out);
}
fn write_pos(out: &mut Vec<u8>, x: i32, y: i32, z: i32) {
    let v = ((x as i64 & 0x3ffffff) << 38) | ((z as i64 & 0x3ffffff) << 12) | (y as i64 & 0xfff);
    out.extend_from_slice(&v.to_be_bytes());
}

// Protocol 767 (Java 1.21.1) clientbound Play payload encoders.
// Each result contains a packet ID and its unframed payload. Callers decide
// whether and when to send the packet; construction alone is not emission.
#[allow(dead_code)]
fn encode_play_bundle_delimiter() -> (i64, Vec<u8>) {
    (0x00, Vec::new())
}

#[allow(dead_code)]
fn encode_play_add_experience_orb(
    entity_id: i32,
    x: f64,
    y: f64,
    z: f64,
    count: i16,
) -> (i64, Vec<u8>) {
    let mut out = Vec::new();
    write_varint(&mut out, i64::from(entity_id));
    for coord in [x, y, z] {
        out.extend_from_slice(&coord.to_be_bytes());
    }
    out.extend_from_slice(&count.to_be_bytes());
    (0x02, out)
}

#[allow(dead_code)]
fn encode_play_block_destruction(
    entity_id: i32,
    position: (i32, i32, i32),
    stage: i8,
) -> (i64, Vec<u8>) {
    let mut out = Vec::new();
    write_varint(&mut out, i64::from(entity_id));
    write_pos(&mut out, position.0, position.1, position.2);
    out.push(stage as u8);
    (0x06, out)
}

#[allow(dead_code)]
fn encode_play_chunks_biomes(chunks: &[(i32, i32, &[u8])]) -> (i64, Vec<u8>) {
    let mut out = Vec::new();
    write_varint(&mut out, chunks.len() as i64);
    for &(x, z, data) in chunks {
        // ChunkPos uses big-endian Z then X in the packed 64-bit value.
        out.extend_from_slice(&z.to_be_bytes());
        out.extend_from_slice(&x.to_be_bytes());
        write_varint(&mut out, data.len() as i64);
        out.extend_from_slice(data);
    }
    (0x0e, out)
}

#[allow(dead_code)]
fn encode_play_cookie_request(key: &str) -> (i64, Vec<u8>) {
    let mut out = Vec::new();
    write_str(&mut out, key);
    (0x16, out)
}

