/// `custom_chat_completions` (`0x18`): `action` is 0 add / 1 remove / 2 set,
/// followed by a list of strings. Vanilla's `PlayerList` uses it to track the
/// online-name completion set: the joiner gets `add` for every online name
/// and everyone else gets `add` for the new name; a departure removes it.
fn encode_play_custom_chat_completions(action: i64, entries: &[String]) -> (i64, Vec<u8>) {
    let mut out = Vec::new();
    write_varint(&mut out, action);
    write_varint(&mut out, entries.len() as i64);
    for entry in entries {
        write_str(&mut out, entry);
    }
    (0x18, out)
}

#[allow(dead_code)]
fn encode_play_player_look_at(
    source_anchor: u8,
    target: (f64, f64, f64),
    target_entity: Option<(i32, u8)>,
) -> Option<(i64, Vec<u8>)> {
    if source_anchor > 1 || target_entity.is_some_and(|(_, anchor)| anchor > 1) {
        return None;
    }
    let mut out = Vec::new();
    write_varint(&mut out, i64::from(source_anchor));
    for coord in [target.0, target.1, target.2] {
        out.extend_from_slice(&coord.to_be_bytes());
    }
    out.push(u8::from(target_entity.is_some()));
    if let Some((entity_id, anchor)) = target_entity {
        write_varint(&mut out, i64::from(entity_id));
        write_varint(&mut out, i64::from(anchor));
    }
    Some((0x3f, out))
}

