enum PlayServerLinkLabel<'a> {
    BuiltIn(u32),
    Custom(&'a [u8]), // Anonymous NBT text component.
}

#[allow(dead_code)]
fn encode_play_server_links(links: &[(PlayServerLinkLabel<'_>, &str)]) -> (i64, Vec<u8>) {
    let mut out = Vec::new();
    write_varint(&mut out, links.len() as i64);
    for (label, url) in links {
        match label {
            PlayServerLinkLabel::BuiltIn(id) => {
                out.push(1);
                write_varint(&mut out, i64::from(*id));
            }
            PlayServerLinkLabel::Custom(nbt) => {
                out.push(0);
                out.extend_from_slice(nbt);
            }
        }
        write_str(&mut out, url);
    }
    (0x7b, out)
}

// ---------------------------------------------------------------------------
// Lane GAP-S2C-18: the eighteen protocol-767 play packets that previously had
// no audit-visible emission. Each encoder below returns the `(packet_id,
// payload)` tuple the broadcast/send machinery consumes; every one of them is
// called by a real gameplay, command, or session path further down.
// ---------------------------------------------------------------------------

/// `level_chunk_with_light` (0x27): finishes the payload `map_chunk_lane`
/// assembled — the block-entity splice and the anti-xray light cull are part
/// of the encode so every tracker receives the same bytes `cached_chunk_frame`
/// prefixes into its shared frame.
fn encode_play_level_chunk_with_light(
    mut payload: Vec<u8>,
    entities: Vec<ChunkBlockEntity>,
    dim: DimId,
) -> (i64, Vec<u8>) {
    splice_chunk_block_entities(&mut payload, entities);
    cull_chunk_light(&mut payload, dim);
    (0x27, payload)
}

/// `set_title_text` (0x65) / `set_subtitle_text` (0x63): the payload is a bare
/// network-NBT text component — the same shape the `/title` command branches
/// emit.
fn encode_play_set_title_text(component_nbt: &[u8]) -> (i64, Vec<u8>) {
    (0x65, component_nbt.to_vec())
}

fn encode_play_set_subtitle_text(component_nbt: &[u8]) -> (i64, Vec<u8>) {
    (0x63, component_nbt.to_vec())
}

/// `set_titles_animation` (0x66): fade-in, stay and fade-out ticks as three
/// big-endian i32 — vanilla `ClientboundSetTitlesAnimationPacket`.
fn encode_play_set_titles_animation(fade_in: i32, stay: i32, fade_out: i32) -> (i64, Vec<u8>) {
    let mut p = Vec::with_capacity(12);
    for v in [fade_in, stay, fade_out] {
        p.extend_from_slice(&v.to_be_bytes());
    }
    (0x66, p)
}

/// `/title <who> title <component>` — `component` is plain text or a JSON/SNBT
/// component, normalized by the same `text_component_nbt` the command lane
/// uses.
pub fn send_play_title_text(s: &mut TcpStream, component: &str) -> std::io::Result<()> {
    send_packet(s, 0x65, encode_play_set_title_text(&text_component_nbt(component)).1)
}

/// `/title <who> subtitle <component>`.
pub fn send_play_subtitle_text(s: &mut TcpStream, component: &str) -> std::io::Result<()> {
    send_packet(s, 0x63, encode_play_set_subtitle_text(&text_component_nbt(component)).1)
}

/// `/title <who> times <fade_in> <stay> <fade_out>` — tick counts as the wire
/// carries them.
pub fn send_play_titles_animation(
    s: &mut TcpStream,
    fade_in: i32,
    stay: i32,
    fade_out: i32,
) -> std::io::Result<()> {
    send_packet(s, 0x66, encode_play_set_titles_animation(fade_in, stay, fade_out).1)
}

/// `player_look_at` (0x3f) — the `ServerPlayer.lookAt` send `/tp ... facing`
/// uses to aim the target client's view: `source_anchor` is 0 = feet /
/// 1 = eyes, `target` the world point, and `target_entity` an optional entity
/// whose anchor point replaces the fixed position.
pub fn send_play_player_look_at(
    s: &mut TcpStream,
    source_anchor: u8,
    target: (f64, f64, f64),
    target_entity: Option<(i32, u8)>,
) -> std::io::Result<()> {
    let Some((_, payload)) = encode_play_player_look_at(source_anchor, target, target_entity)
    else {
        return Ok(());
    };
    send_packet(s, 0x3f, payload)
}

/// `delete_chat` (0x1c): retracts a relayed signed message — the
/// chat-moderation packet. `Signature` targets the message signature bytes,
/// `MessageSignature` an id plus index into the client's signature chain.
pub fn broadcast_play_delete_chat(target: PlayChatDeletion<'_>) {
    let Some((_, payload)) = encode_play_delete_chat(target) else {
        return;
    };
    broadcast_packet(-1, 0x1c, &payload);
}

/// `start_configuration` (0x69): kicks off the optional mid-play reconfigure
/// exchange. The client's `configuration_acknowledged` reply is recorded by
/// `reconfigure_acked`, which tracks the window until play resumes.
pub fn send_play_start_configuration(s: &mut TcpStream) -> std::io::Result<()> {
    send_packet(s, 0x69, encode_play_start_configuration().1)
}

/// `cookie_request` (0x16): the play-phase cookie round-trip; the client's
/// `cookie_response` (C2S 0x11) lands in `client_cookies`.
pub fn send_play_cookie_request(s: &mut TcpStream, key: &str) -> std::io::Result<()> {
    send_packet(s, 0x16, encode_play_cookie_request(key).1)
}

/// `store_cookie` (0x6b): asks the client to persist up to 5 KiB under `key`.
pub fn send_play_store_cookie(s: &mut TcpStream, key: &str, value: &[u8]) -> std::io::Result<()> {
    let Some((_, payload)) = encode_play_store_cookie(key, value) else {
        return Ok(());
    };
    send_packet(s, 0x6b, payload)
}

/// `resource_pack_pop` (0x45): `None` pops the client's whole pack stack.
pub fn send_play_resource_pack_pop(
    s: &mut TcpStream,
    pack_id: Option<[u8; 16]>,
) -> std::io::Result<()> {
    send_packet(s, 0x45, encode_play_resource_pack_pop(pack_id).1)
}

/// `sound_entity` (0x67): `Level.playEntitySound` — the sound rides the
/// entity's position as it moves instead of a fixed point. `source` is the
/// `SoundSource` varint (`neutral` = 6, `players` = 7).
fn broadcast_entity_sound(eid: i32, identifier: &str, source: u32) {
    let Some((_, payload)) = encode_play_sound_entity(
        PlaySound::Custom {
            identifier,
            fixed_range: None,
        },
        source,
        eid,
        1.0,
        1.0,
        world_rng::next_u64() as i64,
    ) else {
        return;
    };
    broadcast_seen_packet(eid, 0x67, &payload);
}

/// Window ids for the horse screen reuse the interactive-menu space (4..=100)
/// so a stale client `container_close` is ignored like a menu id.
fn next_horse_window_id(me: &Client) -> Option<u8> {
    let connection = live_menu_connection(me)?;
    loop {
        let current = connection.next_id.load(Ordering::Relaxed);
        let next = if current == 100 { 4 } else { current + 1 };
        if connection
            .next_id
            .compare_exchange(current, next, Ordering::Relaxed, Ordering::Relaxed)
            .is_ok()
        {
            return Some(current);
        }
    }
}

/// `ServerboundPlayerCommandPacket.Action.OPEN_INVENTORY` while riding an
/// equine: vanilla `ServerPlayer.openHorseInventory` answers
/// `horse_screen_open` (0x23) followed by the container's initial
/// `container_set_content` (0x13) — empty equipment slots, then the player's
/// window slots 9..=44 and an empty carried stack.
fn open_horse_screen(me: &Client) {
    let Some(vehicle) = vehicle_of(me.eid) else {
        return;
    };
    let kind = {
        let mounts = mounts().lock().unwrap_or_else(|e| e.into_inner());
        mounts.registry.kinds.get(&vehicle).copied()
    };
    if !matches!(
        kind,
        Some(
            VehicleKind::Horse
                | VehicleKind::Donkey
                | VehicleKind::Mule
                | VehicleKind::Llama
                | VehicleKind::Camel
        )
    ) {
        return;
    }
    let Some(window_id) = next_horse_window_id(me) else {
        return;
    };
    // Unchested equines expose two slots (saddle + armor); chest columns only
    // exist once the animal actually carries a chest.
    let slots: u32 = 2;
    let (_, payload) = encode_play_horse_screen_open(window_id, slots, vehicle);
    let empty: Stack = (0, 0, Vec::new());
    let mut w = me.sock.lock().unwrap_or_else(|e| e.into_inner());
    if send_packet(&mut w, 0x23, payload).is_err() {
        return;
    }
    let inv = me.inv.lock().unwrap_or_else(|e| e.into_inner());
    let mut content = vec![window_id];
    write_varint(&mut content, 0);
    write_varint(&mut content, i64::from(slots) + 36);
    for _ in 0..slots {
        content.extend_from_slice(&slot_wire(&empty));
    }
    for islot in 9..=44i16 {
        content.extend_from_slice(&slot_wire(inv.get(&islot).unwrap_or(&empty)));
    }
    content.extend_from_slice(&slot_wire(&empty));
    let _ = send_packet(&mut w, 0x13, content);
}

/// One `map_item_data` (0x2c) per held filled_map per connection: vanilla
/// `MapItem.inventoryTick` pushes the saved render while the map state
/// changes; the cartography-table path creates the `MapState`, so the first
/// carry sends scale/locked plus an empty decoration list.
fn map_data_sent() -> &'static Mutex<HashSet<(i32, i64)>> {
    static SENT: OnceLock<Mutex<HashSet<(i32, i64)>>> = OnceLock::new();
    SENT.get_or_init(|| Mutex::new(HashSet::new()))
}

fn send_held_map_data(me: &Client, held_slot: i16) {
    let stack = me
        .inv
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .get(&(36 + held_slot))
        .cloned();
    let Some(stack) = stack else {
        return;
    };
    let Some(state) = live_map_state(&stack) else {
        return;
    };
    let Ok(map_id) = i32::try_from(state.map_id) else {
        return;
    };
    if !map_data_sent()
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .insert((me.eid, state.map_id))
    {
        return;
    }
    if let Some((_, payload)) =
        encode_play_map_item_data(map_id, state.scale as i8, state.locked, Some(&[]), None)
    {
        let _ = send_packet(
            &mut me.sock.lock().unwrap_or_else(|e| e.into_inner()),
            0x2c,
            payload,
        );
    }
}

/// Name -> play-registry id resolvers for `update_tags` (0x78) member lists.
/// Unknown members fail closed (skipped) exactly like `resolve_optional_tags`
/// drops unresolvable optional entries.
fn tag_block_wire_id(name: &str) -> Option<i32> {
    let reg = crate::block_registry::breg()?;
    let st = reg.state_of(name, None);
    if reg.name_of(st) != crate::block_registry::ns_name(name) {
        return None;
    }
    reg.block_id_of(st)
}

fn tag_item_wire_id(name: &str) -> Option<i32> {
    name_to_item(name).and_then(|v| i32::try_from(v).ok())
}

fn tag_etype_wire_id(name: &str) -> Option<i32> {
    name_to_etype(name).and_then(|v| i32::try_from(v).ok())
}

fn tag_fluid_wire_id(name: &str) -> Option<i32> {
    Some(match name {
        "minecraft:empty" => 0,
        "minecraft:flowing_water" => 1,
        "minecraft:water" => 2,
        "minecraft:flowing_lava" => 3,
        "minecraft:lava" => 4,
        _ => return None,
    })
}

fn tag_biome_wire_id(name: &str) -> Option<i32> {
    let short = name.rsplit(':').next().unwrap_or(name);
    VANILLA_BIOMES
        .iter()
        .position(|&b| b == short)
        .and_then(|i| i32::try_from(i).ok())
}

/// The resolved `(wire registry, [(tag, member ids)])` map the datapack
/// registry publishes: every category whose members resolve to a live
/// registry id. Categories without a resolver are left out so clients keep
/// their registry-baseline tags — the wire format only carries ids.
type UpdateTagsRegistries = Vec<(String, Vec<(String, Vec<i32>)>)>;

fn update_tags_wire_map() -> UpdateTagsRegistries {
    let categories: Vec<(String, Vec<String>)> = {
        let registry = datapack_registry()
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        registry
            .tags
            .iter()
            .map(|(category, tags)| (category.clone(), tags.keys().cloned().collect()))
            .collect()
    };
    let mut registries: UpdateTagsRegistries = Vec::new();
    for (category, tag_names) in categories {
        let (registry_name, resolve): (&str, fn(&str) -> Option<i32>) = match category.as_str() {
            "block" => ("minecraft:block", tag_block_wire_id),
            "item" => ("minecraft:item", tag_item_wire_id),
            "entity_type" => ("minecraft:entity_type", tag_etype_wire_id),
            "fluid" => ("minecraft:fluid", tag_fluid_wire_id),
            "biome" | "worldgen/biome" => ("minecraft:worldgen/biome", tag_biome_wire_id),
            _ => continue,
        };
        if !registries.iter().any(|(name, _)| name == registry_name) {
            registries.push((registry_name.to_string(), Vec::new()));
        }
        let Some((_, tags)) = registries.iter_mut().find(|(n, _)| n == registry_name) else {
            continue;
        };
        for tag in tag_names {
            let entries: Vec<i32> = datapack_tag_members(&category, &tag)
                .into_iter()
                .filter_map(|name| resolve(&name))
                .collect();
            tags.push((tag, entries));
        }
    }
    registries
}

/// The tag map `update_tags` (0x78) carries, encoded for the play-phase
/// datapack resend.
fn update_tags_wire_payload() -> Vec<u8> {
    let registries = update_tags_wire_map();
    let tag_vecs: Vec<Vec<PlayTag<'_>>> = registries
        .iter()
        .map(|(_, tags)| {
            tags.iter()
                .map(|(name, entries)| PlayTag {
                    name: name.as_str(),
                    entries: entries.as_slice(),
                })
                .collect()
        })
        .collect();
    let wire: Vec<PlayTagRegistry<'_>> = registries
        .iter()
        .zip(&tag_vecs)
        .map(|((name, _), tags)| PlayTagRegistry {
            name: name.as_str(),
            tags: tags.as_slice(),
        })
        .collect();
    encode_play_update_tags(&wire).1
}

/// Decoded `(wire registry, [(tag, member ids)])` form of one `update_tags`
/// body (packet id already consumed). `None` on any malformed field — a
/// captured packet is authoritative input, never partially applied.
fn update_tags_wire_decode(
    mut input: &[u8],
) -> Option<UpdateTagsRegistries> {
    let count = read_protocol_i32(&mut input)?;
    if !(0..=64).contains(&count) {
        return None;
    }
    let mut registries = Vec::with_capacity(count as usize);
    for _ in 0..count {
        let name = registry_wire_name(&mut input)?.to_string();
        let tag_count = read_protocol_i32(&mut input)?;
        if !(0..=4096).contains(&tag_count) {
            return None;
        }
        let mut tags = Vec::with_capacity(tag_count as usize);
        for _ in 0..tag_count {
            let tag = registry_wire_name(&mut input)?.to_string();
            let member_count = read_protocol_i32(&mut input)?;
            if !(0..=0x100000).contains(&member_count) {
                return None;
            }
            let mut members = Vec::with_capacity(member_count.min(4096) as usize);
            for _ in 0..member_count {
                members.push(read_protocol_i32(&mut input)?);
            }
            tags.push((tag, members));
        }
        registries.push((name, tags));
    }
    input.is_empty().then_some(registries)
}

/// Merge the datapack tag map into a baseline tag map: every resolved
/// datapack tag is unioned into the matching registry (the store keeps raw
/// member lists without `replace` flags, so vanilla's `replace:false` append
/// semantics are the honest merge), and registries the baseline never carried
/// are appended.
fn merge_update_tags_baseline(
    mut baseline: UpdateTagsRegistries,
    overlay: UpdateTagsRegistries,
) -> UpdateTagsRegistries {
    for (reg_name, tags) in overlay {
        let Some((_, base_tags)) = baseline.iter_mut().find(|(n, _)| *n == reg_name) else {
            baseline.push((reg_name, tags));
            continue;
        };
        for (tag, members) in tags {
            match base_tags.iter_mut().find(|(t, _)| *t == tag) {
                Some((_, base_members)) => {
                    for id in members {
                        if !base_members.contains(&id) {
                            base_members.push(id);
                        }
                    }
                }
                None => base_tags.push((tag, members)),
            }
        }
    }
    baseline
}

/// The captured `update_tags` (`0x0d`) predates every datapack load: merge
/// the live server-side tag map into it so the configuration phase publishes
/// the same tags a mid-play `update_tags` resend would, the way vanilla's
/// tag-task output is always the current map.
fn config_tags_merge(config: &mut [(i64, Vec<u8>)]) {
    let overlay = update_tags_wire_map();
    if overlay.is_empty() {
        return;
    }
    for (id, packet) in config.iter_mut() {
        if *id != 0x0d {
            continue;
        }
        let mut body = &packet[..];
        if read_varint(&mut body) != Some(0x0d) {
            continue;
        }
        let Some(baseline) = update_tags_wire_decode(body) else {
            continue;
        };
        let merged = merge_update_tags_baseline(baseline, overlay.clone());
        let mut merged_wire = Vec::new();
        write_varint(&mut merged_wire, 0x0d);
        write_varint(&mut merged_wire, merged.len() as i64);
        for (name, tags) in &merged {
            write_str(&mut merged_wire, name);
            write_varint(&mut merged_wire, tags.len() as i64);
            for (tag, members) in tags {
                write_str(&mut merged_wire, tag);
                write_varint(&mut merged_wire, members.len() as i64);
                for member in members {
                    write_varint(&mut merged_wire, i64::from(*member));
                }
            }
        }
        *packet = merged_wire;
    }
}

/// `/reload` and `/datapack` publishes bump `content_revision`; the first tick
/// after an observed bump re-sends the resolved tag map, matching vanilla
/// `reloadPlayerResources` pushing `update_tags` to every play client.
/// A bump that carries synced-registry content cannot be delivered that way —
/// registry data only exists on the wire inside the configuration phase — so
/// vanilla's mid-play `start_configuration` re-entry is used instead: each
/// connection's handler is marked and runs the exchange on its next pass.
fn play_content_revision_sync() {
    static SEEN: AtomicU64 = AtomicU64::new(u64::MAX);
    let revision = content_revision();
    let last = SEEN.swap(revision, Ordering::Relaxed);
    if last == u64::MAX || last == revision {
        return;
    }
    if config_registry_overlays_present() {
        let mut pending = reconfigure_pending().lock().unwrap_or_else(|e| e.into_inner());
        for c in clients().lock().unwrap_or_else(|e| e.into_inner()).iter() {
            pending.insert(c.eid);
        }
        return;
    }
    let payload = update_tags_wire_payload();
    broadcast_packet(-1, 0x78, &payload);
}

/// Entity ids whose connection handler should run the mid-play
/// `start_configuration` exchange: marked by `play_content_revision_sync` when
/// a content revision carries registry content, consumed at the head of the
/// per-connection play loop.
fn reconfigure_pending() -> &'static Mutex<HashSet<i32>> {
    static PENDING: OnceLock<Mutex<HashSet<i32>>> = OnceLock::new();
    PENDING.get_or_init(Mutex::default)
}

/// Whether the enabled datapacks contribute any synced-registry entries — the
/// content only the configuration phase can deliver to a client.
fn config_registry_overlays_present() -> bool {
    load_registry_overlays(std::path::Path::new(DATAPACK_DIRECTORY))
        .map(|overlays| !overlays.is_empty())
        .unwrap_or(false)
}

/// `chunks_biomes` (0x0e) data for one chunk: per-section biome paletted
/// containers — the same `write_palette` encoding `map_chunk_lane` bakes into
/// 0x27 — with the live `/fillbiome` overrides substituted before encoding.
fn chunk_biome_data(
    dim: DimId,
    cx: i32,
    cz: i32,
    overrides: &HashMap<(i32, i32, i32), String>,
) -> Vec<u8> {
    let mut data = Vec::new();
    let min_y = dim.min_y();
    for sy in (min_y..min_y + dim.height()).step_by(16) {
        let generated = worldgen::biome_section_dim(dim, cx, sy, cz)
            .unwrap_or_else(|| Box::new([39i64; 64]));
        let mut biomes = *generated;
        for ly in 0..4i32 {
            for lz in 0..4i32 {
                for lx in 0..4i32 {
                    let key = (cx * 4 + lx, (sy >> 2) + ly, cz * 4 + lz);
                    if let Some(name) = overrides.get(&key) {
                        if let Some(id) = tag_biome_wire_id(name) {
                            biomes[((ly << 4) | (lz << 2) | lx) as usize] = i64::from(id);
                        }
                    }
                }
            }
        }
        write_palette(&mut data, &biomes[..], 1, 3, 6);
    }
    data
}

/// Per-dimension biome override cells cloned out of the store for one sync pass.
type BiomeOverrideSnapshot = Vec<(DimId, HashMap<(i32, i32, i32), String>)>;

/// The `/fillbiome` store only ever inserts, so a growing quart-cell count is
/// the change signal; on change every chunk an override cell touches gets
/// `chunks_biomes` re-sent to the clients currently holding it.
fn biome_override_sync_tick() {
    static SEEN: AtomicU64 = AtomicU64::new(0);
    let snapshot: BiomeOverrideSnapshot = {
        let overrides = biome_overrides()
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        let total = overrides.values().map(|m| m.len() as u64).sum::<u64>();
        if SEEN.swap(total, Ordering::Relaxed) == total {
            return;
        }
        overrides
            .iter()
            .map(|(dim, cells)| (*dim, cells.clone()))
            .collect()
    };
    for (dim, cells) in snapshot {
        let mut chunks: Vec<(i32, i32)> = cells
            .keys()
            .map(|&(qx, _, qz)| (qx >> 2, qz >> 2))
            .collect::<HashSet<_>>()
            .into_iter()
            .collect();
        chunks.sort_unstable();
        for (cx, cz) in chunks {
            let data = chunk_biome_data(dim, cx, cz, &cells);
            let (_packet, payload) = encode_play_chunks_biomes(&[(cx, cz, data.as_slice())]);
            broadcast_chunk_dim_packet(dim, cx, cz, 0x0e, &payload);
        }
    }
}

fn read_pos(b: &[u8]) -> (i32, i32, i32) {
    let v = i64::from_be_bytes(b[..8].try_into().unwrap());
    let x = (v >> 38) as i32;
    let z = ((v >> 12) & 0x3ffffff) as i32;
    let y = (v & 0xfff) as i32;
    ((x << 6) >> 6, (y << 20) >> 20, (z << 6) >> 6) // sign-extend, (x,y,z) order
}

// A single wall-clock deadline covers every byte of pre-play handshaking.
// Socket read timeouts alone can be bypassed by sending one byte at a time.
fn read_before(s: &mut TcpStream, mut out: &mut [u8], deadline: Instant) -> Option<()> {
    while !out.is_empty() {
        let remaining = deadline.checked_duration_since(Instant::now())?;
        s.set_read_timeout(Some(remaining)).ok()?;
        let n = s.read(out).ok()?;
        if n == 0 {
            return None;
        }
        if let Some(cipher) = conn_cipher(s) {
            cipher.rx.lock().unwrap_or_else(|e| e.into_inner()).decrypt(&mut out[..n]);
        }
        out = &mut out[n..];
    }
    Some(())
}
fn read_packet(s: &mut TcpStream, deadline: Instant) -> Option<(i64, Vec<u8>)> {
    read_login_frame(s, deadline, None)
}

/// Read a pre-play packet only after charging it against the connection's
/// packet budget. Rejected packets are consumed and skipped; a sustained flood
/// ends the connection through the same two-second policy as play traffic.
fn read_preplay_frame(
    s: &mut TcpStream,
    deadline: Instant,
    compression: Option<usize>,
    rate: &mut connection_limits::PacketRateLimit,
) -> Option<(i64, Vec<u8>)> {
    loop {
        let packet = read_login_frame(s, deadline, compression)?;
        let now = Instant::now();
        if rate.allow(now) {
            return Some(packet);
        }
        if rate.should_disconnect(now) {
            return None;
        }
    }
}

fn read_login_frame(
    s: &mut TcpStream,
    deadline: Instant,
    compression: Option<usize>,
) -> Option<(i64, Vec<u8>)> {
    const MAX_LOGIN_FRAME: usize = 64 * 1024;
    let mut len = 0u64;
    let mut done = false;
    for i in 0..3 {
        let mut b = [0u8; 1];
        read_before(s, &mut b, deadline)?;
        len |= ((b[0] & 0x7f) as u64) << (7 * i);
        if b[0] & 0x80 == 0 {
            done = true;
            break;
        }
    }
    // Pre-play packets are small; reject large declared allocations.
    if !done || len == 0 || len > MAX_LOGIN_FRAME as u64 {
        let _ = s.shutdown(std::net::Shutdown::Both);
        return None;
    }
    let mut body = vec![0u8; len as usize];
    read_before(s, &mut body, deadline)?;
    decode_packet(body, compression, MAX_LOGIN_FRAME)
}

fn decode_packet(
    body: Vec<u8>,
    compression: Option<usize>,
    max_size: usize,
) -> Option<(i64, Vec<u8>)> {
    let body = match compression {
        Some(threshold) => {
            connection_limits::decode_compressed_frame(&body, threshold, max_size).ok()?
        }
        None => body,
    };
    let mut payload = body.as_slice();
    let id = read_protocol_i32(&mut payload)?;
    (id >= 0).then(|| (i64::from(id), payload.to_vec()))
}

/// The ceiling an *inflated* play frame may occupy, from `/megu policy set
/// max_frame_mib <2..=8>` — vanilla's CompressionDecoder absolute maximum.
/// The wire prefix still cannot describe more than
/// vanilla's three-byte VarInt bound — this governs the decompressed payload
/// only, so raising it admits modded frames whose compressed bodies stay
/// small. The default `2` lands exactly on `ingress_guard::MAX_PLAY_FRAME`.
fn live_play_frame_bound() -> usize {
    ((live_server_policy()
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .max_frame_mib as usize)
        << 20)
        - 1
}
// Buffered frame reader for the consume loop: a mid-frame timeout must NOT
// drop already-read bytes. Dropped length bytes desync the stream -> garbage
// length fields -> repeated <=16MiB allocs -> allocator arena churn -> the OOM.
struct RxBuf {
    buf: std::collections::VecDeque<u8>,
    compression: Option<usize>,
}
enum RxOut {
    Closed,
    Idle,
    Frame(i64, Vec<u8>),
}
impl RxBuf {
    fn new(compression: Option<usize>) -> Self {
        RxBuf {
            buf: std::collections::VecDeque::new(),
            compression,
        }
    }
    fn try_frame(&mut self) -> Option<Option<RxOut>> {
        let n = self.buf.len();
        let mut len = 0i64;
        let mut i = 0usize;
        loop {
            if i >= n {
                return Some(None);
            }
            let b = self.buf[i];
            len |= ((b & 0x7f) as i64) << (7 * i);
            i += 1;
            if b & 0x80 == 0 {
                break;
            }
            if i == 3 {
                return None;
            }
        }
        // vanilla's Varint21FrameDecoder bound: a three-byte length prefix cannot
        // describe more, so a larger frame is not something a 1.21.1 client sends.
        if len == 0 || len as usize > ingress_guard::MAX_PLAY_FRAME {
            return None;
        }
        let total = i + len as usize;
        if n < total {
            return Some(None);
        }
        let body: Vec<u8> = self
            .buf
            .iter()
            .skip(i)
            .take(len as usize)
            .copied()
            .collect();
        self.buf.drain(..total);
        let (id, payload) = decode_packet(body, self.compression, live_play_frame_bound())?;
        Some(Some(RxOut::Frame(id, payload)))
    }
    fn next(&mut self, s: &mut TcpStream) -> RxOut {
        match self.try_frame() {
            None => {
                let _ = s.shutdown(std::net::Shutdown::Both);
                return RxOut::Closed;
            }
            Some(Some(f)) => return f,
            Some(None) => {}
        }
        let mut tmp = [0u8; 8192];
        match s.read(&mut tmp) {
            Ok(0) => RxOut::Closed,
            Ok(n) => {
                if let Some(cipher) = conn_cipher(s) {
                    cipher.rx.lock().unwrap_or_else(|e| e.into_inner()).decrypt(&mut tmp[..n]);
                }
                self.buf.extend(&tmp[..n]);
                match self.try_frame() {
                    Some(frame) => frame.unwrap_or(RxOut::Idle),
                    None => {
                        let _ = s.shutdown(std::net::Shutdown::Both);
                        RxOut::Closed
                    }
                }
            }
            Err(ref e)
                if e.kind() == std::io::ErrorKind::WouldBlock
                    || e.kind() == std::io::ErrorKind::TimedOut =>
            {
                RxOut::Idle
            }
            Err(_) => RxOut::Closed,
        }
    }
}
#[cfg(unix)]
fn socket_key(socket: &TcpStream) -> u64 {
    use std::os::fd::AsRawFd;
    socket.as_raw_fd() as u64
}

#[cfg(windows)]
fn socket_key(socket: &TcpStream) -> u64 {
    use std::os::windows::io::AsRawSocket;
    socket.as_raw_socket() as u64
}

#[derive(Default)]
struct SocketWireState {
    compression: Option<usize>,
    play: Option<PlayWireState>,
    cipher: Option<Arc<ConnCipher>>,
    tx_queue: Option<Arc<connection_limits::ClientTxQueue>>,
    tx_writer: Option<std::thread::JoinHandle<()>>,
}

/// The AES-128-CFB8 pair one online-mode connection runs under. Registered per
/// socket fd like the rest of `SocketWireState`: the login socket and the
/// `try_clone`d play writer are two fds pointing at one `Arc`, so bytes either
/// side writes advance a single keystream — matching Java's single cipher pair.
struct ConnCipher {
    rx: Mutex<Aes128Cfb8>,
    tx: Mutex<Aes128Cfb8>,
}

/// The connection's cipher if encryption was negotiated on this socket, else
/// `None` — one map lookup per socket call, on top of the lookup `send_packet`
/// already performs.
fn conn_cipher(s: &TcpStream) -> Option<Arc<ConnCipher>> {
    let state = wire_state(socket_key(s))?;
    let cipher = state.lock().unwrap_or_else(|e| e.into_inner()).cipher.clone();
    cipher
}

/// Arm encryption on `s`'s wire entry with the negotiated shared secret. Called
/// the moment the Encryption Response verifies: every later byte crossing the
/// read/write paths below is en- or decrypted through `conn_cipher`.
fn enable_conn_encryption(s: &TcpStream, secret: &[u8; 16]) {
    let cipher = Arc::new(ConnCipher {
        rx: Mutex::new(Aes128Cfb8::new(secret, secret)),
        tx: Mutex::new(Aes128Cfb8::new(secret, secret)),
    });
    let state = wire_state_or_insert(socket_key(s));
    state.lock().unwrap_or_else(|e| e.into_inner()).cipher = Some(cipher);
}

#[derive(Default)]
struct PlayWireState {
    poses: HashMap<i32, TrackedWirePose>,
    chunk_delivery: connection_limits::ChunkDelivery,
}

struct TrackedWirePose {
    pose: EntityWirePose,
    interval: u64,
    last_sent_tick: Option<u64>,
    /// Evaluations since the last absolute sync; vanilla teleports past 400.
    delay: u16,
    /// Evaluations while tracked; every 60th forces a position emit.
    tick_count: u64,
}

#[derive(Clone, Copy, PartialEq)]
struct EntityWirePose {
    pos: [f64; 3],
    yaw: u8,
    pitch: u8,
    on_ground: Option<bool>,
}

impl EntityWirePose {
    fn read(fields: &[u8], spawn: bool) -> Option<Self> {
        let pos = [
            f64::from_be_bytes(fields.get(..8)?.try_into().ok()?),
            f64::from_be_bytes(fields.get(8..16)?.try_into().ok()?),
            f64::from_be_bytes(fields.get(16..24)?.try_into().ok()?),
        ];
        let [a, b, tail] = fields.get(24..27)?.try_into().ok()?;
        let (yaw, pitch, on_ground) = if spawn {
            (b, a, None)
        } else {
            (a, b, Some(tail != 0))
        };
        Some(Self {
            pos,
            yaw,
            pitch,
            on_ground,
        })
    }

}

impl PlayWireState {
    fn remember_spawn(&mut self, mut payload: &[u8]) {
        let Some(eid) = read_protocol_i32(&mut payload) else {
            return;
        };
        let Some(mut fields) = payload.get(16..) else {
            return; // UUID
        };
        let Some(etype) = read_protocol_i32(&mut fields) else {
            return;
        };
        let Some(pose) = EntityWirePose::read(fields, true) else {
            return;
        };
        let interval = entity_spec_by_id(i64::from(etype))
            .map_or(0, |spec| u64::from(entity_update_interval_ticks(spec.name)));
        self.poses.insert(
            eid,
            TrackedWirePose {
                pose,
                interval,
                last_sent_tick: None,
                delay: 0,
                tick_count: 0,
            },
        );
    }

    fn update_packet(&mut self, id: &mut i64, payload: &mut Vec<u8>, tick: u64) -> bool {
        let mut fields = payload.as_slice();
        match *id {
            0x70 => {
                let Some(eid) = read_protocol_i32(&mut fields) else {
                    return true;
                };
                let Some(previous) = self.poses.get_mut(&eid) else {
                    return true;
                };
                let Some(next) = EntityWirePose::read(fields, false) else {
                    return true;
                };
                // These producers also send teleports and impulse-driven movement.
                // Only a repeat of the last sent pose is safe to pace by type here.
                if previous.pose == next
                    && previous
                        .last_sent_tick
                        .is_some_and(|sent| tick.wrapping_sub(sent) < previous.interval)
                {
                    return false;
                }
                previous.delay = previous.delay.saturating_add(1);
                previous.tick_count = previous.tick_count.saturating_add(1);
                // Vanilla 1.21.1 ServerEntity#sendChanges: an absolute teleport
                // heals an out-of-i16 delta, an on-ground flip, and more than
                // 400 evaluations without one. A spawn-seeded baseline carries
                // no on_ground, so it cannot "flip".
                let ground_flipped = next
                    .on_ground
                    .is_some_and(|n| previous.pose.on_ground.is_some_and(|g| g != n));
                let delta = connection_limits::relative_move_delta(previous.pose.pos, next.pos);
                if previous.delay > 400 || ground_flipped || delta.is_none()
                {
                    previous.pose = next;
                    previous.delay = 0;
                    previous.last_sent_tick = Some(tick);
                    return true;
                }
                let delta = delta.unwrap();
                // Position "changed" past the vanilla constant or on the
                // 60th-evaluation forced resync (vanilla ServerEntity
                // tickCount); rotation on a quantized byte change.
                let len_sqr: f64 = (0..3).map(|i| {
                    let d = next.pos[i] - previous.pose.pos[i];
                    d * d
                }).sum();
                let pos_changed =
                    len_sqr >= 7.629_394_531_25e-6 || previous.tick_count % 60 == 0;
                let rot_changed =
                    (previous.pose.yaw, previous.pose.pitch) != (next.yaw, next.pitch);
                let grounded = next.on_ground.unwrap_or(false);
                (*id, *payload) = match (pos_changed, rot_changed) {
                    (true, true) => (
                        0x2f,
                        connection_limits::entity_relative_move(
                            eid,
                            delta,
                            Some((next.yaw, next.pitch)),
                            grounded,
                        ),
                    ),
                    (true, false) => (
                        0x2e,
                        connection_limits::entity_relative_move(eid, delta, None, grounded),
                    ),
                    (false, true) => (
                        0x30,
                        connection_limits::entity_rotation(
                            eid,
                            next.yaw,
                            next.pitch,
                            grounded,
                        ),
                    ),
                    // Unchanged: vanilla sends no movement packet this tick.
                    (false, false) => return false,
                };
                // Only fields the packet actually carried advance the
                // baseline; an unsent position stays outstanding against the
                // last-sent value (vanilla VecDeltaCodec semantics).
                if pos_changed {
                    previous.pose.pos = next.pos;
                }
                if rot_changed {
                    previous.pose.yaw = next.yaw;
                    previous.pose.pitch = next.pitch;
                }
                previous.pose.on_ground = next.on_ground;
                previous.last_sent_tick = Some(tick);
            }
            0x42 => {
                let Some(count) = read_protocol_i32(&mut fields) else {
                    return true;
                };
                for _ in 0..count {
                    let Some(eid) = read_protocol_i32(&mut fields) else {
                        return true;
                    };
                    self.poses.remove(&eid);
                }
            }
            0x47 => {
                self.poses.clear();
                self.chunk_delivery.reset_window();
            }
            _ => {}
        }
        true
    }
}

// Existing packet producers share TcpStream, including the cloned Play writer.
// Store framing against each owned handle until its owner drops, before the OS
// can reuse the handle. The registry lock is released before compression or I/O.
static SOCKET_WIRE: OnceLock<std::sync::RwLock<HashMap<u64, Arc<Mutex<SocketWireState>>>>> = OnceLock::new();

fn socket_wire() -> &'static std::sync::RwLock<HashMap<u64, Arc<Mutex<SocketWireState>>>> {
    SOCKET_WIRE.get_or_init(std::sync::RwLock::default)
}

fn wire_state(key: u64) -> Option<Arc<Mutex<SocketWireState>>> {
    SOCKET_WIRE.get()?.read().unwrap_or_else(|e| e.into_inner()).get(&key).cloned()
}

fn wire_state_or_insert(key: u64) -> Arc<Mutex<SocketWireState>> {
    let mut states = socket_wire().write().unwrap_or_else(|e| e.into_inner());
    Arc::clone(states.entry(key).or_insert_with(|| Arc::new(Mutex::default())))
}

fn with_play_wire<T>(socket: &TcpStream, f: impl FnOnce(&mut PlayWireState) -> T) -> Option<T> {
    let state = wire_state(socket_key(socket))?;
    let mut state = state.lock().unwrap_or_else(|e| e.into_inner());
    state.play.as_mut().map(f)
}

fn unregister_socket_wire(key: u64) {
    if let Some(states) = SOCKET_WIRE.get() {
        states
            .write()
            .unwrap_or_else(|e| e.into_inner())
            .remove(&key);
    }
}

struct LoginCompression(u64);

impl std::ops::Drop for LoginCompression {
    fn drop(&mut self) {
        unregister_socket_wire(self.0);
    }
}

/// Same drop-unregister discipline for the cipher `enable_conn_encryption`
/// arms on the login socket's fd. Without it the entry outlives the connection
/// and a later connection reusing the fd inherits a dead keystream.
struct SocketCipherGuard(u64);

impl std::ops::Drop for SocketCipherGuard {
    fn drop(&mut self) {
        unregister_socket_wire(self.0);
    }
}

fn negotiate_compression(
    s: &mut TcpStream,
    threshold: i32,
) -> std::io::Result<Option<LoginCompression>> {
    let Ok(size) = usize::try_from(threshold) else {
        return Ok(None);
    };
    send_packet(s, 0x03, connection_limits::set_compression(threshold))?;
    let key = socket_key(s);
    let state = wire_state_or_insert(key);
    // Merge, not overwrite: online-mode login arms a cipher on this socket
    // before compression is negotiated.
    state.lock().unwrap_or_else(|e| e.into_inner()).compression = Some(size);
    Ok(Some(LoginCompression(key)))
}

fn send_packet(s: &mut TcpStream, mut id: i64, mut payload: Vec<u8>) -> std::io::Result<()> {
    if id == 0x5a {
        // SetEntityMotion: whatever the server (or a mod acting through it) launches a
        // player with is movement the anti-cheat must allow for.
        let mut body = payload.as_slice();
        if let Some(eid) = read_varint(&mut body) {
            if body.len() >= 6 {
                let axis = |i: usize| f64::from(i16::from_be_bytes([body[i], body[i + 1]])) / 8000.0;
                ac_note_server_velocity(eid as i32, [axis(0), axis(2), axis(4)]);
            }
        }
    }
    let mut send = true;
    let (compression, queued) = wire_state(socket_key(s)).map(|state| {
        let mut state = state.lock().unwrap_or_else(|e| e.into_inner());
        if let Some(play) = &mut state.play {
            send = play.update_packet(&mut id, &mut payload, TICK_IDX.load(Ordering::Relaxed));
        }
        // Keep the baseline update, compression and AES keystream advance in
        // one producer critical section. FIFO enqueue preserves that order
        // even if multiple tick/broadcast threads produce concurrently.
        let queued = if send && state.tx_queue.is_some() {
            let mut body = Vec::with_capacity(payload.len() + 5);
            write_varint(&mut body, id);
            body.extend_from_slice(&payload);
            queue_play_owned_frame(&state, encoded_frame(&body, state.compression))
        } else {
            None
        };
        (state.compression, queued)
    }).unwrap_or((None, None));
    if !send {
        return Ok(());
    }
    if let Some(result) = queued {
        return queued_send_result(s, result);
    }
    let mut body = Vec::new();
    write_varint(&mut body, id);
    body.extend_from_slice(&payload);
    write_frame(s, &body, compression)
}

fn encoded_frame(body: &[u8], compression: Option<usize>) -> Vec<u8> {
    match compression {
        Some(threshold) => connection_limits::encode_compressed_frame(body, threshold),
        None => {
            let mut frame = Vec::new();
            write_varint(&mut frame, body.len() as i64);
            frame.extend_from_slice(body);
            frame
        }
    }
}

/// Queue already-framed bytes while holding this connection's wire state. Encryption must
/// precede FIFO enqueue: AES-CFB8 is a stream cipher, so rearranging the
/// producer-side cipher advances would corrupt every later packet. Concatenating
/// encrypted frames in the writer's coalescer is byte-preserving.
fn queue_play_frame(
    state: &SocketWireState,
    mut frame: Arc<[u8]>,
) -> Option<Result<(), connection_limits::TxQueueError>> {
    let queue = state.tx_queue.as_ref()?;
    if let Some(cipher) = &state.cipher {
        let mut bytes = frame.to_vec();
        cipher.tx.lock().unwrap_or_else(|e| e.into_inner()).encrypt(&mut bytes);
        frame = Arc::from(bytes);
    }
    let result = queue.try_enqueue_arc(frame);
    if result == Err(connection_limits::TxQueueError::BackpressureSlowClient) {
        queue.close();
    }
    Some(result)
}

fn queue_play_owned_frame(
    state: &SocketWireState,
    mut frame: Vec<u8>,
) -> Option<Result<(), connection_limits::TxQueueError>> {
    let queue = state.tx_queue.as_ref()?;
    if let Some(cipher) = &state.cipher {
        cipher.tx.lock().unwrap_or_else(|e| e.into_inner()).encrypt(&mut frame);
    }
    let result = queue.try_enqueue(frame);
    if result == Err(connection_limits::TxQueueError::BackpressureSlowClient) {
        queue.close();
    }
    Some(result)
}

/// A saturated outbound queue closes only the offending socket; its producers
/// never perform network writes and therefore cannot stall a broadcast loop.
fn queued_send_result(
    s: &TcpStream,
    result: Result<(), connection_limits::TxQueueError>,
) -> std::io::Result<()> {
    match result {
        Ok(()) => Ok(()),
        Err(connection_limits::TxQueueError::Closed) => Err(std::io::Error::from(std::io::ErrorKind::BrokenPipe)),
        Err(connection_limits::TxQueueError::BackpressureSlowClient) => {
            eprintln!("[spine] disconnecting slow client: outbound queue full");
            let _ = s.shutdown(std::net::Shutdown::Both);
            Err(std::io::Error::from(std::io::ErrorKind::BrokenPipe))
        }
    }
}

fn write_frame(s: &mut TcpStream, body: &[u8], compression: Option<usize>) -> std::io::Result<()> {
    // Login/status/configuration sockets have no TX queue and keep their
    // synchronous handshake writes. Once Play is armed, all entry points use
    // the same produce-order serialization, including direct frame writers.
    let queued = wire_state(socket_key(s)).and_then(|state| {
        let state = state.lock().unwrap_or_else(|e| e.into_inner());
        if state.tx_queue.is_some() {
            queue_play_owned_frame(&state, encoded_frame(body, compression))
        } else {
            None
        }
    });
    if let Some(result) = queued {
        return queued_send_result(s, result);
    }
    let mut frame = encoded_frame(body, compression);
    if let Some(cipher) = conn_cipher(s) {
        cipher.tx.lock().unwrap_or_else(|e| e.into_inner()).encrypt(&mut frame);
    }
    let result = s.write_all(&frame);
    if result.is_err() {
        // A partial write invalidates both the frame boundary and entity baselines.
        let _ = s.shutdown(std::net::Shutdown::Both);
    }
    result
}

/// `write_frame` for an already-framed packet. `SharedBroadcastFrame` fans the
/// same `Arc<[u8]>` out to every recipient, so the bytes here are borrowed: a
/// plain connection writes them with no copy at all, while a ciphered
/// connection encrypts a scratch copy rather than mutating the shared
/// allocation the other recipients still have to send.
fn write_raw_frame_arc(s: &mut TcpStream, frame: Arc<[u8]>) -> std::io::Result<()> {
    let queued = wire_state(socket_key(s)).and_then(|state| {
        let state = state.lock().unwrap_or_else(|e| e.into_inner());
        queue_play_frame(&state, frame.clone())
    });
    if let Some(result) = queued {
        return queued_send_result(s, result);
    }
    let result = if let Some(cipher) = conn_cipher(s) {
        let mut bytes = frame.to_vec();
        cipher
            .tx
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .encrypt(&mut bytes);
        s.write_all(&bytes)
    } else {
        s.write_all(&frame)
    };
    if result.is_err() {
        // A partial write invalidates both the frame boundary and entity baselines.
        let _ = s.shutdown(std::net::Shutdown::Both);
    }
    result
}

#[cfg(test)]
fn write_raw_frame(s: &mut TcpStream, frame: &[u8]) -> std::io::Result<()> {
    write_raw_frame_arc(s, Arc::from(frame))
}

/// One broadcast's reusable wire form. The first `(id, payload)` `mk` produces
/// is framed once by the `SharedBroadcastFrame`; every later recipient `mk`
/// hands the same bytes to is served from it, so the fanout encodes and — for
/// compressed clients — compresses once instead of once per client. A
/// recipient whose `mk` returns different bytes reframes, which keeps
/// per-client producers byte-exact.
struct BroadcastFrameCache {
    id: i64,
    payload: Box<[u8]>,
    frame: connection_limits::SharedBroadcastFrame,
}

/// The shared frame for `(id, payload)`, building the cache entry on the first
/// call and whenever `mk` produced different bytes than the last recipient.
fn broadcast_frame<'c>(
    cache: &'c mut Option<BroadcastFrameCache>,
    id: i64,
    payload: &[u8],
) -> &'c mut connection_limits::SharedBroadcastFrame {
    let hit = cache
        .as_ref()
        .is_some_and(|c| c.id == id && c.payload.as_ref() == payload);
    if !hit {
        *cache = Some(BroadcastFrameCache {
            id,
            payload: payload.into(),
            frame: connection_limits::SharedBroadcastFrame::new(id, payload),
        });
    }
    &mut cache.as_mut().expect("populated above").frame
}

/// `send_packet` for the broadcast loops: the per-recipient work — the
/// anti-cheat note and the pose-tracking `update_packet` gate — still runs on
/// every client exactly as before, so a gate suppression or a per-client
/// rewrite (a `0x70` teleport becoming a relative move this one recipient
/// tracks differently) stays byte-identical to the old per-client send. Only
/// the framing changes: a packet that crosses the gate unmodified writes the
/// broadcast's shared `SharedBroadcastFrame`, encoding and compressing once
/// for the whole fanout rather than once per recipient.
fn send_broadcast_frame(
    s: &mut TcpStream,
    cache: &mut Option<BroadcastFrameCache>,
    mut id: i64,
    payload: &[u8],
) -> std::io::Result<()> {
    if id == 0x5a {
        // SetEntityMotion: whatever the server (or a mod acting through it) launches a
        // player with is movement the anti-cheat must allow for.
        let mut body = payload;
        if let Some(eid) = read_varint(&mut body) {
            if body.len() >= 6 {
                let axis = |i: usize| f64::from(i16::from_be_bytes([body[i], body[i + 1]])) / 8000.0;
                ac_note_server_velocity(eid as i32, [axis(0), axis(2), axis(4)]);
            }
        }
    }
    let mut send = true;
    let mut rewritten: Option<Vec<u8>> = None;
    let (compression, queued) = wire_state(socket_key(s)).map(|state| {
        let mut state = state.lock().unwrap_or_else(|e| e.into_inner());
        if let Some(play) = &mut state.play {
            let mut wire_id = id;
            let mut scratch = payload.to_vec();
            send = play.update_packet(
                &mut wire_id,
                &mut scratch,
                TICK_IDX.load(Ordering::Relaxed),
            );
            if wire_id != id || scratch.as_slice() != payload {
                id = wire_id;
                rewritten = Some(scratch);
            }
        }
        let queued = if send && state.tx_queue.is_some() {
            if let Some(payload) = &rewritten {
                let mut body = Vec::with_capacity(payload.len() + 5);
                write_varint(&mut body, id);
                body.extend_from_slice(payload);
                queue_play_owned_frame(&state, encoded_frame(&body, state.compression))
            } else {
                queue_play_frame(
                    &state,
                    broadcast_frame(cache, id, payload).frame_for(state.compression),
                )
            }
        } else {
            None
        };
        (state.compression, queued)
    }).unwrap_or((None, None));
    if !send {
        return Ok(());
    }
    if let Some(result) = queued {
        return queued_send_result(s, result);
    }
    if let Some(payload) = rewritten {
        let mut body = Vec::with_capacity(payload.len() + 5);
        write_varint(&mut body, id);
        body.extend_from_slice(&payload);
        return write_frame(s, &body, compression);
    }
    let frame = broadcast_frame(cache, id, payload).frame_for(compression);
    write_raw_frame_arc(s, frame)
}

/// A START_DESTROY_BLOCK the client has not cancelled. Vanilla survival mining
/// advances on the server (`ServerPlayerGameMode.tick` accumulates destroy
/// progress and breaks the block when it reaches the dig duration); the finish
/// packet a client sends only predicts the same event, so the stored duration
/// here is the completion trigger. `state` pins the block the dig was computed
/// for — if the cell changed underneath, the dig is abandoned instead.
#[derive(Clone, Copy)]
struct PendingDig {
    pos: DimBlockPos,
    state: u32,
    start_tick: u64,
    seconds: f32,
    /// The last crack stage broadcast to viewers (`-1` = none yet) —
    /// vanilla `destroyBlockProgress` emits only on stage changes.
    last_stage: i8,
}

/// Mining acceptance follows simulated server ticks, even if wall-clock time
/// advances while the server is stalled. The 70% tolerance is for early client
/// FINISH packets, while server-driven completion uses the full duration.
fn dig_required_ticks(seconds: f32, fraction: f64) -> u64 {
    (f64::from(seconds.max(0.0)) * 20.0 * fraction).ceil() as u64
}

fn dig_min_ticks(seconds: f32) -> u64 {
    dig_required_ticks(seconds, 0.7)
}

/// The one canonical pose-aware eye Y for every dig/place/attack reach and
/// underwater check: `player_eye_height_at` resolves standing `1.62`,
/// sneaking `1.27` and the `0.40` crawl/swim/fall-fly pose from the
/// client's flags and the collision shapes that would force the 1x1 pose.
/// A hardcoded `py + 1.62` rejects real 1x1-trapdoor branch mining.
fn client_eye_y(me: &Client, dim: DimId, px: f64, py: f64, pz: f64) -> f64 {
    let sneaking = *me.sneaking.lock().unwrap_or_else(|e| e.into_inner());
    let fall_fly = *me.fall_fly.lock().unwrap_or_else(|e| e.into_inner());
    let sprinting = *me.sprinting.lock().unwrap_or_else(|e| e.into_inner());
    // `Player.updateSwimming`: the swim flag is `isSprinting && isInWater`.
    let swimming =
        sprinting && aabb_in_water_dim(dim, player_bounding_box(px, py, pz, false, false));
    py + f64::from(player_eye_height_at(
        dim, px, py, pz, sneaking, fall_fly, swimming,
    ))
}

/// A queued `use_on` resend: `(dim, x, y, z, tick)` of the clicked cell.
type UseOnResend = Mutex<Option<(DimId, i32, i32, i32, i64)>>;

struct Client {
    eid: i32,
    uuid: [u8; 16],
    name: String,
    player_attack_damage_id: Option<i32>,
    pos: Mutex<(f64, f64, f64, f32, f32, bool)>,
    teleport: Mutex<connection_limits::TeleportSync>,
    hp: Mutex<f32>,
    sock: Mutex<TcpStream>,
    inv: Mutex<HashMap<i16, Stack>>,
    cursor: Mutex<Stack>,
    drag: Mutex<(i32, Vec<i16>)>, // (button, painted window slots) for click-mode 5
    open_chest: Mutex<Option<(ContainerKey, Option<ContainerKey>)>>, // (key, double-chest partner)
    chest_sync: Mutex<Option<ChestSyncState>>,
    open_furnace: Mutex<Option<DimBlockPos>>,
    craft: Mutex<HashMap<i16, Stack>>,
    craft9: Mutex<HashMap<i16, Stack>>,
    open_table: Mutex<bool>,
    // Legacy fields still initialized by the synthetic client fixtures.
    #[cfg(test)]
    #[allow(dead_code)]
    open_merchant: Mutex<bool>,
    #[cfg(test)]
    #[allow(dead_code)]
    trade_sel: Mutex<i32>,
    #[cfg(test)]
    #[allow(dead_code)]
    merchant_in: Mutex<[Stack; 2]>,
    bow_draw: Mutex<Option<Instant>>,
    dig: Mutex<Option<PendingDig>>,
    eat_start: Mutex<Option<Instant>>,
    blocking: Mutex<bool>,
    sprinting: Mutex<bool>,
    sneaking: Mutex<bool>,
    last_melee: Mutex<Instant>,
    fall_fly: Mutex<bool>,
    invulnerable: Mutex<i32>, // vanilla LivingEntity.invulnerableTime, in server ticks
    last_hurt: Mutex<f32>,    // vanilla LivingEntity.lastHurt: the last accepted damage
    shield_cd: Mutex<Instant>,
    absorb: Mutex<f32>,
    pearl_cd: Mutex<Instant>,
    xp: Mutex<i64>,
    skin: Mutex<Option<(String, String)>>, // textures (value, signature) resolved from Mojang
    seen: Mutex<HashSet<i32>>,             // entity ids currently spawned for this client
    chunks: Mutex<HashSet<(i32, i32)>>,    // chunks the client currently holds
    chunk_ack: Mutex<ChunkFeedback>,       // chunk batch pacing: the client's requested rate
    gen_sources: Mutex<GenSources>, // generated light emitters per held chunk, for the light pass
    gm: Mutex<u8>,                  // 0=survival 1=creative 3=spectator
    fall_from: Mutex<f64>,
    food: Mutex<i32>,
    air: Mutex<i32>,
    armor_pts: Mutex<i32>,
    sat: Mutex<f32>,
    walk_acc: Mutex<f64>,
    lastp: Mutex<(f64, f64, f64)>,
    spawn_pt: Mutex<Option<(f64, f64, f64, f32)>>,
    // P2-3-S4: a player lives in one dimension at a time. Every dimension-scoped
    // audience filter (chunks, block deltas, entity visibility) reads this, and a
    // 0x47 Respawn flips it together with the chunk window. The saved spawn point
    // carries its own dimension so death respawn returns the player to the right
    // world even when they died in another one.
    dim: Mutex<DimId>,
    // The client's effective view distance, mirrored from the connection so commands and
    // portals can rebuild a window of the same size without a stream reference.
    view: Mutex<i32>,
    spawn_dim: Mutex<DimId>,
    // Set while the client is standing inside a portal block. Cleared on arrival
    // in the destination so the freshly-materialised return portal does not bounce
    // the player straight back (a per-player, not per-block, guard).
    in_portal: Mutex<bool>,
    portal_at: Mutex<Option<Instant>>,
    held: Mutex<i16>,
    effs: Mutex<Vec<Eff>>,
    // The `megu:lod_v1` opt-in from the client's `minecraft:register`
    // payload. Vanilla clients never set it and must never receive a `lod_v1`
    // packet, so the flag is checked before every channel write.
    lod_v1_enabled: AtomicBool,
    // Anti-xray lane hysteresis: `true` while the player is underground enough
    // to see real chunks, `false` while they get the surface-occluded lane.
    // Flipped by `update_underground_lane`, which re-sends held chunks.
    underground_revealed: AtomicBool,
    // `Some` while the player lies in a bed; `sleep_tick` ages it and clears it
    // on wake, damage or a completed night skip.
    sleeping: Mutex<Option<Sleeping>>,
    // Window-0/container stateId counter: every server-initiated full-content
    // resync bumps it so a stale client echo on 0x0e can be detected.
    inv_state_id: AtomicI32,
    // `handleUseItemOn` resends `ClientboundBlockUpdatePacket` for the clicked
    // cell and `clicked + face` at the end of every use_on; the next queued
    // flush emits them so they carry post-write states like vanilla's tail.
    use_on_resend: UseOnResend,
}

// Per-player bed occupancy: the bed position, game ticks slept so far and the
// `last_hurt` watermark at sleep entry so damage wakes the player.
#[derive(Clone, Copy)]
struct Sleeping {
    bed: (i32, i32, i32),
    ticks: u32,
    last_hurt: f32,
}

impl Client {
    fn enter_play_wire(
        &self,
        compression: Option<usize>,
        chunk_delivery: connection_limits::ChunkDelivery,
    ) -> bool {
        // Some synthetic clients have no reader/handler for a failed socket.
        // Log the setup error here while allowing their existing call sites
        // to ignore the status; the real connection handler checks it.
        match self.try_enter_play_wire(compression, chunk_delivery) {
            Ok(()) => true,
            Err(error) => {
                eprintln!("[spine] {} play writer setup failed: {error}", self.name);
                false
            }
        }
    }

    fn try_enter_play_wire(
        &self,
        compression: Option<usize>,
        chunk_delivery: connection_limits::ChunkDelivery,
    ) -> std::io::Result<()> {
        let (key, mut stream) = {
            let socket = self.sock.lock().unwrap_or_else(|e| e.into_inner());
            (socket_key(&socket), socket.try_clone()?)
        };
        // The Play writer uses its own fd. Login/config and initial Join Game
        // have already been synchronously sent on the original socket.
        stream.set_write_timeout(Some(Duration::from_secs(2)))?;
        let queue = Arc::new(connection_limits::ClientTxQueue::default());
        let writer_queue = Arc::clone(&queue);
        let name = self.name.clone();
        let writer = std::thread::Builder::new()
            .name(format!("spine-tx-{}", self.eid))
            .spawn(move || {
                if let Err(error) = writer_queue.writer_loop(&mut stream) {
                    eprintln!("[spine] {name} writer failed: {error}");
                    writer_queue.close();
                    // A partial encrypted write invalidates the socket stream.
                    // Wake the read loop so its normal cleanup path runs.
                    let _ = stream.shutdown(std::net::Shutdown::Both);
                }
            })?;
        let state = wire_state_or_insert(key);
        // Merge, not overwrite: the encryption handshake may have armed a
        // cipher on this writer fd before the play state existed.
        let mut state = state.lock().unwrap_or_else(|e| e.into_inner());
        state.compression = compression;
        state.play = Some(PlayWireState {
            chunk_delivery,
            ..PlayWireState::default()
        });
        state.tx_queue = Some(queue);
        state.tx_writer = Some(writer);
        Ok(())
    }

    /// Closing keeps queued Play Disconnect packets ahead of writer shutdown;
    /// joining here ensures no detached per-client writer survives teardown.
    fn close_play_writer(&self) {
        let key = {
            let socket = self.sock.lock().unwrap_or_else(|e| e.into_inner());
            socket_key(&socket)
        };
        let (queue, writer) = {
            match wire_state(key) {
                Some(state) => {
                    let mut state = state.lock().unwrap_or_else(|e| e.into_inner());
                    (state.tx_queue.clone(), state.tx_writer.take())
                }
                None => (None, None),
            }
        };
        if let Some(queue) = queue {
            queue.close();
        }
        let socket = self.sock.lock().unwrap_or_else(|e| e.into_inner());
        shutdown_and_join_writer(&socket, writer, &self.name);
    }

    fn is_spectator(&self) -> bool {
        *self.gm.lock().unwrap_or_else(|e| e.into_inner()) == 3
    }
    fn touch_aabb(&self) -> EntityAabb {
        let (px, py, pz, ..) = *self.pos.lock().unwrap_or_else(|e| e.into_inner());
        let sneaking = *self.sneaking.lock().unwrap_or_else(|e| e.into_inner());
        let fall_fly = *self.fall_fly.lock().unwrap_or_else(|e| e.into_inner());
        player_touch_aabb(px, py, pz, sneaking, fall_fly)
    }
}

impl std::ops::Drop for Client {
    fn drop(&mut self) {
        // Also covers early exits before the online-client cleanup guard exists.
        self.close_play_writer();
        ac_forget(self.eid);
        let socket = self.sock.get_mut().unwrap_or_else(|e| e.into_inner());
        unregister_socket_wire(socket_key(socket));
    }
}
static CLIENTS: OnceLock<Mutex<Vec<Arc<Client>>>> = OnceLock::new();
const PLAYER_ENTITY_TYPE: i64 = 128; // minecraft:player in 1.21.1
static NEXT_EID: AtomicI32 = AtomicI32::new(1000);
fn clients() -> &'static Mutex<Vec<Arc<Client>>> {
    CLIENTS.get_or_init(|| Mutex::new(Vec::new()))
}

/// The entity ids whose login identity the server verified (online-mode session
/// check or Velocity forwarding). Login stamps the mark; every disconnect path
/// clears it. An unmarked client is an offline-mode claim: permission lookups
/// on it must never let a stored UUID be overruled by a name collision.
fn authenticated_players() -> &'static Mutex<HashSet<i32>> {
    static AUTHENTICATED: OnceLock<Mutex<HashSet<i32>>> = OnceLock::new();
    AUTHENTICATED.get_or_init(|| Mutex::new(HashSet::new()))
}
fn mark_authenticated(eid: i32) {
    authenticated_players()
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .insert(eid);
}
fn authenticated_player(eid: i32) -> bool {
    authenticated_players()
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .contains(&eid)
}
enum AngleRounding {
    Floor,
    Truncate,
}

// 1.21.1 packet constructors have distinct rounding policies. Narrow through
// Java's int boundary before the wrapping byte conversion, including overflow.
fn angle_byte(scaled: f64, rounding: AngleRounding) -> i8 {
    let value = scaled as i32; // Java's saturating floating-point -> int conversion.
    let value = if matches!(rounding, AngleRounding::Floor) && scaled < f64::from(value) {
        value.wrapping_sub(1) // Mth.floor also wraps below Integer.MIN_VALUE.
    } else {
        value
    };
    value as i8 // Java int -> byte wraps; a direct Rust float -> i8 saturates.
}
fn angle(deg: f32) -> i8 {
    angle_byte(f64::from(deg * 256.0 / 360.0), AngleRounding::Floor)
}
fn teleport_angle(deg: f32) -> i8 {
    // ClientboundTeleportEntityPacket (afw) uses f2i, not Mth.floor.
    angle_byte(f64::from(deg * 256.0 / 360.0), AngleRounding::Truncate)
}
fn spawn_angles(out: &mut Vec<u8>, yaw: f32, pitch: f32) {
    // ClientboundAddEntityPacket (abv): body uses f32, head uses f64.
    out.extend_from_slice(&[
        angle(pitch) as u8,
        angle(yaw) as u8,
        angle_byte(f64::from(yaw) * 256.0 / 360.0, AngleRounding::Floor) as u8,
    ]);
}

// Bounded: one entry per distinct name an (unauthenticated) client logs in
// with would otherwise grow forever, and each miss costs two outbound requests.
const SKIN_CACHE_CAP: usize = 1024;
const SKIN_TTL_HIT: Duration = Duration::from_secs(60 * 60);
const SKIN_TTL_MISS: Duration = Duration::from_secs(5 * 60);
/// Concurrent outbound lookups (and lookup threads); a login whose name is not
/// cached while this many are in flight simply goes without a skin.
const SKIN_LOOKUPS_MAX: usize = 4;
static SKIN_INFLIGHT: AtomicUsize = AtomicUsize::new(0);
type SkinEntry = (Instant, Option<(String, String)>);
static SKIN_CACHE: OnceLock<Mutex<HashMap<String, SkinEntry>>> = OnceLock::new();
fn skin_cache() -> &'static Mutex<HashMap<String, SkinEntry>> {
    SKIN_CACHE.get_or_init(|| Mutex::new(HashMap::new()))
}
fn skin_entry_fresh(e: &SkinEntry, now: Instant) -> bool {
    let ttl = if e.1.is_some() {
        SKIN_TTL_HIT
    } else {
        SKIN_TTL_MISS
    };
    now.saturating_duration_since(e.0) < ttl
}
/// Fresh cached result for `key` (outer `None` = not cached or expired).
fn skin_cache_get(
    c: &HashMap<String, SkinEntry>,
    key: &str,
    now: Instant,
) -> Option<Option<(String, String)>> {
    c.get(key)
        .filter(|e| skin_entry_fresh(e, now))
        .map(|e| e.1.clone())
}
/// Insert, keeping at most `cap` entries: expired ones go first, then the oldest.
fn skin_cache_put(
    c: &mut HashMap<String, SkinEntry>,
    key: String,
    res: Option<(String, String)>,
    now: Instant,
    cap: usize,
) {
    if c.len() >= cap && !c.contains_key(&key) {
        c.retain(|_, e| skin_entry_fresh(e, now));
        while c.len() >= cap {
            let Some(oldest) = c.iter().min_by_key(|(_, e)| e.0).map(|(k, _)| k.clone()) else {
                break;
            };
            c.remove(&oldest);
        }
    }
    c.insert(key, (now, res));
}
fn load_skin_properties(name: &str) -> Option<(String, String)> {
    // offline-mode skin resolution: name -> uuid -> session profile textures
    let agent: ureq::Agent = ureq::Agent::config_builder()
        .timeout_global(Some(Duration::from_secs(6)))
        .build()
        .into();
    let prof = agent
        .get(format!(
            "https://api.mojang.com/users/profiles/minecraft/{}",
            name
        ))
        .call()
        .ok()?
        .body_mut()
        .with_config()
        .limit(1 << 20)
        .read_to_string()
        .ok()?;
    let id = jstr(&prof, "id")?.to_string();
    let full = agent
        .get(format!(
            "https://sessionserver.mojang.com/session/minecraft/profile/{}?unsigned=false",
            id
        ))
        .call()
        .ok()?
        .body_mut()
        .with_config()
        .limit(1 << 20)
        .read_to_string()
        .ok()?;
    let value = jstr(&full, "value")?.to_string();
    let signature = jstr(&full, "signature")?.to_string();
    Some((value, signature))
}
/// Give `t` its resolved textures and re-announce it so connected viewers see them.
fn apply_skin(t: &Arc<Client>, res: Option<(String, String)>) {
    if let Some((v, sig)) = res {
        *t.skin.lock().unwrap_or_else(|e| e.into_inner()) = Some((v.clone(), sig.clone()));
        // re-add player info so already-connected viewers pick up the skin
        let cs = clients().lock().unwrap_or_else(|e| e.into_inner());
        if !cs.iter().any(|c| Arc::ptr_eq(c, t)) {
            return;
        }
        let pi = player_info_add(t);
        for c in cs.iter() {
            let _ = send_packet(&mut c.sock.lock().unwrap_or_else(|e| e.into_inner()), 0x3e, pi.clone());
        }
    }
}
struct SkinLookupSlot;
impl SkinLookupSlot {
    fn try_acquire() -> Option<Self> {
        if SKIN_INFLIGHT.fetch_add(1, Ordering::SeqCst) < SKIN_LOOKUPS_MAX {
            Some(SkinLookupSlot)
        } else {
            SKIN_INFLIGHT.fetch_sub(1, Ordering::SeqCst);
            None
        }
    }
}
impl std::ops::Drop for SkinLookupSlot {
    fn drop(&mut self) {
        SKIN_INFLIGHT.fetch_sub(1, Ordering::SeqCst);
    }
}
fn kick_skin(name: String, target: &Arc<Client>) {
    // Mojang names are case-insensitive; one cache entry per name, not per spelling.
    let key = name.to_ascii_lowercase();
    let hit = skin_cache_get(&skin_cache().lock().unwrap_or_else(|e| e.into_inner()), &key, Instant::now());
    if let Some(res) = hit {
        apply_skin(target, res);
        return;
    }
    // Not cached: at most SKIN_LOOKUPS_MAX lookups (and threads) at a time.
    let Some(slot) = SkinLookupSlot::try_acquire() else {
        return;
    };
    let t = target.clone();
    thread::spawn(move || {
        let _slot = slot;
        let r = load_skin_properties(&name);
        skin_cache_put(
            &mut skin_cache().lock().unwrap_or_else(|e| e.into_inner()),
            key,
            r.clone(),
            Instant::now(),
            SKIN_CACHE_CAP,
        );
        apply_skin(&t, r);
    });
}
fn player_info_add(c: &Client) -> Vec<u8> {
    // actions: add_player|update_game_mode|update_listed|update_latency = 0x1d
    let mut p = vec![0x1du8];
    write_varint(&mut p, 1);
    p.extend_from_slice(&c.uuid);
    write_str(&mut p, &c.name);
    let skin = c.skin.lock().unwrap_or_else(|e| e.into_inner()).clone();
    if let Some((v, sig)) = skin {
        write_varint(&mut p, 1);
        write_str(&mut p, "textures");
        write_str(&mut p, &v);
        p.push(1); // signed
        write_str(&mut p, &sig);
    } else {
        write_varint(&mut p, 0); // properties
    }
    write_varint(&mut p, 1); // gamemode creative
    write_varint(&mut p, 1); // listed
    write_varint(&mut p, 0); // latency
    p
}

/// S2C `ClientboundPlayerInfoRemovePacket` (`0x3d`): a VarInt count followed
/// by the UUIDs whose tab-list entries are removed.
fn player_info_remove_pkt(uuids: &[[u8; 16]]) -> Vec<u8> {
    let mut p = Vec::with_capacity(5 + uuids.len() * 16);
    write_varint(&mut p, uuids.len() as i64);
    for uuid in uuids {
        p.extend_from_slice(uuid);
    }
    p
}
fn spawn_player(c: &Client) -> Vec<u8> {
    let (x, y, z, yaw, pitch, _g) = *c.pos.lock().unwrap_or_else(|e| e.into_inner());
    let mut p = Vec::new();
    write_varint(&mut p, c.eid as i64);
    p.extend_from_slice(&c.uuid);
    write_varint(&mut p, PLAYER_ENTITY_TYPE);
    p.extend_from_slice(&x.to_be_bytes());
    p.extend_from_slice(&y.to_be_bytes());
    p.extend_from_slice(&z.to_be_bytes());
    spawn_angles(&mut p, yaw, pitch);
    write_varint(&mut p, 0);
    p.extend_from_slice(&[0u8; 6]); // velocity
    p
}
#[allow(dead_code)]
fn arrow_meta(eid: i32) -> Vec<u8> {
    let mut p = Vec::new();
    write_varint(&mut p, eid as i64);
    p.push(0xff);
    p
}
fn entity_teleport(eid: i32, x: f64, y: f64, z: f64, yaw: f32, pitch: f32, g: bool) -> Vec<u8> {
    let mut p = Vec::new();
    write_varint(&mut p, eid as i64);
    p.extend_from_slice(&x.to_be_bytes());
    p.extend_from_slice(&y.to_be_bytes());
    p.extend_from_slice(&z.to_be_bytes());
    p.push(teleport_angle(yaw) as u8);
    p.push(teleport_angle(pitch) as u8);
    p.push(g as u8);
    p
}
fn head_rot(eid: i32, yaw: f32) -> Vec<u8> {
    connection_limits::entity_head_rotation(eid, angle(yaw) as u8)
}
// LOCK ORDER: acquires clients() internally — the caller must NOT
// hold clients().lock() (self-deadlock). Per-client field locks are
// fine: the client list is snapshotted before any field is touched.
/// Snapshot the client list and release the lock before handing it back. Every
/// caller must come through here, because sending while holding `clients()`
/// self-deadlocks: the send paths acquire it themselves. That was hit twice
/// before the rule was written down, so the rule is a function rather than a
/// comment that the next caller has to find.
fn client_snapshot() -> Vec<Arc<Client>> {
    clients().lock().unwrap_or_else(|e| e.into_inner()).iter().cloned().collect()
}

/// Send one packet to every client the predicate accepts. The snapshot is taken
/// before any send, so the lock order above is structural rather than remembered.
/// The audience is a parameter, not a global read: the four broadcast helpers
/// are pinned by a test that hands them its own three clients, and that test
/// asserts that the *other* clients receive nothing. While the audience came
/// from `clients()`, any test running beside it that broadcast to the global
/// list wrote into those sockets and broke the negative assertions - measured
/// once in four eight-thread runs (`fanout_tests`, 68 bytes on the sender).
fn fanout_in<F, P>(audience: &[Arc<Client>], interested: P, mk: F)
where
    F: Fn(&Client) -> (i64, Vec<u8>),
    P: Fn(&Client) -> bool,
{
    let mut shared = None;
    fanout_shared_in(audience, interested, mk, &mut shared);
}

/// `fanout_in` with the broadcast's frame cache handed in rather than owned:
/// production callers pass a fresh `None`; a test keeps the cache afterwards
/// and reads `frame.encode_count()`, the direct proof that a fanout encoded
/// once for every identical packet instead of once per recipient.
fn fanout_shared_in<F, P>(
    audience: &[Arc<Client>],
    interested: P,
    mk: F,
    shared: &mut Option<BroadcastFrameCache>,
) where
    F: Fn(&Client) -> (i64, Vec<u8>),
    P: Fn(&Client) -> bool,
{
    for c in audience.iter() {
        if !interested(c) {
            continue;
        }
        let (id, packet) = mk(c);
        if let Ok(mut w) = c.sock.lock() {
            let _ = send_broadcast_frame(&mut w, shared, id, &packet);
        }
    }
}

/// Fan out one already-built payload without cloning it for each recipient.
/// The broadcast frame cache still handles each wire compression class once.
fn fanout_packet_in<P>(
    audience: &[Arc<Client>],
    interested: P,
    id: i64,
    packet: &[u8],
    shared: &mut Option<BroadcastFrameCache>,
) where
    P: Fn(&Client) -> bool,
{
    for c in audience.iter() {
        if !interested(c) {
            continue;
        }
        if let Ok(mut w) = c.sock.lock() {
            let _ = send_broadcast_frame(&mut w, shared, id, packet);
        }
    }
}

fn broadcast_packet(me_eid: i32, id: i64, packet: &[u8]) {
    let audience = client_snapshot();
    let mut shared = None;
    fanout_packet_in(&audience, |c| c.eid != me_eid, id, packet, &mut shared);
}

fn broadcast_seen_packet(eid: i32, id: i64, packet: &[u8]) {
    broadcast_seen_ex_packet(eid, 0, id, packet)
}

fn broadcast_seen_ex_packet(eid: i32, excl: i32, id: i64, packet: &[u8]) {
    let audience = client_snapshot();
    let mut shared = None;
    for client in audience.iter().filter(|c| c.eid != excl) {
        let seen = client.seen.lock().unwrap_or_else(|e| e.into_inner());
        if seen.contains(&eid) {
            if let Ok(mut socket) = client.sock.lock() {
                let _ = send_broadcast_frame(&mut socket, &mut shared, id, packet);
            }
        }
    }
}

fn broadcast<F: Fn(&Client) -> (i64, Vec<u8>)>(me_eid: i32, mk: F) {
    broadcast_in(&client_snapshot(), me_eid, mk)
}

/// The next container stateId for windows tracked by `inv_state_id`, wrapping
/// like vanilla `AbstractContainerMenu.incrementStateId` (`& 0x7fff`).
fn inv_state_next(me: &Client) -> i32 {
    (me.inv_state_id.fetch_add(1, Ordering::Relaxed) + 1) & 0x7fff
}

/// Whether the stateId the client echoed on `0x0e` no longer matches the
/// authoritative counter for `wid`. Unknown windows are not validated.
fn container_state_stale(me: &Client, wid: u8, click_state_id: i32) -> bool {
    let expected = match wid {
        0 | 2 | 3 => me.inv_state_id.load(Ordering::Relaxed),
        1 => me
            .chest_sync
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .as_ref()
            .map_or(0, |sync| sync.state_id),
        _ => return false,
    };
    click_state_id != expected
}

/// Full `0x13` SetContainerContent resync after a stale stateId click: the
/// authoritative counter advances and every slot is resent, so the client and
/// server re-agree instead of drifting apart.
fn resend_container_content(me: &Client, wid: u8) {
    let inv = me.inv.lock().unwrap_or_else(|e| e.into_inner()).clone();
    let cursor = me.cursor.lock().unwrap_or_else(|e| e.into_inner()).clone();
    let empty = Stack::default();
    let mut q = vec![wid];
    match wid {
        0 => {
            write_varint(&mut q, i64::from(inv_state_next(me)));
            write_varint(&mut q, 46);
            for slot in 0..46i16 {
                q.extend_from_slice(&slot_wire(inv.get(&slot).unwrap_or(&empty)));
            }
        }
        1 => {
            let Some(window) = *me.open_chest.lock().unwrap_or_else(|e| e.into_inner()) else {
                return;
            };
            let slots = chest_window_slots(window);
            let state_id = {
                let mut sync = me.chest_sync.lock().unwrap_or_else(|e| e.into_inner());
                let sync = sync.get_or_insert_with(|| ChestSyncState {
                    window,
                    anchor: None,
                    state_id: 0,
                    last_slots: slots.clone(),
                });
                sync.state_id = (sync.state_id + 1) & 0x7fff;
                sync.last_slots = slots.clone();
                sync.state_id
            };
            write_varint(&mut q, i64::from(state_id));
            write_varint(&mut q, (slots.len() + 36) as i64);
            for stack in &slots {
                q.extend_from_slice(&slot_wire(stack));
            }
            for slot in 9..45i16 {
                q.extend_from_slice(&slot_wire(inv.get(&slot).unwrap_or(&empty)));
            }
        }
        2 => {
            let Some((dim, x, y, z)) = *me.open_furnace.lock().unwrap_or_else(|e| e.into_inner()) else {
                return;
            };
            write_varint(&mut q, i64::from(inv_state_next(me)));
            write_varint(&mut q, 39);
            for stack in furnace_slot_snapshot_dim(dim, (x, y, z)) {
                q.extend_from_slice(&slot_wire(&stack));
            }
            for slot in 3..39i16 {
                q.extend_from_slice(&slot_wire(inv.get(&(slot + 6)).unwrap_or(&empty)));
            }
        }
        3 => {
            let craft9 = me.craft9.lock().unwrap_or_else(|e| e.into_inner()).clone();
            write_varint(&mut q, i64::from(inv_state_next(me)));
            write_varint(&mut q, 46);
            let result = json_craft_match(&craft9, 3).unwrap_or_default();
            q.extend_from_slice(&slot_wire(&result));
            for slot in 1..=9i16 {
                q.extend_from_slice(&slot_wire(craft9.get(&slot).unwrap_or(&empty)));
            }
            for slot in 10..46i16 {
                q.extend_from_slice(&slot_wire(inv.get(&(slot - 1)).unwrap_or(&empty)));
            }
        }
        _ => return,
    }
    q.extend_from_slice(&slot_wire(&cursor));
    if let Ok(mut w) = me.sock.lock() {
        let _ = send_packet(&mut w, 0x13, q);
    }
}

/// Click-mode 5 (vanilla drag paint): button 0/4 begins a left/right drag,
/// 1/5 records a painted window slot, 2/6 ends the drag and distributes the
/// carried stack across the recorded slots.
fn drag_paint_click(me: &Client, slot: i16, button: i32) {
    let mut dr = me.drag.lock().unwrap_or_else(|e| e.into_inner());
    match button {
        0 | 4 => {
            dr.0 = button;
            dr.1.clear();
        }
        1 | 5 => {
            if dr.0 >= 0 && dr.0 + 1 == button && !dr.1.contains(&slot) {
                dr.1.push(slot);
            }
        }
        2 | 6 if dr.0 >= 0 && dr.0 + 2 == button => {
            let slots_taken = std::mem::take(&mut dr.1);
            dr.0 = -1;
            drop(dr);
            let mut cur = me.cursor.lock().unwrap_or_else(|e| e.into_inner());
            if cur.1 > 0 && !slots_taken.is_empty() {
                let right = dr_btn_right(button);
                // vanilla right-drag paints exactly 1 item per slot, and can
                // never consume more slots than the cursor holds
                let per = if right {
                    1
                } else {
                    (cur.1 as usize / slots_taken.len()) as u8
                };
                if per > 0 {
                    let slots_taken = if right {
                        slots_taken[..slots_taken.len().min(cur.1 as usize)].to_vec()
                    } else {
                        slots_taken
                    };
                    for wsl in slots_taken {
                        if cur.1 == 0 {
                            break;
                        }
                        paint_slot(me, wsl, per, &mut cur);
                    }
                    if cur.1 == 0 {
                        *cur = (0, 0, Vec::new());
                    }
                }
            }
        }
        _ => {}
    }
}

/// Entity metadata for pose 6 (`SLEEPING`) + LivingEntity's optional sleeping
/// bed position at index 14. Vanilla broadcasts the full entity data on pose
/// changes; for parity of the sleep animation these two entries suffice.
fn sleep_meta_pkt(eid: i32, sleeping: bool, bed: (i32, i32, i32)) -> Vec<u8> {
    let mut p = Vec::new();
    write_varint(&mut p, i64::from(eid));
    p.push(6);
    p.push(21); // POSE
    write_varint(&mut p, if sleeping { 2 } else { 0 });
    p.push(14); // SLEEPING_POS_ID
    p.push(27); // OPTIONAL_POSITION
    p.push(u8::from(sleeping));
    if sleeping {
        write_pos(&mut p, bed.0, bed.1, bed.2);
    }
    p.push(0xff);
    p
}

fn broadcast_sleep_pose(me: &Client, sleeping: bool, bed: (i32, i32, i32)) {
    let pkt = sleep_meta_pkt(me.eid, sleeping, bed);
    broadcast_seen_packet(me.eid, 0x58, &pkt);
}

/// Wake the player if they are in a bed: clear the state and restore the pose
/// for observers. Returns true when the player was sleeping.
fn wake_if_sleeping(me: &Client) -> bool {
    if let Some(state) = me.sleeping.lock().unwrap_or_else(|e| e.into_inner()).take() {
        broadcast_sleep_pose(me, false, state.bed);
        true
    } else {
        false
    }
}

/// Vanilla `ServerLevel.wakeUpAllPlayers` + `advanceWeatherCycle` on the night
/// skip: jump to the next morning, clear rain/thunder and wake every sleeper.
fn skip_night() {
    let day = WORLD_TIME.load(Ordering::Relaxed).div_euclid(24000);
    let morning = (day + 1) * 24000;
    WORLD_TIME.store(morning, Ordering::Relaxed);
    // `RAINING`/`THUNDERING` count the remaining ticks of weather.
    RAINING.store(0, Ordering::Relaxed);
    THUNDERING.store(0, Ordering::Relaxed);
    let sleepers: Vec<Arc<Client>> = client_snapshot()
        .into_iter()
        .filter(|c| c.sleeping.lock().unwrap_or_else(|e| e.into_inner()).is_some())
        .collect();
    let mut tm = Vec::new();
    tm.extend_from_slice(&0i64.to_be_bytes());
    tm.extend_from_slice(&morning.to_be_bytes());
    let mut rain = vec![2u8]; // END_RAINING
    rain.extend_from_slice(&0f32.to_be_bytes());
    for sleeper in sleepers {
        let bed = sleeper.sleeping.lock().unwrap_or_else(|e| e.into_inner()).take().map_or((0, 0, 0), |s| s.bed);
        broadcast_sleep_pose(&sleeper, false, bed);
        if let Ok(mut w) = sleeper.sock.lock() {
            let _ = send_packet(&mut w, 0x64, tm.clone());
            let _ = send_packet(&mut w, 0x22, rain.clone());
        }
        let line = system_chat(&format!("{} slept through the night", sleeper.name));
        broadcast_packet(-1, 0x6c, &line);
    }
}

/// One server tick of sleep bookkeeping: wake on fresh damage, age every
/// sleeper, then run vanilla's
/// `sleepingPlayers * 100 >= playersSleepingPercentage * allPlayers` gate once
/// at least one player has slept for 100 ticks.
fn sleep_tick() {
    let clients = client_snapshot();
    let mut any_ready = false;
    for c in &clients {
        let mut sl = c.sleeping.lock().unwrap_or_else(|e| e.into_inner());
        let Some(mut state) = *sl else {
            continue;
        };
        let last_hurt = *c.last_hurt.lock().unwrap_or_else(|e| e.into_inner());
        if last_hurt > state.last_hurt {
            let bed = state.bed;
            *sl = None;
            drop(sl);
            broadcast_sleep_pose(c, false, bed);
            continue;
        }
        state.ticks = state.ticks.saturating_add(1);
        if state.ticks >= 100 {
            any_ready = true;
        }
        *sl = Some(state);
    }
    if !any_ready {
        return;
    }
    // Vanilla counts everyone in the Overworld (awake or asleep) in the
    // denominator; `playersSleepingPercentage` > 100 can never be met.
    let (sleeping, all) = clients
        .iter()
        .filter(|c| *c.dim.lock().unwrap_or_else(|e| e.into_inner()) == DimId::Overworld)
        .fold((0i64, 0i64), |(s, a), c| {
            (s + i64::from(c.sleeping.lock().unwrap_or_else(|e| e.into_inner()).is_some()), a + 1)
        });
    if all == 0 {
        return;
    }
    let percentage = command_gamerules()
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .get("playersSleepingPercentage")
        .copied()
        .unwrap_or(100);
    // `0` means a single sleeper can skip the night once they are done lying
    // down; `> 100` disables sleep-skipping entirely.
    if sleeping > 0 && sleeping * 100 >= i64::from(percentage) * all {
        skip_night();
    }
}

/// Bed use at night: vanilla `startSleepInBed` — mark the player sleeping
/// (respawn was already set by the caller) and broadcast the pose change so
/// observers see the lying-down animation. Actual time travel happens in
/// `sleep_tick` after 100 slept ticks.
fn enter_bed(me: &Client, x: i32, y: i32, z: i32) {
    *me.sleeping.lock().unwrap_or_else(|e| e.into_inner()) = Some(Sleeping {
        bed: (x, y, z),
        ticks: 0,
        last_hurt: *me.last_hurt.lock().unwrap_or_else(|e| e.into_inner()),
    });
    broadcast_sleep_pose(me, true, (x, y, z));
}
fn broadcast_in<F: Fn(&Client) -> (i64, Vec<u8>)>(audience: &[Arc<Client>], me_eid: i32, mk: F) {
    fanout_in(audience, |c| c.eid != me_eid, mk)
}
struct TrackedSpawn {
    dim: DimId,
    range: u32,
    eid: i32,
    x: f64,
    z: f64,
    cx: i32,
    cz: i32,
    spawn: SpawnDescriptor,
}

/// Value form of the old per-tick `Box<dyn FnOnce>` spawn job. The descriptor is
/// built for every live entity every tick, but its packets are encoded only when
/// a client actually transitions from untracked to tracked.
enum SpawnDescriptor {
    Cart(generated_content::Cart),
    Frame(generated_content::Frame),
    Mob(Arc<Mob>),
    Projectile(LiveMobProjectile),
    Player(Arc<Client>),
    ItemDrop {
        eid: i32,
        x: f64,
        y: f64,
        z: f64,
        item: i64,
        cnt: u8,
        comps: Comps,
    },
    Falling {
        eid: i32,
        state: u32,
        x: f64,
        y: f64,
        z: f64,
    },
    ExperienceOrb {
        eid: i32,
        x: f64,
        y: f64,
        z: f64,
        val: i16,
    },
    Typed {
        eid: i32,
        etype: i64,
        x: f64,
        y: f64,
        z: f64,
    },
}

impl SpawnDescriptor {
    fn packets(&self) -> Vec<(i64, Vec<u8>)> {
        #[cfg(test)]
        SPAWN_DESCRIPTOR_MATERIALIZATIONS.with(|count| count.set(count.get() + 1));
        match self {
            Self::Cart(cart) => vec![(0x01, spawn_generated_cart(cart))],
            Self::Frame(frame) => vec![
                (0x01, spawn_generated_frame(frame)),
                (0x58, frame_meta_pkt(frame)),
            ],
            Self::Mob(mob) => {
                let mut packets = live_mob_spawn_packets(mob);
                // SetEquipment trails the spawn so a skeleton's bow or a
                // pillager's crossbow is visible from the first frame.
                if let Some(equipment) = mob_equipment_packet(mob) {
                    packets.push((0x5b, equipment));
                }
                packets
            }
            Self::Projectile(projectile) => {
                let mut packets = live_mob_projectile_packets(*projectile);
                // `ServerEntity.sendPairingData`: every tracked
                // `AbstractHurtingProjectile` carries a
                // `set_projectile_power` right after the spawn — the
                // vanilla `accelerationPower` default is 0.1.
                if matches!(
                    projectile.kind,
                    MobProjectileKind::SmallFireball
                        | MobProjectileKind::GhastFireball
                        | MobProjectileKind::DragonFireball
                        | MobProjectileKind::WitherSkull { .. }
                ) {
                    packets.push(encode_play_set_projectile_power(projectile.eid, 0.1));
                }
                packets
            }
            Self::Player(player) => {
                let mut packets = vec![(0x01, spawn_player(player))];
                // SetEquipment trails the spawn so an observer sees the
                // player's held item and armor from the first frame.
                if let Some(equipment) = player_equipment_packet(player) {
                    packets.push((0x5b, equipment));
                }
                packets
            }
            Self::ItemDrop {
                eid,
                x,
                y,
                z,
                item,
                cnt,
                comps,
            } => {
                let drop = Drop {
                    eid: *eid,
                    x: *x,
                    y: *y,
                    z: *z,
                    item: *item,
                    cnt: *cnt,
                    comps: comps.clone(),
                    age: 0,
                    target: None,
                    thrower: None,
                };
                vec![(0x01, spawn_drop_pkt(&drop)), (0x58, drop_meta_pkt(&drop))]
            }
            Self::Falling {
                eid,
                state,
                x,
                y,
                z,
            } => vec![(0x01, spawn_falling_pkt(*eid, *state, *x, *y, *z))],
            Self::ExperienceOrb { eid, x, y, z, val } => {
                let (id, body) = encode_play_add_experience_orb(*eid, *x, *y, *z, *val);
                debug_assert_eq!(body, xp_orb_pkt(*eid, *x, *y, *z, *val));
                vec![(id, body)]
            }
            Self::Typed {
                eid,
                etype,
                x,
                y,
                z,
            } => vec![(0x01, spawn_typed_pkt(*eid, *etype, *x, *y, *z))],
        }
    }
}

/// Entities grouped by the chunk cell `sync_entity_interest` tests for chunk
/// membership. `order` is the entity indices sorted by `(dim, cx, cz)` and
/// `ranges` maps each distinct cell to its slice inside `order`, so building the
/// index allocates two containers rather than a `Vec` per occupied chunk.
struct InterestChunkIndex {
    order: Vec<usize>,
    ranges: HashMap<(DimId, i32, i32), (usize, usize)>,
}

impl InterestChunkIndex {
    fn new(entities: &[TrackedSpawn]) -> Self {
        let mut order: Vec<usize> = (0..entities.len()).collect();
        order.sort_unstable_by_key(|&index| {
            let entity = &entities[index];
            (entity.dim, entity.cx, entity.cz)
        });
        let mut ranges = HashMap::new();
        let mut start = 0usize;
        while start < order.len() {
            let first = &entities[order[start]];
            let key = (first.dim, first.cx, first.cz);
            let mut end = start + 1;
            while end < order.len() {
                let entity = &entities[order[end]];
                if (entity.dim, entity.cx, entity.cz) != key {
                    break;
                }
                end += 1;
            }
            ranges.insert(key, (start, end));
            start = end;
        }
        Self { order, ranges }
    }
}

#[derive(Default)]
struct InterestSyncScratch {
    eligible: Vec<(i32, usize)>,
    removed: Vec<i32>,
    added: Vec<(i32, usize)>,
}

thread_local! {
    static INTEREST_SYNC_SCRATCH: std::cell::RefCell<InterestSyncScratch> =
        std::cell::RefCell::new(InterestSyncScratch::default());
}

// Test-only count of `SpawnDescriptor::packets` materializations, proving the
// steady-state path encodes no spawn packets.
#[cfg(test)]
thread_local! {
    static SPAWN_DESCRIPTOR_MATERIALIZATIONS: std::cell::Cell<usize> =
        const { std::cell::Cell::new(0) };
}

fn entity_tracking_range(etype: i64) -> u32 {
    static RANGES: OnceLock<Vec<u32>> = OnceLock::new();
    let ranges = RANGES.get_or_init(|| {
        ENTITY_REGISTRY_1211
            .iter()
            .map(|spec| client_tracking_range_chunks(spec.name))
            .collect()
    });
    usize::try_from(etype)
        .ok()
        .and_then(|id| ranges.get(id))
        .copied()
        .unwrap_or(0)
}

fn entity_in_tracking_range(player: (f64, f64), target: (f64, f64), range: u32, view: i32) -> bool {
    let distance = f64::from(range.min(view as u32)) * 16.0;
    let dx = player.0 - target.0;
    let dz = player.1 - target.1;
    range > 0 && dx * dx + dz * dz <= distance * distance
}

fn interest_tick() {
    let cls = client_snapshot();
    if cls.is_empty() {
        return;
    }
    sleep_tick();
    play_content_revision_sync();
    biome_override_sync_tick();
    // Build value descriptors once per tick; spawn packets are encoded only
    // for clients that actually start tracking an entity.
    let mut ents = Vec::new();
    let mut queue = |dim: DimId,
                     etype: i64,
                     eid: i32,
                     x: f64,
                     z: f64,
                     spawn: SpawnDescriptor| {
        ents.push(TrackedSpawn {
            dim,
            range: entity_tracking_range(etype),
            eid,
            x,
            z,
            cx: spatial_chunk_coord(x),
            cz: spatial_chunk_coord(z),
            spawn,
        });
    };
    for cart in generated_content().lock().unwrap_or_else(|e| e.into_inner()).carts.iter() {
        let cart = cart.clone();
        let pos = cart.pos().expect("validated generated cart");
        queue(
            cart.dim(),
            name_to_etype("chest_minecart").unwrap(),
            cart.eid,
            pos[0],
            pos[2],
            SpawnDescriptor::Cart(cart),
        );
    }
    for frame in generated_content().lock().unwrap_or_else(|e| e.into_inner()).frames.iter() {
        let frame = frame.clone();
        let pos = frame.pos().expect("validated generated frame");
        queue(
            frame.dim(),
            name_to_etype(if frame.glow() {
                "glow_item_frame"
            } else {
                "item_frame"
            })
            .unwrap(),
            frame.eid,
            pos[0],
            pos[2],
            SpawnDescriptor::Frame(frame),
        );
    }
    let mut live_eids = HashSet::new();
    for m in mobs().lock().unwrap_or_else(|e| e.into_inner()).iter() {
        let p = *m.pos.lock().unwrap_or_else(|e| e.into_inner());
        let mob = m.clone();
        live_eids.insert(mob.eid);
        queue(
            mob.dim,
            mob.etype,
            mob.eid,
            p.0,
            p.2,
            SpawnDescriptor::Mob(mob),
        );
    }
    mob_equipment()
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .retain(|eid, _| live_eids.contains(eid));
    for (&knot_eid, &(dim, pos)) in leash_knots()
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .iter()
    {
        let (x, y, z) = (
            pos.0 as f64 + 0.5,
            pos.1 as f64 + 0.5,
            pos.2 as f64 + 0.5,
        );
        queue(
            dim,
            name_to_etype("leash_knot").unwrap(),
            knot_eid,
            x,
            z,
            SpawnDescriptor::Typed {
                eid: knot_eid,
                etype: 63,
                x,
                y,
                z,
            },
        );
    }
    for &projectile in live_mob_projectiles().lock().unwrap_or_else(|e| e.into_inner()).iter() {
        let [x, _y, z] = projectile.pos;
        queue(
            projectile.dim,
            projectile.entity_type(),
            projectile.eid,
            x,
            z,
            SpawnDescriptor::Projectile(projectile),
        );
    }
    for cloud in live_dragon_clouds().lock().unwrap_or_else(|e| e.into_inner()).iter() {
        let (eid, [x, y, z]) = (cloud.eid, cloud.pos);
        queue(
            cloud.dim,
            1,
            eid,
            x,
            z,
            SpawnDescriptor::Typed {
                eid,
                etype: 1,
                x,
                y,
                z,
            },
        );
    }
    for d in drops().lock().unwrap_or_else(|e| e.into_inner()).iter() {
        let (eid, x, y, z, item, cnt, comps) =
            (d.eid, d.x, d.y, d.z, d.item, d.cnt, d.comps.clone());
        queue(
            DimId::Overworld,
            name_to_etype("item").unwrap(),
            eid,
            x,
            z,
            SpawnDescriptor::ItemDrop {
                eid,
                x,
                y,
                z,
                item,
                cnt,
                comps,
            },
        );
    }
    for a in arrows().lock().unwrap_or_else(|e| e.into_inner()).iter() {
        queue(
            DimId::Overworld,
            4,
            a.eid,
            a.x,
            a.z,
            SpawnDescriptor::Typed {
                eid: a.eid,
                etype: 4,
                x: a.x,
                y: a.y,
                z: a.z,
            },
        );
    }
    for b in bobbers().lock().unwrap_or_else(|e| e.into_inner()).iter() {
        let (eid, x, y, z) = (b.eid, b.x, b.y, b.z);
        queue(
            DimId::Overworld,
            129,
            eid,
            x,
            z,
            SpawnDescriptor::Typed {
                eid,
                etype: 129,
                x,
                y,
                z,
            },
        );
    }
    for p in pearls().lock().unwrap_or_else(|e| e.into_inner()).iter() {
        let (eid, x, y, z) = (p.eid, p.x, p.y, p.z);
        queue(
            DimId::Overworld,
            32,
            eid,
            x,
            z,
            SpawnDescriptor::Typed {
                eid,
                etype: 32,
                x,
                y,
                z,
            },
        );
    }
    for sb in snowballs().lock().unwrap_or_else(|e| e.into_inner()).iter() {
        let (eid, x, y, z) = (sb.eid, sb.x, sb.y, sb.z);
        queue(
            DimId::Overworld,
            97,
            eid,
            x,
            z,
            SpawnDescriptor::Typed {
                eid,
                etype: 97,
                x,
                y,
                z,
            },
        );
    }
    for e in eyes().lock().unwrap_or_else(|e| e.into_inner()).iter() {
        let (eid, x, y, z) = (e.eid, e.x, e.y, e.z);
        queue(
            DimId::Overworld,
            39,
            eid,
            x,
            z,
            SpawnDescriptor::Typed {
                eid,
                etype: 39,
                x,
                y,
                z,
            },
        );
    }
    for t in primed().lock().unwrap_or_else(|e| e.into_inner()).iter() {
        let (eid, x, y, z) = (t.eid, t.x, t.y, t.z);
        queue(
            DimId::Overworld,
            106,
            eid,
            x,
            z,
            SpawnDescriptor::Typed {
                eid,
                etype: 106,
                x,
                y,
                z,
            },
        );
    }
    for f in falling().lock().unwrap_or_else(|e| e.into_inner()).iter() {
        let (eid, x, y, z, state) = (f.eid, f.x, f.y, f.z, f.state);
        queue(
            DimId::Overworld,
            name_to_etype("falling_block").unwrap(),
            eid,
            x,
            z,
            SpawnDescriptor::Falling {
                eid,
                state,
                x,
                y,
                z,
            },
        );
    }
    for o in xps().lock().unwrap_or_else(|e| e.into_inner()).iter() {
        let (eid, x, y, z, val) = (o.eid, o.x, o.y, o.z, o.val);
        queue(
            DimId::Overworld,
            name_to_etype("experience_orb").unwrap(),
            eid,
            x,
            z,
            SpawnDescriptor::ExperienceOrb {
                eid,
                x,
                y,
                z,
                val,
            },
        );
    }
    // P2-3-S4: a player is only interested in players sharing their dimension. Two players
    // at the same coordinates in different worlds must not spawn for one another; on a
    // dimension switch the 0x42 removals below retire the old-world players.
    for o in cls.iter() {
        let (dim, x, _, z, _, _) = client_dim_pos(o);
        queue(
            dim,
            PLAYER_ENTITY_TYPE,
            o.eid,
            x,
            z,
            SpawnDescriptor::Player(o.clone()),
        );
    }
    let index = InterestChunkIndex::new(&ents);
    for client in &cls {
        sync_entity_interest_indexed(client, &ents, &index);
    }
    dig_progress_tick(&cls);
    combat_tick(&cls);
    flight_kick_tick(&cls);
    // Death is a server-tick event (vanilla LivingEntity.die): an idle
    // victim's own read loop may not wake for seconds, so the tick sweep
    // drives drop_player_items_on_death — it emits the 0x1f death event and
    // drops exactly once via death_drop_marks.
    for c in &cls {
        drop_player_items_on_death(c);
    }
}

/// `Level.destroyBlockProgress`: the dig's crack stage goes to every viewer
/// within the vanilla 32-block update radius in the dig's dimension —
/// excluding the breaker, whose own client plays the local crack animation.
/// `stage` `-1` clears the cracks on a cancelled dig.
fn broadcast_block_destroy(cls: &[Arc<Client>], dim: DimId, pos: (i32, i32, i32), breaker: i32, stage: i8) {
    let (_, payload) = encode_play_block_destruction(breaker, pos, stage);
    let (x, y, z) = pos;
    let mut shared = None;
    for c in cls {
        if c.eid == breaker || *c.dim.lock().unwrap_or_else(|e| e.into_inner()) != dim {
            continue;
        }
        let (px, py, pz, ..) = *c.pos.lock().unwrap_or_else(|e| e.into_inner());
        let (dx, dy, dz) = (px - x as f64 - 0.5, py - y as f64 - 0.5, pz - z as f64 - 0.5);
        if dx * dx + dy * dy + dz * dz <= 32.0 * 32.0 {
            if let Ok(mut w) = c.sock.lock() {
                let _ = send_broadcast_frame(&mut w, &mut shared, 0x06, &payload);
            }
        }
    }
}

/// Server-side mining completion: a pending START_DESTROY_BLOCK whose block
/// still matches and whose dig duration has elapsed breaks, exactly as
/// `ServerPlayerGameMode.tick` advancing `destroyProgress` past 1.0 would. A
/// changed or removed block, a cancelled dig, or a client disconnect clears the
/// pending state instead. While a dig is pending, its crack stage broadcasts
/// `block_destruction` to nearby viewers on every stage change.
fn dig_progress_tick(cls: &[Arc<Client>]) {
    for c in cls {
        let Some(dig) = *c.dig.lock().unwrap_or_else(|e| e.into_inner()) else {
            continue;
        };
        let (dim, x, y, z) = dig.pos;
        let current = block_at_dim(dim, x, y, z);
        if current != dig.state {
            *c.dig.lock().unwrap_or_else(|e| e.into_inner()) = None;
            continue;
        }
        let elapsed_ticks = TICK_IDX.load(Ordering::Relaxed).saturating_sub(dig.start_tick);
        let required_ticks = dig_required_ticks(dig.seconds, 1.0).max(1);
        let stage = ((elapsed_ticks as f64 / required_ticks as f64) * 10.0)
            .clamp(0.0, 9.0) as i8;
        if stage != dig.last_stage {
            if let Some(d) = c.dig.lock().unwrap_or_else(|e| e.into_inner()).as_mut() {
                d.last_stage = stage;
            }
            broadcast_block_destroy(cls, dim, (x, y, z), c.eid, stage);
        }
        if elapsed_ticks >= required_ticks {
            *c.dig.lock().unwrap_or_else(|e| e.into_inner()) = None;
            finish_block_break(c, dim, x, y, z, dig.state);
        }
    }
}

/// Per-player `CombatTracker` mirrors — `(first damage, last damage)` keyed by
/// player eid. Vanilla opens the combat window on the first accepted hit and
/// closes it 100 ticks (5 seconds) after the most recent one.
fn combat_sessions() -> &'static Mutex<HashMap<i32, (Instant, Instant)>> {
    static COMBAT: OnceLock<Mutex<HashMap<i32, (Instant, Instant)>>> = OnceLock::new();
    COMBAT.get_or_init(|| Mutex::new(HashMap::new()))
}

/// `CombatTracker.recordDamage`: the first hit opens the victim's combat
/// window (`player_combat_enter` to the victim); every accepted hit refreshes
/// the five-second end timer.
fn combat_note_damage(victim: &Client) {
    let mut sessions = combat_sessions().lock().unwrap_or_else(|e| e.into_inner());
    let now = Instant::now();
    match sessions.get_mut(&victim.eid) {
        Some((_, last)) => *last = now,
        None => {
            sessions.insert(victim.eid, (now, now));
            drop(sessions);
            let _ = send_packet(
                &mut victim.sock.lock().unwrap_or_else(|e| e.into_inner()),
                0x3b,
                encode_play_player_combat_enter().1,
            );
        }
    }
}

/// `ServerGamePacketListenerImpl`'s `floatingTicks` ledger: consecutive
/// airborne, non-falling ticks per player eid, plus the last sampled `y` so
/// the per-tick `dy` is the same measurement Vanilla takes per move packet.
/// Entries are swept with the client list so a disconnect frees its row.
fn floating_ticks() -> &'static Mutex<HashMap<i32, (u32, f64)>> {
    static FLOATING: OnceLock<Mutex<HashMap<i32, (u32, f64)>>> = OnceLock::new();
    FLOATING.get_or_init(|| Mutex::new(HashMap::new()))
}

/// `allow-flight` (`MEGU_ALLOW_FLIGHT`, Vanilla `allow-flight`): `false`
/// kicks a survival/adventure player who reports airborne for 80 straight
/// ticks without actually falling — Vanilla's `floatingTicks` check with the
/// same exemptions (creative/spectator, dead, sleeping, riding, elytra
/// gliding, submerged). "Airborne without falling" is vanilla's
/// `dY >= -0.03125 && noBlocksAround`: a non-air block in the half-block
/// band under the feet, or real downward speed, both reset the count.
fn flight_kick_tick(cls: &[Arc<Client>]) {
    let mut floating = floating_ticks().lock().unwrap_or_else(|e| e.into_inner());
    floating.retain(|eid, _| cls.iter().any(|c| c.eid == *eid));
    if live_allow_flight() {
        floating.clear();
        return;
    }
    let air_supply = server_ticks(AIR_SUPPLY_GT) as i32;
    for c in cls {
        let exempt = matches!(*c.gm.lock().unwrap_or_else(|e| e.into_inner()), 1 | 3)
            || *c.hp.lock().unwrap_or_else(|e| e.into_inner()) <= 0.0
            || c.sleeping.lock().unwrap_or_else(|e| e.into_inner()).is_some()
            || *c.fall_fly.lock().unwrap_or_else(|e| e.into_inner())
            || vehicle_of(c.eid).is_some()
            || *c.air.lock().unwrap_or_else(|e| e.into_inner()) < air_supply;
        if exempt {
            floating.remove(&c.eid);
            continue;
        }
        let (x, y, z, _, _, grounded) = *c.pos.lock().unwrap_or_else(|e| e.into_inner());
        let entry = floating.entry(c.eid).or_insert((0, y));
        let dy = y - entry.1;
        entry.1 = y;
        let supported = crate::block_registry::breg().is_some_and(|reg| {
            let dim = *c.dim.lock().unwrap_or_else(|e| e.into_inner());
            let (bx, bz) = (x.floor() as i32, z.floor() as i32);
            [y - 0.1, y - 0.55]
                .iter()
                .any(|probe| !reg.is_air(block_at_dim(dim, bx, probe.floor() as i32, bz)))
        });
        if grounded || supported || dy < -0.03125 {
            entry.0 = 0;
            continue;
        }
        entry.0 += 1;
        if entry.0 >= 80 {
            kick_client(c, "Flying is not enabled on this server");
        }
    }
}

/// `CombatTracker.tick`: five quiet seconds after the last damage the combat
/// window closes with `player_combat_end` carrying the open duration in
/// ticks; a dead player's window closes silently — `player_combat_kill`
/// carries the death instead.
fn combat_tick(cls: &[Arc<Client>]) {
    for c in cls {
        let alive = *c.hp.lock().unwrap_or_else(|e| e.into_inner()) > 0.0;
        let ended = {
            let mut sessions = combat_sessions().lock().unwrap_or_else(|e| e.into_inner());
            match sessions.get(&c.eid) {
                Some(&(started, last)) if alive && last.elapsed() >= Duration::from_secs(5) => {
                    sessions.remove(&c.eid);
                    Some(started.elapsed())
                }
                Some(_) if !alive => {
                    sessions.remove(&c.eid);
                    None
                }
                _ => None,
            }
        };
        if let Some(duration) = ended {
            let ticks = (duration.as_millis() / 50) as u32;
            let _ = send_packet(
                &mut c.sock.lock().unwrap_or_else(|e| e.into_inner()),
                0x3a,
                encode_play_player_combat_end(ticks).1,
            );
        }
    }
}

/// `Inventory.getSuitableHotbarSlot` (1.21.1 `cmw.i()`): scan forward from the
/// held slot for an empty hotbar slot, then for an unenchanted one
/// (`ItemStack.isEnchanted` == a non-empty `enchantments` component), else
/// keep the held slot. Hotbar slots are menu slots 36..=44.
fn suitable_hotbar_slot(inv: &HashMap<i16, Stack>, held: i16) -> i16 {
    for i in 0..9i16 {
        let cand = (held + i) % 9;
        let empty = inv
            .get(&(36 + cand))
            .is_none_or(|st| st.0 == 0 || st.1 == 0);
        if empty {
            return cand;
        }
    }
    for i in 0..9i16 {
        let cand = (held + i) % 9;
        let enchanted = inv
            .get(&(36 + cand))
            .is_some_and(|st| !enchantments_get(&st.2).is_empty());
        if !enchanted {
            return cand;
        }
    }
    held
}

/// `ClientboundContainerSetSlotPacket` on the `-2` (`PLAYER_INVENTORY`)
/// window `handlePickItem` uses: slot numbers are `Inventory.items` indices
/// (0..=8 hotbar, 9..=35 main inventory), not menu slots.
fn send_pick_slot(me: &Client, items_slot: i16, st: &Stack) {
    let mut p = vec![0xFEu8]; // containerId -2
    write_varint(&mut p, i64::from(inv_state_next(me)));
    p.extend_from_slice(&items_slot.to_be_bytes());
    p.extend_from_slice(&slot_wire(st));
    let _ = send_packet(&mut me.sock.lock().unwrap_or_else(|e| e.into_inner()), 0x15, p);
}

/// `ServerGamePacketListenerImpl.handlePickItem` + `Inventory.pickSlot`
/// (1.21.1): the client resolves the middle-clicked block to an
/// `Inventory.items` index — 0..=8 hotbar, 9..=35 main inventory — and the
/// server swaps that stack into the suitable hotbar slot. Vanilla clients
/// only ever send main-inventory hits (hotbar matches select locally), but
/// the handler is written for the full `items` index space; out-of-range
/// slots are dropped fail-closed. Both touched slots are resent on the `-2`
/// window followed by `SetCarriedItem`.
fn pick_item(me: &Arc<Client>, held_slot: &mut i16, slot: i64) {
    if !(0..36).contains(&slot) {
        return;
    }
    let slot = slot as i16;
    if slot < 9 {
        // Hotbar index: select it — the same visible result the vanilla
        // client produces locally for a hotbar match.
        *held_slot = slot;
        *me.held.lock().unwrap_or_else(|e| e.into_inner()) = slot;
        let _ = send_packet(
            &mut me.sock.lock().unwrap_or_else(|e| e.into_inner()),
            0x53,
            vec![slot as u8],
        );
        return;
    }
    let hslot = {
        let inv = me.inv.lock().unwrap_or_else(|e| e.into_inner());
        suitable_hotbar_slot(&inv, *held_slot)
    };
    // items index -> menu slot: hotbar i -> 36+i, main i -> i
    let hot_menu = 36 + hslot;
    let (st_hot, st_main) = {
        let mut inv = me.inv.lock().unwrap_or_else(|e| e.into_inner());
        let displaced = inv.get(&hot_menu).cloned().unwrap_or((0, 0, Vec::new()));
        let picked = inv.get(&slot).cloned().unwrap_or((0, 0, Vec::new()));
        if picked.0 != 0 && picked.1 > 0 {
            inv.insert(hot_menu, picked);
        } else {
            inv.remove(&hot_menu);
        }
        if displaced.0 != 0 && displaced.1 > 0 {
            inv.insert(slot, displaced);
        } else {
            inv.remove(&slot);
        }
        (
            inv.get(&hot_menu).cloned().unwrap_or((0, 0, Vec::new())),
            inv.get(&slot).cloned().unwrap_or((0, 0, Vec::new())),
        )
    };
    *held_slot = hslot;
    *me.held.lock().unwrap_or_else(|e| e.into_inner()) = hslot;
    send_pick_slot(me, hslot, &st_hot);
    send_pick_slot(me, slot, &st_main);
    let _ = send_packet(
        &mut me.sock.lock().unwrap_or_else(|e| e.into_inner()),
        0x53,
        vec![hslot as u8],
    );
}

/// `can_place_on`/`can_break` component ids (protocol 767 data-component
/// registry indices 10 and 11). Both encode `AdventureModePredicate`: a
/// VarInt count of `BlockPredicate` entries — optional block holder-set,
/// optional property-matcher list, optional NBT — where any one matching
/// predicate allows the interaction.
const COMP_CAN_PLACE_ON: i64 = 10;
const COMP_CAN_BREAK: i64 = 11;

/// A `PropertyMatcher`'s min/max arm: `true` when `value` falls inside the
/// closed range. Ordered property values compare numerically when every side
/// parses (vanilla's ordered properties are index-ordered and overwhelmingly
/// numeric); anything else takes the lexicographic answer. Only used where a
/// missing matcher already failed the predicate.
fn prop_value_in_range(value: &str, min: &str, max: &str) -> bool {
    match (value.parse::<i64>(), min.parse::<i64>(), max.parse::<i64>()) {
        (Ok(v), Ok(lo), Ok(hi)) => v >= lo && v <= hi,
        _ => value >= min && value <= max,
    }
}

/// Parse one `BlockPredicate` off `b` and test the parts a block state can
/// answer: the holder-set (explicit ids or a named tag) and the property
/// matchers. Returns `Ok(false)` for a parsed-but-unmatched predicate and
/// `Err(())` for truncated/unsupported input — including a present NBT clause,
/// which needs a block entity this layer does not see and therefore fails the
/// whole component closed.
fn adventure_predicate_match(
    reg: &block_registry::BReg,
    st: u32,
    b: &mut &[u8],
) -> Result<bool, ()> {
    // Optional<HolderSet<Block>>: absent matches every block. On the wire a
    // negative size (-1) names a registry tag; otherwise `n` VarInt block ids.
    let has_blocks = *b.first().ok_or(())? != 0;
    *b = &b[1..];
    if has_blocks {
        let n = read_varint(b).ok_or(())?;
        let in_set = if n < 0 {
            let tag = read_string_bounded(b, 32767).ok_or(())?;
            reg.in_tag(st, &tag)
        } else {
            if n > 4096 {
                return Err(());
            }
            let mut hit = false;
            for _ in 0..n {
                hit |= reg.block_id_of(st) == Some(read_varint(b).ok_or(())? as i32);
            }
            hit
        };
        if !in_set {
            return Ok(false);
        }
    }
    // Optional<List<PropertyMatcher>>: absent matches every state.
    let has_props = *b.first().ok_or(())? != 0;
    *b = &b[1..];
    if has_props {
        let count = read_varint(b).ok_or(())?;
        if !(0..=256).contains(&count) {
            return Err(());
        }
        for _ in 0..count {
            let name = read_string_bounded(b, 32767).ok_or(())?;
            let kind = *b.first().ok_or(())?;
            *b = &b[1..];
            let value = reg.get_prop(st, &name);
            let ok = match kind {
                0 => {
                    let want = read_string_bounded(b, 32767).ok_or(())?;
                    value.as_deref() == Some(want.as_str())
                }
                1 => {
                    let min = read_string_bounded(b, 32767).ok_or(())?;
                    let max = read_string_bounded(b, 32767).ok_or(())?;
                    value.is_some_and(|v| prop_value_in_range(&v, &min, &max))
                }
                _ => return Err(()),
            };
            if !ok {
                return Ok(false);
            }
        }
    }
    // Optional<Nbt>: a present clause needs the block entity and cannot be
    // skipped byte-wise here, so the component fails closed.
    if *b.first().ok_or(())? != 0 {
        return Err(());
    }
    *b = &b[1..];
    Ok(true)
}

/// `AdventureModePredicate.test` over a held stack's `can_place_on` /
/// `can_break` component against one block state. A stack without the
/// component allows nothing in adventure mode; a malformed or
/// NBT-bearing component is treated the same — deny.
fn adventure_stack_allows(reg: &block_registry::BReg, st: u32, held: &Stack, comp: i64) -> bool {
    let Some(data) = comp_get(&held.2, comp) else {
        return false;
    };
    let mut b = data;
    let Some(count) = read_varint(&mut b) else {
        return false;
    };
    if !(0..=256).contains(&count) {
        return false;
    }
    for _ in 0..count {
        match adventure_predicate_match(reg, st, &mut b) {
            Ok(true) => return true,
            Ok(false) => {}
            Err(()) => return false,
        }
    }
    false
}

/// `TrapDoorBlock.useWithoutItem`: every trapdoor but the iron one toggles
/// `open` on right-click; the iron variant answers redstone only. A toggled
/// state is pushed to every chunk watcher through `note_block_update_dim`.
/// Returns whether a toggle ran.
fn try_toggle_trapdoor(dim: DimId, x: i32, y: i32, z: i32) -> bool {
    let st = block_at_dim(dim, x, y, z);
    if !trapdoor_state(st) {
        return false;
    }
    let Some(reg) = block_registry::breg() else {
        return false;
    };
    if reg.name_of(st) == "minecraft:iron_trapdoor" {
        return false;
    }
    let Some(opened) = reg.get_prop(st, "open").map(|v| v == "true") else {
        return false;
    };
    let updated = reg.with_prop(st, "open", if opened { "false" } else { "true" });
    set_block_dim(dim, x, y, z, updated);
    note_block_update_dim(dim, x, y, z, updated);
    true
}

/// Apply a confirmed block break: clear the cell, fan the update out to every
/// chunk watcher, then run the survival bookkeeping (exhaustion, tool wear,
/// drops). Shared by the dig packet's immediate path and the tick-driven
/// destroy progress that runs after START_DESTROY_BLOCK.
fn finish_block_break(me: &Arc<Client>, dim: DimId, x: i32, y: i32, z: i32, old: u32) {
    // Lane WIRE-MINECUT-ORBITAL-SYNC (`mod-suite` only): the opt-in
    // MineAll/CutAll plan must run while the origin block is still in the
    // world — it is the BFS search origin. `live_mine_cut_all_apply` below
    // fires only after the origin actually broke, and both policies default
    // to `off`, which returns an empty plan before touching the world.
    #[cfg(feature = "mod-suite")]
    let vein_plan = live_mine_cut_all_plan(me, dim, x, y, z);
    finish_block_break_one(me, dim, x, y, z, old);
    #[cfg(feature = "mod-suite")]
    live_mine_cut_all_apply(me, dim, vein_plan, (x, y, z), old);
}

/// The confirmed single-block break [`finish_block_break`] runs for the
/// origin and — under `mod-suite` — for every extra position the opt-in
/// MineAll/CutAll planner emits. Extras re-enter this body so the adventure
/// `mayDestroy` recheck, the progression gate, and the NeoForge break event
/// all apply to every expanded cell exactly as they do to the origin.
fn finish_block_break_one(me: &Arc<Client>, dim: DimId, x: i32, y: i32, z: i32, old: u32) {
    let held = {
        let held_slot = *me.held.lock().unwrap_or_else(|e| e.into_inner());
        let inv = me.inv.lock().unwrap_or_else(|e| e.into_inner());
        inv.get(&(36 + held_slot)).cloned().unwrap_or((0, 0, Vec::new()))
    };
    // Vanilla rechecks mayDestroy in `destroyAndAck`: an adventure-mode dig
    // still finishes only while the held stack's can_break matches.
    if *me.gm.lock().unwrap_or_else(|e| e.into_inner()) == 2 {
        let allowed = block_registry::breg().is_some_and(|reg| {
            adventure_stack_allows(reg, old, &held, COMP_CAN_BREAK)
        });
        if !allowed {
            return;
        }
    }
    // Live progression gates (mod-suite): a sealed dimension/biome rule
    // denies the break before any world mutation and resyncs the cell so the
    // client sees the block reappear, matching the recheck above.
    if live_progression_denies_break(me, dim, x, y, z) {
        return;
    }
    #[cfg(feature = "neoforge-events")]
    if java_compat::NEOFORGE.get().is_some() {
        let result = neoforge_event(me, java_compat::S1Event::BlockBreak {
            dim: dim.index() as u8,
            pos: (x, y, z),
            state: old,
            player: (me.eid, me.name.clone()),
            exp_to_drop: 0,
        });
        if result.is_err() || !set_block_if_dim(dim, x, y, z, 0, Some(old)) {
            neoforge_resync_block(me, dim, (x, y, z));
            return;
        }
    } else {
        set_block_dim(dim, x, y, z, 0);
    }
    #[cfg(not(feature = "neoforge-events"))]
    set_block_dim(dim, x, y, z, 0);
    note_block_update_dim(dim, x, y, z, 0);
    if *me.gm.lock().unwrap_or_else(|e| e.into_inner()) != 1 {
        *me.walk_acc.lock().unwrap_or_else(|e| e.into_inner()) += 0.005; // block-break exhaustion
        // `Stats.BLOCK_MINED` for the block that was there — keyed by the
        // block item registry id like every other mined stat entry.
        if let Some(reg) = crate::block_registry::breg() {
            if let Some(block_id) = reg.block_id_of(old) {
                stat_increment(me, StatCategory::Mined, block_id, 1);
            }
        }
        // `Item.mineBlock` damages the held tool only when the broken
        // state has a nonzero destroy speed — insta-mine blocks (torch,
        // tall grass, TNT…) never cost durability, even for a tool.
        if block_hardness(old as i64) != 0.0
            && (tool_max_damage(held.0).is_some()
                || comp_get(&held.2, COMP_MAX_DAMAGE).is_some())
        {
            if damage_held(me) {
                let (pxx, pyy, pzz, ..) = {
                    let p = me.pos.lock().unwrap_or_else(|e| e.into_inner());
                    *p
                };
                let snd = sound_pkt_named("entity.item.break", pxx, pyy + 1.0, pzz);
                broadcast_near_packet(
                    *me.dim.lock().unwrap_or_else(|e| e.into_inner()),
                    pxx,
                    pyy + 1.0,
                    pzz,
                    -1,
                    0x68,
                    &snd,
                );
            }
            held_slot_resync(me);
        }
        let silk = enchant_level(&held.2, 33) > 0;
        let fort = enchant_level(&held.2, 13).clamp(0, 3) as u8;
        // ore loot: (material drop, silk-touch drops the ore block
        // item instead, fortune multiplies the material count)
        let ore: Option<(i64, i64)> = match old {
            127 | 128 => Some((803, 62)),     // coal -> coal_ore
            125 | 126 => Some((810, 64)),     // raw_iron -> iron_ore
            123 | 124 => Some((814, 68)),     // raw_gold -> gold_ore
            4274 | 4275 => Some((805, 76)),   // diamond -> diamond_ore
            520 | 521 => Some((807, 74)),     // lapis -> lapis_ore
            5735..=5737 => Some((657, 70)),   // redstone -> redstone_ore
            22942..=22943 => Some((812, 66)), // raw_copper -> copper_ore
            7511 | 7512 => Some((806, 72)),   // emerald -> emerald_ore
            _ => None,
        };
        let (drop_item, drop_cnt) = if let (true, Some(o)) = (silk, ore) {
            (Some(o.1), 1)
        } else {
            let it = match old {
                127 | 128 => Some(803),
                125 | 126 => Some(810),
                123 | 124 => Some(814),
                4274 | 4275 => Some(805),
                520 | 521 => Some(807),
                5735..=5737 => Some(657),
                22942..=22943 => Some(812),
                7511 | 7512 => Some(806),
                4278..=4285 => Some(853), // wheat -> seeds
                _ => block_drop(old),
            };
            let n = if fort > 0 && ore.is_some() {
                1 + (world_rng::next_u64() % (fort as u64 + 1)) as u8
            } else {
                1
            };
            (it, n)
        };
        crops().lock().unwrap_or_else(|e| e.into_inner()).remove(&(dim, x, y, z));
        if old == 4285 && GR_DO_TILE_DROPS.load(Ordering::Relaxed) != 0 {
            // ripe: extra wheat drop
            let d = Drop {
                eid: NEXT_EID.fetch_add(1, Ordering::SeqCst),
                x: x as f64 + 0.5,
                y: y as f64 + 0.25,
                z: z as f64 + 0.5,
                item: 854,
                cnt: 1,
                comps: Vec::new(),
                age: 0,
                target: None,
                thrower: None,
            }
            .world_scatter(dim);
            drops().lock().unwrap_or_else(|e| e.into_inner()).push(d);
        }
        if let Some(item) = if !can_harvest(old as i64, held.0)
            || GR_DO_TILE_DROPS.load(Ordering::Relaxed) == 0
        {
            None
        } else {
            drop_item
        } {
            let d = Drop {
                eid: NEXT_EID.fetch_add(1, Ordering::SeqCst),
                x: x as f64 + 0.5,
                y: y as f64 + 0.25,
                z: z as f64 + 0.5,
                item,
                cnt: drop_cnt,
                comps: Vec::new(),
                age: 0,
                target: None,
                thrower: None,
            }
            .world_scatter(dim);
            drops().lock().unwrap_or_else(|e| e.into_inner()).push(d);
        }
    }
}

// ---------------------------------------------------------------------------
// Lane WIRE-MINECUT-ORBITAL-SYNC: opt-in MineAll/CutAll expansion over
// `mod_adapter_core::mine_cut_all`. Armed only by `/megu policy set
// mine_all|cut_all <sneak_only|while_not_sneaking|always>` (or server.toml);
// both modes default `off` and the live break path is then byte-identical to
// vanilla. The planner's `can_break` closure is the same spawn-protection +
// claim predicate the dig handler enforces on the origin, so an expansion
// can never reach into a protected chunk.
// ---------------------------------------------------------------------------

/// Read-only live-world view for `mod_adapter_core::mine_cut_all`: block
/// names and effective tag membership come from `breg()`, claim/spawn
/// protection comes from `can_player_modify_block` — the predicate the dig
/// handler itself enforces, so the expansion stops at exactly the same wall.
#[cfg(feature = "mod-suite")]
struct LiveMineCutAllWorld<'a> {
    dim: DimId,
    reg: &'static block_registry::BReg,
    player_name: &'a str,
    op_level: u8,
}

#[cfg(feature = "mod-suite")]
impl mod_adapter_core::mine_cut_all::MineCutAllWorld for LiveMineCutAllWorld<'_> {
    fn block_id_at(
        &self,
        pos: mod_adapter_core::mine_cut_all::MineCutAllPos,
    ) -> Option<&str> {
        let st = block_at_dim(self.dim, pos.x, pos.y, pos.z);
        if self.reg.is_air(st) {
            None
        } else {
            Some(self.reg.name_of(st))
        }
    }

    fn block_has_tag(&self, block_id: &str, tag: &str) -> bool {
        self.reg.in_tag(self.reg.state_of(block_id, None), tag)
    }

    fn can_break(&self, pos: mod_adapter_core::mine_cut_all::MineCutAllPos) -> bool {
        can_player_modify_block(self.dim, pos.x, pos.z, self.player_name, self.op_level)
    }
}

#[cfg(feature = "mod-suite")]
fn live_mine_cut_all_trigger(mode: &str) -> mod_adapter_core::mine_cut_all::TriggerMode {
    use mod_adapter_core::mine_cut_all::TriggerMode;
    match mode {
        "sneak_only" => TriggerMode::SneakOnly,
        "while_not_sneaking" => TriggerMode::WhileNotSneaking,
        "always" => TriggerMode::Always,
        _ => TriggerMode::Off,
    }
}

/// Map the live held stack onto the planner's mod-agnostic tool descriptor:
/// vanilla tool-band items synthesize their `minecraft:<tool>s` family tag,
/// datapack/builtin item tags carry modded families (`c:tools/pickaxe` et
/// al.), and a `minecraft:tool` component contributes its mineable block
/// tags. Durability is `max_damage - damage`; unbreakable and non-damageable
/// stacks carry no budget at all.
#[cfg(feature = "mod-suite")]
fn live_mine_cut_all_tool(held: &Stack) -> mod_adapter_core::mine_cut_all::ToolDescriptor {
    use mod_adapter_core::mine_cut_all as mca;
    let item_id = item_to_name(held.0).unwrap_or("minecraft:air");
    let mut tags = std::collections::BTreeSet::new();
    // Vanilla band sword/shovel/pickaxe/axe/hoe x 6 tiers: items 818..=847.
    if (818..=847).contains(&held.0) {
        tags.insert(
            match (held.0 - 818) % 5 {
                1 => "minecraft:shovels",
                2 => "minecraft:pickaxes",
                3 => "minecraft:axes",
                4 => "minecraft:hoes",
                _ => "minecraft:swords",
            }
            .to_string(),
        );
    }
    {
        let item_tags = item_tags().lock().unwrap_or_else(|e| e.into_inner());
        for (tag, members) in item_tags.iter() {
            if members.iter().any(|m| name_to_item(m) == Some(held.0)) {
                tags.insert(tag.clone());
            }
        }
    }
    let mut tool = mca::ToolDescriptor::new(item_id).with_item_tags(tags);
    if let Some(component) = tool_component_for(held) {
        tool = tool.with_mineable_tags(component.rules.iter().filter_map(|r| r.tag.clone()));
    }
    if comp_get(&held.2, COMP_UNBREAKABLE).is_some() {
        return tool.with_unbreakable();
    }
    if let Some(max_damage) =
        comp_varint(&held.2, COMP_MAX_DAMAGE).or_else(|| tool_max_damage(held.0))
    {
        let used = comp_varint(&held.2, COMP_DAMAGE).unwrap_or(0);
        tool = tool.with_remaining_durability((max_damage - used).max(0) as u32);
    }
    tool
}

/// Plan the opt-in vein/tree expansion for a confirmed break at `(x, y, z)`.
/// Runs BEFORE the origin mutates — the BFS needs it as its search origin.
/// Every early-out (both modes off, sneak gate closed, no registry) returns
/// the shared empty plan, so the vanilla-default path costs one policy read.
#[cfg(feature = "mod-suite")]
fn live_mine_cut_all_plan(
    me: &Arc<Client>,
    dim: DimId,
    x: i32,
    y: i32,
    z: i32,
) -> mod_adapter_core::mine_cut_all::MineCutAllPlan {
    use mod_adapter_core::mine_cut_all as mca;
    let (mine_all, cut_all) = live_mine_cut_all_modes();
    let config = mca::MineCutAllConfig::default().with_trigger(
        live_mine_cut_all_trigger(&mine_all),
        live_mine_cut_all_trigger(&cut_all),
    );
    if config.mine_all.is_off() && config.cut_all.is_off() {
        return mca::MineCutAllPlan::default();
    }
    let sneaking = *me.sneaking.lock().unwrap_or_else(|e| e.into_inner());
    if !config.mine_all.allows(sneaking) && !config.cut_all.allows(sneaking) {
        return mca::MineCutAllPlan::default();
    }
    let Some(reg) = block_registry::breg() else {
        return mca::MineCutAllPlan::default();
    };
    let held = {
        let held_slot = *me.held.lock().unwrap_or_else(|e| e.into_inner());
        me.inv
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .get(&(36 + held_slot))
            .cloned()
            .unwrap_or((0, 0, Vec::new()))
    };
    let tool = live_mine_cut_all_tool(&held);
    let world = LiveMineCutAllWorld {
        dim,
        reg,
        player_name: &me.name,
        op_level: client_permission_level(me),
    };
    mca::plan_vein_or_tree_break(
        &config,
        &tool,
        &world,
        mca::MineCutAllPos::new(x, y, z),
        sneaking,
    )
}

/// Break every extra position a [`live_mine_cut_all_plan`] produced. The
/// apply fires only when the origin cell actually left `origin_state` — a
/// denied or resynced break never expands — and each extra goes back through
/// [`finish_block_break_one`], so drops, block updates, tool damage,
/// exhaustion, the adventure `mayDestroy` recheck and the progression gate
/// all behave exactly as they do for the origin. Positions re-read their
/// live state: a cell another actor cleared in the meantime is a no-op, and
/// recursion is impossible because extras never re-plan.
#[cfg(feature = "mod-suite")]
fn live_mine_cut_all_apply(
    me: &Arc<Client>,
    dim: DimId,
    plan: mod_adapter_core::mine_cut_all::MineCutAllPlan,
    (ox, oy, oz): (i32, i32, i32),
    origin_state: u32,
) {
    if plan.positions.len() < 2
        || plan.kind == mod_adapter_core::mine_cut_all::MineCutAllKind::None
        || block_at_dim(dim, ox, oy, oz) == origin_state
    {
        return;
    }
    for pos in &plan.positions[1..] {
        let cur = block_at_dim(dim, pos.x, pos.y, pos.z);
        if block_registry::breg().is_none_or(|reg| reg.is_air(cur)) {
            continue;
        }
        finish_block_break_one(me, dim, pos.x, pos.y, pos.z, cur);
        record_live_block_audit(
            dim,
            (pos.x, pos.y, pos.z),
            &me.name,
            cur,
            block_at_dim(dim, pos.x, pos.y, pos.z),
            TICK_IDX.load(Ordering::Relaxed),
        );
    }
}

/// Scale a per-tick work budget by the server PID load-shed factor
/// (`live_server_budget_scale`, `1.0` when `mod-suite` is off). The `.max(1)`
/// floor keeps at least one unit flowing so streaming and interest tracking
/// always make forward progress even at the 0.25 shed floor; a scale `>= 1.0`
/// or an empty budget is a no-op.
fn live_scaled_tick_budget(base: usize, scale: f32) -> usize {
    if base == 0 || scale >= 1.0 {
        return base;
    }
    ((base as f64 * f64::from(scale)).ceil() as usize).clamp(1, base)
}

fn interest_entity_eligible(
    client: &Client,
    entity: &TrackedSpawn,
    dim: DimId,
    player: (f64, f64),
    player_chunk: (i32, i32),
    view: i32,
) -> bool {
    if entity.eid == client.eid || entity.dim != dim {
        return false;
    }
    // Integer chunk-gap rejection before the float distance check: two chunk
    // cells `d` apart leave at least `16 * max(0, d - 1)` blocks between them
    // on that axis, so an entity whose cells are more than `reach` effective
    // chunk-gaps away can never satisfy `entity_in_tracking_range`.
    let reach = i128::from(entity.range.min(view as u32));
    let gx = (i128::from(entity.cx) - i128::from(player_chunk.0)).abs() - 1;
    let gz = (i128::from(entity.cz) - i128::from(player_chunk.1)).abs() - 1;
    let gx = gx.max(0);
    let gz = gz.max(0);
    if gx * gx + gz * gz > reach * reach {
        return false;
    }
    entity_in_tracking_range(player, (entity.x, entity.z), entity.range, view)
}

fn sync_entity_interest_indexed(
    client: &Client,
    entities: &[TrackedSpawn],
    index: &InterestChunkIndex,
) {
    INTEREST_SYNC_SCRATCH.with(|cell| {
        sync_entity_interest_indexed_inner(client, entities, index, &mut cell.borrow_mut())
    });
}

fn sync_entity_interest_indexed_inner(
    client: &Client,
    entities: &[TrackedSpawn],
    index: &InterestChunkIndex,
    scratch: &mut InterestSyncScratch,
) {
    scratch.eligible.clear();
    scratch.removed.clear();
    scratch.added.clear();
    let mut seen = client.seen.lock().unwrap_or_else(|e| e.into_inner());
    if entities.is_empty() {
        if seen.is_empty() {
            return;
        }
        scratch.removed.extend(seen.iter().copied());
        scratch.removed.sort_unstable();
        let Ok(mut socket) = client.sock.lock() else {
            return;
        };
        if send_packet(&mut socket, 0x42, remove_entities_payload(scratch.removed.as_slice()))
            .is_err()
        {
            return;
        }
        for &eid in &scratch.removed {
            seen.remove(&eid);
        }
        return;
    }
    let chunks = client.chunks.lock().unwrap_or_else(|e| e.into_inner());
    if chunks.is_empty() {
        if seen.is_empty() {
            return;
        }
        scratch.removed.extend(seen.iter().copied());
        scratch.removed.sort_unstable();
        let Ok(mut socket) = client.sock.lock() else {
            return;
        };
        if send_packet(&mut socket, 0x42, remove_entities_payload(scratch.removed.as_slice()))
            .is_err()
        {
            return;
        }
        for &eid in &scratch.removed {
            seen.remove(&eid);
        }
        return;
    }
    let (dim, px, _, pz, _, _) = client_dim_pos(client);
    let view = *client.view.lock().unwrap_or_else(|e| e.into_inner());
    let player_chunk = (spatial_chunk_coord(px), spatial_chunk_coord(pz));
    let entity_chunks = index.ranges.len();
    let client_chunks = chunks.len();
    if client_chunks <= entity_chunks {
        for &(cx, cz) in chunks.iter() {
            if let Some(&(start, end)) = index.ranges.get(&(dim, cx, cz)) {
                for &entity_index in &index.order[start..end] {
                    let entity = &entities[entity_index];
                    if interest_entity_eligible(
                        client,
                        entity,
                        dim,
                        (px, pz),
                        player_chunk,
                        view,
                    ) {
                        scratch.eligible.push((entity.eid, entity_index));
                    }
                }
            }
        }
    } else {
        for (&(entity_dim, cx, cz), &(start, end)) in index.ranges.iter() {
            if entity_dim != dim || !chunks.contains(&(cx, cz)) {
                continue;
            }
            for &entity_index in &index.order[start..end] {
                let entity = &entities[entity_index];
                if interest_entity_eligible(
                    client,
                    entity,
                    dim,
                    (px, pz),
                    player_chunk,
                    view,
                ) {
                    scratch.eligible.push((entity.eid, entity_index));
                }
            }
        }
    }
    scratch
        .eligible
        .sort_unstable_by_key(|&(eid, _)| eid);
    for &eid in seen.iter() {
        if scratch
            .eligible
            .binary_search_by_key(&eid, |&(entity_eid, _)| entity_eid)
            .is_err()
        {
            scratch.removed.push(eid);
        }
    }
    scratch.removed.sort_unstable();
    for &(eid, entity_index) in &scratch.eligible {
        if !seen.contains(&eid) {
            scratch.added.push((eid, entity_index));
        }
    }
    // PID load shedding: under CPU pressure each client ingests only a
    // fraction of the new-entity burst per tick. The deferred spawns stay
    // unseen, so they re-enter `added` on the next tick — the cap throttles
    // wire work without dropping tracking state.
    let add_cap = live_scaled_tick_budget(scratch.added.len(), live_server_budget_scale());
    scratch.added.truncate(add_cap);
    if scratch.added.is_empty() && scratch.removed.is_empty() {
        return;
    }
    let Ok(mut socket) = client.sock.lock() else {
        return;
    };
    if !scratch.removed.is_empty() {
        if send_packet(&mut socket, 0x42, remove_entities_payload(scratch.removed.as_slice()))
            .is_err()
        {
            return;
        }
        for &eid in &scratch.removed {
            seen.remove(&eid);
        }
    }
    for &(eid, entity_index) in &scratch.added {
        // vanilla `ServerEntity.sendPairingData` wraps an entity's spawn
        // group (spawn + data + equipment) in a bundle so the client applies
        // the burst atomically.
        let packets = entities[entity_index].spawn.packets();
        let bundled = packets.len() > 1;
        if bundled
            && send_packet(&mut socket, 0x00, encode_play_bundle_delimiter().1).is_err()
        {
            return;
        }
        for (id, body) in packets {
            if id == 0x01 {
                with_play_wire(&socket, |play| play.remember_spawn(&body));
            }
            if send_packet(&mut socket, id, body).is_err() {
                return;
            }
        }
        if bundled
            && send_packet(&mut socket, 0x00, encode_play_bundle_delimiter().1).is_err()
        {
            return;
        }
        seen.insert(eid);
    }
}

#[cfg(test)]
fn sync_entity_interest(client: &Client, entities: &[TrackedSpawn]) {
    let index = InterestChunkIndex::new(entities);
    sync_entity_interest_indexed(client, entities, &index);
}

fn remove_entities_payload(entities: &[i32]) -> Vec<u8> {
    let mut p = Vec::new();
    write_varint(&mut p, entities.len() as i64);
    for &eid in entities {
        write_varint(&mut p, i64::from(eid));
    }
    p
}

// entity-scoped broadcast: only clients currently tracking <eid> —
// the tightest possible audience for per-entity update packets.
// chunk-scoped broadcast: only clients currently holding the chunk —
// block updates to an unloaded chunk would create phantom state.
#[cfg(test)]
fn broadcast_chunk_in<F: Fn(&Client) -> (i64, Vec<u8>)>(
    audience: &[Arc<Client>],
    cx: i32,
    cz: i32,
    mk: F,
) {
    broadcast_chunk_dim_in(DimId::Overworld, audience, cx, cz, mk)
}
/// The dimension-scoped chunk audience: a client only receives a block delta if it is in the
/// same dimension AND holds that column. Two players standing at the same `(cx, cz)` in
/// different dimensions must never see each other's edits.
fn broadcast_chunk_dim<F: Fn(&Client) -> (i64, Vec<u8>)>(dim: DimId, cx: i32, cz: i32, mk: F) {
    broadcast_chunk_dim_in(dim, &client_snapshot(), cx, cz, mk)
}
fn broadcast_chunk_dim_in<F: Fn(&Client) -> (i64, Vec<u8>)>(
    dim: DimId,
    audience: &[Arc<Client>],
    cx: i32,
    cz: i32,
    mk: F,
) {
    let mut shared = None;
    for client in audience {
        // Cheap dimension reject before the chunk/socket locks; the post-lock
        // check below still guards a mid-broadcast dimension switch.
        if *client.dim.lock().unwrap_or_else(|e| e.into_inner()) != dim {
            continue;
        }
        // Stream and unload take the chunk lock before the socket. Keep the
        // audience check in that order so a delta cannot follow an unload.
        let chunks = client.chunks.lock().unwrap_or_else(|e| e.into_inner());
        if !chunks.contains(&(cx, cz)) {
            continue;
        }
        let Ok(mut socket) = client.sock.lock() else {
            continue;
        };
        if *client.dim.lock().unwrap_or_else(|e| e.into_inner()) != dim {
            continue;
        }
        let (id, packet) = mk(client);
        if send_broadcast_frame(&mut socket, &mut shared, id, &packet).is_err() {
            let _ = socket.shutdown(std::net::Shutdown::Both);
        }
    }
}
fn broadcast_chunk_dim_packet(dim: DimId, cx: i32, cz: i32, id: i64, packet: &[u8]) {
    let audience = client_snapshot();
    let mut shared = None;
    for client in audience {
        if *client.dim.lock().unwrap_or_else(|e| e.into_inner()) != dim {
            continue;
        }
        let chunks = client.chunks.lock().unwrap_or_else(|e| e.into_inner());
        if !chunks.contains(&(cx, cz)) {
            continue;
        }
        let Ok(mut socket) = client.sock.lock() else {
            continue;
        };
        if *client.dim.lock().unwrap_or_else(|e| e.into_inner()) != dim {
            continue;
        }
        if send_broadcast_frame(&mut socket, &mut shared, id, packet).is_err() {
            let _ = socket.shutdown(std::net::Shutdown::Both);
        }
    }
}
fn broadcast_seen_destroy(eid: i32) {
    let p = remove_entities_payload(&[eid]);
    broadcast_seen_packet(eid, 0x42, &p);
}
// LOCK ORDER: these helpers acquire clients() internally — never call
// while holding clients().lock() (self-deadlock; hit twice: v1.56
// save_world drops(), v1.76 /effect). Collect targets under the lock,
// release, then broadcast.
fn broadcast_seen<F: Fn(&Client) -> (i64, Vec<u8>)>(eid: i32, mk: F) {
    broadcast_seen_ex(eid, 0, mk)
}
fn broadcast_seen_ex<F: Fn(&Client) -> (i64, Vec<u8>)>(eid: i32, excl: i32, mk: F) {
    broadcast_seen_ex_in(&client_snapshot(), eid, excl, mk)
}
fn broadcast_seen_ex_in<F: Fn(&Client) -> (i64, Vec<u8>)>(
    audience: &[Arc<Client>],
    eid: i32,
    excl: i32,
    mk: F,
) {
    let mut shared = None;
    for client in audience.iter().filter(|c| c.eid != excl) {
        // Serialize updates with the tracking sweep's spawn and remove packets.
        let seen = client.seen.lock().unwrap_or_else(|e| e.into_inner());
        if seen.contains(&eid) {
            let (id, packet) = mk(client);
            if let Ok(mut socket) = client.sock.lock() {
                let _ = send_broadcast_frame(&mut socket, &mut shared, id, &packet);
            }
        }
    }
}

/// Position-scoped broadcast: vanilla `PlayerList.broadcast(except, x, y, z,
/// radius, dimension, packet)` reaches only same-dimension players strictly
/// inside `radius` of the effect. The radius is read from the packet itself
/// (`connection_limits::broadcast_radius`), so a packet id with no vanilla
/// range contract — chat, weather, player-info — is refused rather than sent
/// to the whole list; this is for sounds, particles and explosions only.
fn broadcast_near<F: Fn(&Client) -> (i64, Vec<u8>)>(
    dim: DimId,
    x: f64,
    y: f64,
    z: f64,
    me_eid: i32,
    mk: F,
) {
    broadcast_near_in(dim, &client_snapshot(), x, y, z, me_eid, mk)
}
fn broadcast_near_in<F: Fn(&Client) -> (i64, Vec<u8>)>(
    dim: DimId,
    audience: &[Arc<Client>],
    x: f64,
    y: f64,
    z: f64,
    me_eid: i32,
    mk: F,
) {
    let mut shared = None;
    for client in audience.iter().filter(|c| c.eid != me_eid) {
        if *client.dim.lock().unwrap_or_else(|e| e.into_inner()) != dim {
            continue;
        }
        let (id, packet) = mk(client);
        let Some(radius) = connection_limits::broadcast_radius(id, &packet) else {
            continue;
        };
        let (px, py, pz, ..) = *client.pos.lock().unwrap_or_else(|e| e.into_inner());
        if !connection_limits::within_broadcast_range(px, py, pz, x, y, z, radius) {
            continue;
        }
        if let Ok(mut socket) = client.sock.lock() {
            let _ = send_broadcast_frame(&mut socket, &mut shared, id, &packet);
        }
    }
}

fn broadcast_near_packet(
    dim: DimId,
    x: f64,
    y: f64,
    z: f64,
    me_eid: i32,
    id: i64,
    packet: &[u8],
) {
    let audience = client_snapshot();
    let Some(radius) = connection_limits::broadcast_radius(id, packet) else {
        return;
    };
    let mut shared = None;
    for client in audience.iter().filter(|c| c.eid != me_eid) {
        if *client.dim.lock().unwrap_or_else(|e| e.into_inner()) != dim {
            continue;
        }
        let (px, py, pz, ..) = *client.pos.lock().unwrap_or_else(|e| e.into_inner());
        if !connection_limits::within_broadcast_range(px, py, pz, x, y, z, radius) {
            continue;
        }
        if let Ok(mut socket) = client.sock.lock() {
            let _ = send_broadcast_frame(&mut socket, &mut shared, id, packet);
        }
    }
}

// broadcast helpers return (packet_id, payload)

fn spawn_typed_pkt(eid: i32, etype: i64, x: f64, y: f64, z: f64) -> Vec<u8> {
    let mut p = Vec::new();
    write_varint(&mut p, eid as i64);
    p.extend_from_slice(&[0u8; 16]);
    write_varint(&mut p, etype);
    p.extend_from_slice(&x.to_be_bytes());
    p.extend_from_slice(&y.to_be_bytes());
    p.extend_from_slice(&z.to_be_bytes());
    p.extend_from_slice(&[0u8; 3]);
    write_varint(&mut p, 0);
    p.extend_from_slice(&[0u8; 6]);
    p
}

fn read_varint_at(b: &[u8], p: usize) -> (i64, usize) {
    let (v, n) = megu_core::varint::read_varlong_i64(&b[p..])
        .expect("read_varint_at: malformed varint");
    (v, p + n)
}

fn velocity_pkt(eid: i32, vx: i16, vy: i16, vz: i16) -> Vec<u8> {
    let mut p = Vec::new();
    write_varint(&mut p, eid as i64);
    p.extend_from_slice(&vx.to_be_bytes());
    p.extend_from_slice(&vy.to_be_bytes());
    p.extend_from_slice(&vz.to_be_bytes());
    p
}

/// Decode the carried stack a container-click packet claims to hold. The tail
/// after the click mode is `changedSlots` (varint-sized map of slot -> stack)
/// followed by the carried `ItemStack`. Map entries embed full stacks whose
/// boundaries need the component-aware decoder, so a non-empty map yields
/// `None` and callers fall back to a conservative rule.
fn click_carried_stack(tail: &[u8]) -> Option<Stack> {
    let mut p = tail;
    if read_protocol_i32(&mut p)? != 0 {
        return None;
    }
    let mut buf = vec![0u8, 0u8];
    buf.extend_from_slice(p);
    slot_read_wire(&buf).map(|(_, st)| st)
}

fn hotbar_swap_slot(button: i8) -> Option<i16> {
    (0..=8).contains(&button).then_some(36 + i16::from(button))
}

fn crafting_remainder(item: i64) -> Option<Stack> {
    let name = item_to_name(item)?;
    if name.ends_with("_bucket") && name != "bucket" {
        Some((name_to_item("bucket")?, 1, Vec::new()))
    } else {
        None
    }
}

fn consume_crafting_grid(
    grid: &mut HashMap<i16, Stack>,
    slots: std::ops::RangeInclusive<i16>,
) -> Vec<Stack> {
    let mut overflow = Vec::new();
    for slot in slots {
        let Some((item, count, comps)) = grid.get(&slot).cloned() else {
            continue;
        };
        if count == 0 {
            continue;
        }
        let remainder = crafting_remainder(item);
        if count == 1 {
            if let Some(remainder) = remainder {
                grid.insert(slot, remainder);
            } else {
                grid.remove(&slot);
            }
        } else {
            grid.insert(slot, (item, count - 1, comps));
            if let Some(remainder) = remainder {
                overflow.push(remainder);
            }
        }
    }
    overflow
}

fn return_crafting_grid_to_inventory(
    inv: &mut HashMap<i16, Stack>,
    grid: &mut HashMap<i16, Stack>,
) -> Vec<Stack> {
    let mut overflow = Vec::new();
    for stack in std::mem::take(grid).into_values() {
        let remainder = move_to_slots(inv, 9..=44, stack);
        if remainder.1 > 0 {
            overflow.push(remainder);
        }
    }
    overflow
}

fn quick_move_crafting_result(
    inv: &mut HashMap<i16, Stack>,
    grid: &mut HashMap<i16, Stack>,
    slots: std::ops::RangeInclusive<i16>,
    result: fn(&HashMap<i16, Stack>) -> Option<Stack>,
) -> Vec<Stack> {
    let mut overflow = Vec::new();
    for _ in 0..64 {
        let Some(output) = result(grid) else { break };
        let mut trial = inv.clone();
        if move_to_slots(&mut trial, 9..=44, output).1 > 0 {
            break;
        }
        *inv = trial;
        for remainder in consume_crafting_grid(grid, slots.clone()) {
            let remainder = move_to_slots(inv, 9..=44, remainder);
            if remainder.1 > 0 {
                overflow.push(remainder);
            }
        }
    }
    overflow
}

/// Hurt Animation (`0x24`): entity id + the hurt direction yaw vanilla computes
/// in `ServerPlayer.indicateDamage` (`getHurtDir`).
fn hurt_anim_yaw(eid: i32, yaw: f32) -> Vec<u8> {
    let mut p = Vec::new();
    write_varint(&mut p, eid as i64);
    p.extend_from_slice(&yaw.to_be_bytes());
    p
}

/// Entity Event (`0x1f`): i32 entity id + i8 status. Status 3 is the death
/// event vanilla broadcasts from `LivingEntity.die`.
fn entity_event_pkt(eid: i32, status: i8) -> Vec<u8> {
    let mut p = Vec::new();
    p.extend_from_slice(&eid.to_be_bytes());
    p.push(status as u8);
    p
}

/// Vanilla `LivingEntity.knockback(0.4, dx, dz)` for a bare-hand player hit,
/// reduced to the `SetEntityMotion` shorts. `pp`/`vp` are attacker/victim
/// `(x, y, z, yaw, pitch, on_ground)`. Player knockback resistance is always 0
/// here, so the strength is the vanilla 0.4 constant.
fn vanilla_knockback(
    vp: &(f64, f64, f64, f32, f32, bool),
    pp: &(f64, f64, f64, f32, f32, bool),
) -> (i16, i16, i16) {
    let strength = 0.4f64;
    let (mut dx, mut dz) = (pp.0 - vp.0, pp.2 - vp.2);
    if dx * dx + dz * dz < 1e-10 {
        // Vanilla rerolls a random direction here; a deterministic zero keeps
        // the packet stable for the degenerate same-position case.
        dx = 0.0;
        dz = 0.0;
    } else {
        let len = (dx * dx + dz * dz).sqrt();
        dx /= len;
        dz /= len;
    }
    // Players have no server-side velocity state; a settled on-ground body
    // carries vanilla's one-tick gravity residue (-0.08 * 0.98 drag).
    let old_y = if vp.5 { -0.08 * 0.98 } else { 0.0 };
    let nx = 0.0f64 / 2.0 - dx * strength;
    let ny = if vp.5 {
        (old_y / 2.0 + strength).min(0.4)
    } else {
        old_y
    };
    let nz = 0.0f64 / 2.0 - dz * strength;
    (
        (nx.clamp(-3.9, 3.9) * 8000.0) as i16,
        (ny.clamp(-3.9, 3.9) * 8000.0) as i16,
        (nz.clamp(-3.9, 3.9) * 8000.0) as i16,
    )
}

fn spawn_mob(m: &Mob) -> Vec<u8> {
    let (x, y, z, yaw, pitch) = *m.pos.lock().unwrap_or_else(|e| e.into_inner());
    let mut p = Vec::new();
    write_varint(&mut p, m.eid as i64);
    p.extend_from_slice(&m.uuid);
    write_varint(&mut p, m.etype);
    p.extend_from_slice(&x.to_be_bytes());
    p.extend_from_slice(&y.to_be_bytes());
    p.extend_from_slice(&z.to_be_bytes());
    spawn_angles(&mut p, yaw, pitch);
    write_varint(&mut p, 0);
    p.extend_from_slice(&[0u8; 6]);
    p
}
#[allow(clippy::too_many_arguments)]
fn spawn_entity_pkt(
    eid: i32,
    etype: u32,
    x: f64,
    y: f64,
    z: f64,
    yaw: f32,
    pitch: f32,
    data: i64,
) -> Vec<u8> {
    let mut p = Vec::new();
    write_varint(&mut p, eid as i64);
    p.extend_from_slice(&[0u8; 16]);
    write_varint(&mut p, etype as i64);
    p.extend_from_slice(&x.to_be_bytes());
    p.extend_from_slice(&y.to_be_bytes());
    p.extend_from_slice(&z.to_be_bytes());
    spawn_angles(&mut p, yaw, pitch);
    write_varint(&mut p, data);
    p.extend_from_slice(&[0u8; 6]);
    p
}
/// `minecraft:falling_block` (entity type 40) carries its block state as the spawn packet's
/// object data, so the client renders the right block while it falls.
fn spawn_falling_pkt(eid: i32, state: u32, x: f64, y: f64, z: f64) -> Vec<u8> {
    let mut p = Vec::new();
    write_varint(&mut p, eid as i64);
    p.extend_from_slice(&[0u8; 16]);
    write_varint(&mut p, 40);
    p.extend_from_slice(&x.to_be_bytes());
    p.extend_from_slice(&y.to_be_bytes());
    p.extend_from_slice(&z.to_be_bytes());
    p.extend_from_slice(&[0u8; 3]);
    write_varint(&mut p, state as i64);
    p.extend_from_slice(&[0u8; 6]);
    p
}

// sound/particle id subsets (minecraft-data 1.21.1 registries, unnamespaced)
// sound_effect packet (0x68): named sound at a position, ambient cat
fn sound_pkt_named(name: &str, x: f64, y: f64, z: f64) -> Vec<u8> {
    let mut p = Vec::new();
    write_varint(&mut p, sound_id(name).unwrap_or(0) as i64 + 1);
    write_varint(&mut p, 0);
    p.extend_from_slice(&((x * 8.0) as i32).to_be_bytes());
    p.extend_from_slice(&((y * 8.0) as i32).to_be_bytes());
    p.extend_from_slice(&((z * 8.0) as i32).to_be_bytes());
    p.extend_from_slice(&1.0f32.to_be_bytes());
    p.extend_from_slice(&1.0f32.to_be_bytes());
    p.extend_from_slice(&0i64.to_be_bytes());
    p
}
