fn resource_pack_pkt() -> Option<Vec<u8>> {
    let (url, hash) = pack_info().as_ref()?;
    let mut p = Vec::new();
    p.extend_from_slice(&[0xabu8; 16]); // uuid
    write_str(&mut p, url);
    write_str(&mut p, hash);
    p.push(resource_pack_required() as u8);
    p.push(0); // no prompt
    Some(p)
}
/// Whether the configured resource pack is mandatory. The server config's
/// `resource_pack_required` key boots into `MEGU_RESOURCE_PACK_REQUIRED`;
/// a Vanilla `server.properties` says `require-resource-pack`. Either marks the
/// pack required.
fn resource_pack_required() -> bool {
    fn truthy(value: &str) -> bool {
        matches!(
            value.trim().to_ascii_lowercase().as_str(),
            "1" | "true" | "yes"
        )
    }
    std::env::var("MEGU_RESOURCE_PACK_REQUIRED").is_ok_and(|v| truthy(&v))
        || server_properties_lookup("require-resource-pack").is_some_and(|v| truthy(&v))
}

// ---------- config blob replay ----------
// Registry packet order in the vanilla 1.21.1 configuration capture.
const SYNCED_REGISTRIES: [&str; 11] = [
    "worldgen/biome",
    "chat_type",
    "trim_pattern",
    "trim_material",
    "wolf_variant",
    "painting_variant",
    "dimension_type",
    "damage_type",
    "banner_pattern",
    "enchantment",
    "jukebox_song",
];

/// Build Configuration 0x07 payloads (starting at the registry ID) from pack
/// files in low-to-high priority order. Directory and ZIP readers supply paths
/// relative to the pack root. A partial input emits only its populated registries.
fn build_registry_data_payloads<'a>(
    packs: impl IntoIterator<Item = impl IntoIterator<Item = (&'a str, &'a [u8])>>,
) -> Result<Vec<Vec<u8>>, String> {
    let mut registries = std::collections::BTreeMap::<_, std::collections::BTreeMap<_, _>>::new();
    for (priority, files) in packs.into_iter().enumerate() {
        for (file, json) in files {
            let Some((namespace, relative)) = file
                .strip_prefix("data/")
                .and_then(|path| path.split_once('/'))
            else {
                continue;
            };
            let Some(relative) = relative.strip_suffix(".json") else {
                continue;
            };
            let Some((kind, path)) = SYNCED_REGISTRIES.iter().find_map(|&kind| {
                let path = relative.strip_prefix(kind)?.strip_prefix('/')?;
                Some((kind, path))
            }) else {
                continue;
            };
            // Vanilla ResourceLocation orders by path, then by namespace.
            let previous = registries
                .entry(kind)
                .or_default()
                .insert((path, namespace), (priority, file, json));
            if previous.is_some_and(|(previous_priority, _, _)| previous_priority == priority) {
                return Err(format!("duplicate registry file {file} in one datapack"));
            }
        }
    }

    let mut payloads = Vec::new();
    for kind in SYNCED_REGISTRIES {
        let Some(entries) = registries.remove(kind) else {
            continue;
        };
        let mut payload = Vec::new();
        write_str(&mut payload, &format!("minecraft:{kind}"));
        let count = i32::try_from(entries.len()).map_err(|_| "too many registry entries")?;
        write_varint(&mut payload, i64::from(count));
        for ((path, namespace), (_, file, json)) in entries {
            let location = brigadier_wire::ResourceLocation::new(namespace, path)
                .map_err(|_| format!("invalid registry entry path {file}"))?;
            let id = location.to_string();
            if id.len() > 32_767 || path.split('/').any(|part| matches!(part, "" | "." | "..")) {
                return Err(format!("invalid registry entry path {file}"));
            }
            let mut tag =
                nbt::registry_json_to_nbt(json).map_err(|err| format!("{file}: {err}"))?;
            if kind == "worldgen/biome" {
                // Biome's network codec carries only the climate and effects.
                if let nbt::Tag::Compound(fields) = &mut tag {
                    for field in [
                        "carvers",
                        "features",
                        "spawn_costs",
                        "spawners",
                        "creature_spawn_probability",
                    ] {
                        fields.remove(&nbt::NbtString::text(field));
                    }
                }
            }
            write_str(&mut payload, &id);
            payload.push(1); // Optional NBT is present for every entry.
            payload.extend(nbt::write_network_nbt(&tag).map_err(|err| format!("{file}: {err}"))?);
        }
        payloads.push(payload);
    }
    Ok(payloads)
}

fn registry_pack_files(
    base: &std::path::Path,
    zip: bool,
) -> std::io::Result<Vec<(String, Vec<u8>)>> {
    if zip {
        let mut bytes = Vec::new();
        std::fs::File::open(base)?
            .take(ZIP_MAX_BYTES as u64 + 1)
            .read_to_end(&mut bytes)?;
        return (bytes.len() <= ZIP_MAX_BYTES)
            .then(|| zip_datapack_entries(&bytes))
            .flatten()
            .ok_or_else(|| std::io::Error::other("invalid or unsupported registry datapack ZIP"));
    }
    let data = base.join("data");
    let namespaces = match std::fs::read_dir(data) {
        Ok(entries) => entries,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(Vec::new()),
        Err(error) => return Err(error),
    };
    let mut files = Vec::new();
    for namespace in namespaces {
        let namespace = namespace?;
        if !namespace.file_type()?.is_dir() {
            continue;
        }
        for kind in SYNCED_REGISTRIES {
            let mut dirs = vec![namespace.path().join(kind)];
            while let Some(dir) = dirs.pop() {
                let entries = match std::fs::read_dir(dir) {
                    Ok(entries) => entries,
                    Err(error) if error.kind() == std::io::ErrorKind::NotFound => continue,
                    Err(error) => return Err(error),
                };
                for entry in entries {
                    let entry = entry?;
                    let file_type = entry.file_type()?;
                    let path = entry.path();
                    if file_type.is_dir() {
                        dirs.push(path);
                    } else if file_type.is_file() && path.extension().is_some_and(|e| e == "json") {
                        if let Some(name) = path.strip_prefix(base).ok().and_then(|p| p.to_str()) {
                            files.push((name.replace('\\', "/"), std::fs::read(path)?));
                        }
                    }
                }
            }
        }
    }
    Ok(files)
}

fn load_registry_overlays(base: &std::path::Path) -> Result<Vec<Vec<u8>>, String> {
    let mut sources = datapack_sources(base);
    // The built-in pack is the base. User packs follow in the server's pack order.
    sources.sort_by_key(|(name, _, _)| name != "vanilla");
    let disabled = disabled_datapacks().lock().unwrap_or_else(|e| e.into_inner()).clone();
    let mut packs = Vec::new();
    for (name, path, zip) in sources {
        if !disabled.contains(&name) {
            packs
                .push(registry_pack_files(&path, zip).map_err(|error| format!("{name}: {error}"))?);
        }
    }
    build_registry_data_payloads(packs.iter().map(|files| {
        files
            .iter()
            .map(|(name, data)| (name.as_str(), data.as_slice()))
    }))
}

fn captured_config_packets() -> Option<Vec<(i64, Vec<u8>)>> {
    let data = std::fs::read("config_packets.bin").ok()?;
    let mut packets = Vec::new();
    let mut input = data.as_slice();
    while !input.is_empty() {
        let len = usize::try_from(read_protocol_i32(&mut input)?).ok()?;
        let (packet, rest) = input.split_at_checked(len)?;
        let id = read_protocol_i32(&mut &packet[..])?;
        packets.push((i64::from(id), packet.to_vec()));
        input = rest;
    }
    Some(packets)
}

fn registry_wire_name<'a>(input: &mut &'a [u8]) -> Option<&'a str> {
    let len = usize::try_from(read_protocol_i32(input)?).ok()?;
    let (name, rest) = input.split_at_checked(len)?;
    *input = rest;
    std::str::from_utf8(name).ok()
}

fn config_registry_header(packet: &[u8]) -> Option<(&str, &[u8])> {
    let mut input = packet;
    (read_protocol_i32(&mut input)? == 0x07).then_some(())?;
    let name = registry_wire_name(&mut input)?;
    Some((name, input))
}

fn registry_wire_entries(mut input: &[u8]) -> Option<Vec<(&str, &[u8])>> {
    let count = read_protocol_i32(&mut input)?;
    if !(0..=4096).contains(&count) {
        return None;
    }
    let mut entries = Vec::with_capacity(count as usize);
    for _ in 0..count {
        let name = registry_wire_name(&mut input)?;
        let entry = input;
        let (&has_nbt, body) = input.split_first()?;
        let mut end = 0;
        match has_nbt {
            0 => {}
            1 if nbt_wire_skip(body, &mut end, 0) => {}
            _ => return None,
        }
        let (entry, rest) = entry.split_at_checked(1 + end)?;
        entries.push((name, entry));
        input = rest;
    }
    input.is_empty().then_some(entries)
}

fn merge_registry_overlays(config: &mut [(i64, Vec<u8>)], overlays: &[Vec<u8>]) -> Option<()> {
    let mut pending = HashMap::new();
    for payload in overlays {
        let mut body = payload.as_slice();
        let name = registry_wire_name(&mut body)?;
        pending.insert(name, registry_wire_entries(body)?);
    }
    let mut replacements = Vec::new();
    for (index, (_, packet)) in config.iter().enumerate().filter(|(_, (id, _))| *id == 0x07) {
        let (name, body) = config_registry_header(packet)?;
        let Some(entries) = pending.remove(name) else {
            continue;
        };
        let mut overrides: HashMap<_, _> = entries.iter().copied().collect();
        let mut ordered = registry_wire_entries(body)?;
        for (id, payload) in &mut ordered {
            if let Some(replacement) = overrides.remove(id) {
                *payload = replacement;
            }
        }
        // Keep baseline numeric IDs stable for Update Tags, chunk biome IDs and
        // dimension IDs. New entries are appended in the builder's order.
        ordered.extend(
            entries
                .into_iter()
                .filter(|(id, _)| overrides.contains_key(id)),
        );
        let mut merged = vec![0x07];
        write_str(&mut merged, name);
        write_varint(&mut merged, ordered.len() as i64);
        for (id, payload) in ordered {
            write_str(&mut merged, id);
            merged.extend_from_slice(payload);
        }
        replacements.push((index, merged));
    }
    if !pending.is_empty() {
        return None;
    }
    for (index, packet) in replacements {
        config[index].1 = packet;
    }
    Some(())
}

fn load_config_packets() -> Vec<(i64, Vec<u8>)> {
    let Some(mut config) = captured_config_packets() else {
        eprintln!(
            "[spine] missing or invalid config_packets.bin. {}",
            worldgen::VANILLA_DATA_MISSING
        );
        return Vec::new();
    };
    match load_registry_overlays(std::path::Path::new(DATAPACK_DIRECTORY)) {
        Ok(overlays) => {
            if merge_registry_overlays(&mut config, &overlays).is_none() {
                eprintln!("[spine] unable to merge datapack registries into config_packets.bin");
            }
        }
        Err(error) => eprintln!("[spine] unable to load datapack registries: {error}"),
    }
    append_custom_dimension_types(&mut config);
    config_tags_merge(&mut config);
    config
}

/// The `minecraft:dimension_type` entry NBT a registered custom dimension declares,
/// in the field order the vanilla registry writer emits.
fn custom_dimension_type_nbt(spec: &worldgen::DimensionSpec) -> nbt::Tag {
    let b = |v: bool| nbt::Tag::Byte(v as i8);
    let t = nbt::NbtString::text;
    let mut fields = std::collections::BTreeMap::new();
    fields.insert(t("piglin_safe"), b(spec.piglin_safe));
    fields.insert(t("has_raids"), b(spec.has_raids));
    fields.insert(
        t("monster_spawn_light_level"),
        nbt::Tag::Int(spec.monster_spawn_light_level),
    );
    fields.insert(
        t("monster_spawn_block_light_limit"),
        nbt::Tag::Int(spec.monster_spawn_block_light_limit),
    );
    fields.insert(t("natural"), b(spec.natural));
    fields.insert(
        t("ambient_light"),
        nbt::Tag::Float(spec.ambient_light.to_bits()),
    );
    if let Some(fixed_time) = spec.fixed_time {
        fields.insert(t("fixed_time"), nbt::Tag::Long(fixed_time));
    }
    fields.insert(
        t("infiniburn"),
        nbt::Tag::String(t(&spec.infiniburn)),
    );
    fields.insert(t("respawn_anchor_works"), b(spec.respawn_anchor_works));
    fields.insert(t("has_skylight"), b(spec.has_skylight));
    fields.insert(t("bed_works"), b(spec.bed_works));
    fields.insert(t("effects"), nbt::Tag::String(t(&spec.effects)));
    fields.insert(t("min_y"), nbt::Tag::Int(spec.min_y));
    fields.insert(t("height"), nbt::Tag::Int(spec.height));
    fields.insert(t("logical_height"), nbt::Tag::Int(spec.logical_height));
    fields.insert(
        t("coordinate_scale"),
        nbt::Tag::Double(spec.coordinate_scale.to_bits()),
    );
    fields.insert(t("ultrawarm"), b(spec.ultrawarm));
    fields.insert(t("has_ceiling"), b(spec.has_ceiling));
    nbt::Tag::Compound(fields)
}

/// Append the registered custom `dimension_type` entries to the merged `0x07` registry
/// packet — a datapack may already carry its type file (merged by the overlays), in
/// which case only the wire-id table learns its position — and record every entry's
/// wire index so `dim_type_wire_id` can answer for custom dimensions.
fn append_custom_dimension_types(config: &mut [(i64, Vec<u8>)]) {
    let specs = worldgen::custom_dimension_specs();
    if specs.is_empty() {
        return;
    }
    for (_, packet) in config.iter_mut().filter(|(id, _)| *id == 0x07) {
        let Some((name, body)) = config_registry_header(packet) else {
            continue;
        };
        if name != "minecraft:dimension_type" {
            continue;
        }
        let Some(entries) = registry_wire_entries(body) else {
            continue;
        };
        let mut ids: HashMap<String, i32> = entries
            .iter()
            .enumerate()
            .map(|(index, (entry, _))| (entry.to_string(), index as i32))
            .collect();
        let mut appended = Vec::new();
        for spec in &specs {
            if ids.contains_key(spec.type_key) {
                continue;
            }
            let Ok(nbt) = nbt::write_network_nbt(&custom_dimension_type_nbt(spec)) else {
                eprintln!("[spine] cannot encode dimension_type {}", spec.type_key);
                continue;
            };
            let mut entry = Vec::new();
            entry.push(1); // Optional NBT present.
            entry.extend_from_slice(&nbt);
            let index = (entries.len() + appended.len()) as i32;
            ids.insert(spec.type_key.to_string(), index);
            appended.push((spec.type_key, entry));
        }
        {
            let mut table = dim_type_entry_ids().lock().unwrap_or_else(|e| e.into_inner());
            for spec in &specs {
                if let Some(&index) = ids.get(spec.type_key) {
                    table.insert(spec.type_key, index);
                }
            }
        }
        if appended.is_empty() {
            continue;
        }
        let count = entries.len() + appended.len();
        let mut merged = vec![0x07];
        write_str(&mut merged, name);
        write_varint(&mut merged, count as i64);
        for (id, payload) in entries {
            write_str(&mut merged, id);
            merged.extend_from_slice(payload);
        }
        for (id, payload) in appended {
            write_str(&mut merged, id);
            merged.extend_from_slice(&payload);
        }
        *packet = merged;
    }
}

/// `type_key -> wire index` for the `minecraft:dimension_type` entries registered
/// custom dimensions reference, published by `append_custom_dimension_types` when the
/// config blob is built.
fn dim_type_entry_ids() -> &'static Mutex<HashMap<&'static str, i32>> {
    static IDS: OnceLock<Mutex<HashMap<&'static str, i32>>> = OnceLock::new();
    IDS.get_or_init(Mutex::default)
}

fn player_attack_damage_wire_id(config: &[(i64, Vec<u8>)]) -> Option<i32> {
    let mut registry = None;
    for (_, packet) in config.iter().filter(|(id, _)| *id == 0x07) {
        let (name, body) = config_registry_header(packet)?;
        if name == "minecraft:damage_type" && registry.replace(body).is_some() {
            return None;
        }
    }
    let mut matches = registry_wire_entries(registry?)?
        .into_iter()
        .enumerate()
        .filter(|(_, (name, _))| *name == "minecraft:player_attack");
    let (index, _) = matches.next()?;
    matches.next().is_none().then_some(index as i32)
}

/// S2C `0x55` SetChunkCacheRadius + `0x62` SetSimulationDistance: sent right
/// after Join Game and whenever the client's effective view distance changes.
/// Both radii come from the live server config (`MEGU_VIEW_DISTANCE` /
/// `MEGU_SIMULATION_DISTANCE`, `server.toml`/`server.properties` included,
/// each clamped to Vanilla's `2..=32`).
fn send_view_distance(s: &mut TcpStream, view: i32) {
    let mut p = Vec::new();
    write_varint(&mut p, i64::from(view));
    let _ = send_packet(s, 0x55, p);
    let mut p = Vec::new();
    write_varint(&mut p, i64::from(live_simulation_distance()));
    let _ = send_packet(s, 0x62, p);
}

/// Decode protocol 767 Client Information; view distance is a signed Byte.
/// The connection bounds the requested value, not the packet decoder.
fn client_info_view_distance(body: &[u8]) -> Option<i32> {
    let mut p = body;
    let len = usize::try_from(read_protocol_i32(&mut p)?).ok()?;
    if len > 64 || p.len() < len {
        return None;
    }
    let locale = std::str::from_utf8(&p[..len]).ok()?;
    if locale.encode_utf16().count() > 16 {
        return None;
    }
    p = &p[len..];
    let view = *p.first()? as i8 as i32;
    p = &p[1..];
    if !(0..=2).contains(&read_protocol_i32(&mut p)?) {
        return None;
    } // chat mode
    if p.len() < 2 {
        return None;
    }
    p = &p[2..]; // chat colours and skin parts
    if !(0..=1).contains(&read_protocol_i32(&mut p)?) {
        return None;
    } // main hand
    if p.len() != 2 {
        return None;
    } // filtering and server listings
    Some(view)
}

/// Per-connection configuration-phase link state. Vanilla runs the
/// configuration stage under the same `CommonListenerCookie` keep-alive
/// machinery the play loop uses; `ConfigLink` carries that state plus the
/// answers that arrive while the phase is open (a late client-information
/// view distance, a resource-pack status, a pong, a stored cookie) so the
/// join and reconfigure paths can merge them into the play-phase stores
/// afterwards.
struct ConfigLink {
    keepalive: connection_limits::KeepaliveState,
    next_keepalive_id: i64,
    client_view: i32,
    /// Latest resource-pack status the client reported; when a pack was
    /// pushed the finish packet is held until a *terminal* one (loaded,
    /// declined, failed download, invalid url or failed reload) lands,
    /// matching `ServerResourcePackConfigurationTask` ordering.
    rp_status: Option<i64>,
    last_pong: Option<i32>,
    cookies: HashMap<String, Option<Vec<u8>>>,
}

impl ConfigLink {
    fn new(client_view: i32) -> Self {
        Self {
            keepalive: connection_limits::KeepaliveState::new(Instant::now()),
            next_keepalive_id: 1,
            client_view,
            rp_status: None,
            last_pong: None,
            cookies: HashMap::new(),
        }
    }
}

/// Configuration `disconnect` (`0x02`): the reason is a network-NBT chat
/// component — unlike the login-phase JSON string — exactly like play `0x1d`.
fn send_config_disconnect(s: &mut TcpStream, compression: Option<usize>, reason: &str) {
    let mut pkt = Vec::new();
    write_varint(&mut pkt, 0x02);
    pkt.extend_from_slice(&chat_nbt(reason));
    let _ = write_frame(s, &pkt, compression);
}

/// The configuration keep-alive pair vanilla issues on `KEEPALIVE_INTERVAL`:
/// `keep_alive` (`0x04`, the outstanding i64) plus `ping` (`0x05`, the same
/// value truncated to i32) so the client answers both probes.
fn send_config_keepalive(
    s: &mut TcpStream,
    compression: Option<usize>,
    id: i64,
) -> std::io::Result<()> {
    let mut pkt = Vec::new();
    write_varint(&mut pkt, 0x04);
    pkt.extend_from_slice(&id.to_be_bytes());
    write_frame(s, &pkt, compression)?;
    let mut pkt = Vec::new();
    write_varint(&mut pkt, 0x05);
    pkt.extend_from_slice(&(id as i32).to_be_bytes());
    write_frame(s, &pkt, compression)
}

/// Configuration `reset_chat` (`0x06`): no body — the client drops its chat
/// chain, which is why a mid-play `start_configuration` re-entry also clears
/// `chat_sessions`/`chat_ack_offsets` server-side.
fn send_config_reset_chat(s: &mut TcpStream, compression: Option<usize>) -> std::io::Result<()> {
    let mut pkt = Vec::new();
    write_varint(&mut pkt, 0x06);
    write_frame(s, &pkt, compression)
}

/// One keep-alive cadence pass inside a configuration wait loop: on a due
/// interval with no pending challenge the `0x04`/`0x05` pair goes out; an
/// unanswered challenge that ages past the interval ends the phase with a
/// vanilla `Timed out` disconnect.
fn config_keepalive_tick(
    s: &mut TcpStream,
    compression: Option<usize>,
    link: &mut ConfigLink,
) -> bool {
    use connection_limits::KeepaliveAction;
    match link.keepalive.tick(Instant::now(), link.next_keepalive_id) {
        KeepaliveAction::Send(id) => {
            if send_config_keepalive(s, compression, id).is_err() {
                return false;
            }
            link.next_keepalive_id = link.next_keepalive_id.wrapping_add(1);
            true
        }
        KeepaliveAction::TimedOut => {
            send_config_disconnect(s, compression, "Timed out");
            false
        }
        KeepaliveAction::Wait => true,
    }
}

/// One polled configuration read's verdict for the wait loops: `Frame` is a
/// packet the current stage is waiting on, `Serviced` means the async surface
/// was handled inline (keep waiting), `Abort` means the connection is over
/// (EOF, rate-limit or a sent disconnect).
enum ConfigPoll {
    Frame(i64),
    Serviced,
    Abort,
}

/// Poll one inbound frame during configuration. Keep-alive answers (`0x04`)
/// are checked against the outstanding challenge, pongs (`0x05`) are
/// recorded, client-information (`0x00`) re-reads the requested view
/// distance, cookie responses (`0x01`) land on the pre-entity store, and
/// resource-pack responses (`0x06`) apply the required/stale-pack policy —
/// including the `remove_resource_pack` (`0x08`, uuid omitted = pop all) a
/// client with an old pack needs when this server advertises none. The ids a
/// stage waits on (`0x07` select_known_packs, `0x03` finish ack) pass through
/// as `Frame`.
fn config_next_frame(
    s: &mut TcpStream,
    rx: &mut RxBuf,
    compression: Option<usize>,
    rate: &mut connection_limits::PacketRateLimit,
    link: &mut ConfigLink,
) -> ConfigPoll {
    let (id, b) = match rx.next(s) {
        RxOut::Closed => return ConfigPoll::Abort,
        RxOut::Idle => {
            return if config_keepalive_tick(s, compression, link) {
                ConfigPoll::Serviced
            } else {
                ConfigPoll::Abort
            };
        }
        RxOut::Frame(id, b) => (id, b),
    };
    let received = Instant::now();
    if !rate.allow(received) {
        if rate.should_disconnect(received) {
            send_config_disconnect(s, compression, "Packet rate limit exceeded");
            return ConfigPoll::Abort;
        }
        return ConfigPoll::Serviced;
    }
    match id {
        0x00 => match client_info_view_distance(&b) {
            Some(v) => {
                link.client_view = v;
                ConfigPoll::Serviced
            }
            None => {
                send_config_disconnect(s, compression, "Invalid client information");
                ConfigPoll::Abort
            }
        },
        0x01 => {
            if let Some((key, payload)) = decode_cookie_response(&b) {
                link.cookies.insert(key, payload);
            }
            ConfigPoll::Serviced
        }
        0x04 => {
            if link.keepalive.reply(received, &b) {
                ConfigPoll::Serviced
            } else {
                send_config_disconnect(s, compression, "Timed out");
                ConfigPoll::Abort
            }
        }
        0x05 => {
            if let Some(pong) = decode_pong(&b) {
                link.last_pong = Some(pong);
            }
            ConfigPoll::Serviced
        }
        0x06 => {
            let mut p = &b[..];
            link.rp_status = read_varint(&mut p);
            if pack_info().is_none() && link.rp_status.is_some() {
                let mut pkt = Vec::new();
                write_varint(&mut pkt, 0x08);
                pkt.push(0);
                let _ = write_frame(s, &pkt, compression);
            }
            if resource_pack_status_disconnects(link.rp_status) {
                send_config_disconnect(
                    s,
                    compression,
                    "This server requires the configured resource pack.",
                );
                return ConfigPoll::Abort;
            }
            ConfigPoll::Serviced
        }
        _ => ConfigPoll::Frame(id),
    }
}

/// `MEGU_SERVER_LINKS` parsed entries: `(builtin id | custom label NBT, url)`.
type ParsedServerLinks<'a> = Vec<(Option<u32>, Option<Vec<u8>>, &'a str)>;

/// `MEGU_SERVER_LINKS`/`MEGU_REPORT_DETAILS` in their configuration-phase
/// slots: vanilla writes `server_links` (`0x10`) and `custom_report_details`
/// (`0x0f`) immediately after the brand custom-payload, before
/// `feature_flags`. The bodies are shared with the play-phase refresh the
/// post-join burst sends.
fn send_config_links_and_reports(s: &mut TcpStream, compression: Option<usize>) {
    if let Ok(links) = std::env::var("MEGU_SERVER_LINKS") {
        // The post-join burst's convention: `builtin:<id>=<url>` or
        // `<text>=<url>`; text labels ride the same `text_component_nbt`.
        let mut parsed: ParsedServerLinks<'_> = Vec::new();
        for entry in links.split(';').map(str::trim).filter(|e| !e.is_empty()) {
            let Some((label, url)) = entry.split_once('=') else {
                continue;
            };
            if let Some(builtin) = label
                .strip_prefix("builtin:")
                .and_then(|v| v.trim().parse::<u32>().ok())
            {
                parsed.push((Some(builtin), None, url));
            } else {
                parsed.push((None, Some(text_component_nbt(label)), url));
            }
        }
        if !parsed.is_empty() {
            let wire: Vec<(PlayServerLinkLabel<'_>, &str)> = parsed
                .iter()
                .filter_map(|(builtin, custom, url)| match (builtin, custom) {
                    (Some(builtin), _) => Some((PlayServerLinkLabel::BuiltIn(*builtin), *url)),
                    (_, Some(nbt)) => Some((PlayServerLinkLabel::Custom(nbt.as_slice()), *url)),
                    _ => None,
                })
                .collect();
            let (_, payload) = encode_play_server_links(&wire);
            let mut pkt = Vec::new();
            write_varint(&mut pkt, 0x10);
            pkt.extend_from_slice(&payload);
            let _ = write_frame(s, &pkt, compression);
        }
    }
    if let Ok(details) = std::env::var("MEGU_REPORT_DETAILS") {
        let entries: Vec<(&str, &str)> = details
            .split(';')
            .filter_map(|e| e.split_once('='))
            .collect();
        if !entries.is_empty() {
            let (_, payload) = encode_play_custom_report_details(&entries);
            let mut pkt = Vec::new();
            write_varint(&mut pkt, 0x0f);
            pkt.extend_from_slice(&payload);
            let _ = write_frame(s, &pkt, compression);
        }
    }
}

/// The opt-in session packets vanilla delivers through the configuration
/// task queue: `store_cookie` (`0x0a`), `cookie_request` (`0x00`) and
/// `resource_pack_push` (`0x09`) — the same `MEGU_*`-gated features the
/// post-join burst refreshes. Returns true when a resource pack went out,
/// in which case the caller holds the finish until a terminal `0x06`
/// status arrives.
fn send_config_cookie_and_pack(s: &mut TcpStream, compression: Option<usize>) -> bool {
    if let Ok(list) = std::env::var("MEGU_STORE_COOKIE") {
        for pair in list.split(';').map(str::trim).filter(|p| !p.is_empty()) {
            let Some((key, value)) = pair.split_once('=') else {
                continue;
            };
            let Some((_, payload)) = encode_play_store_cookie(key, value.as_bytes()) else {
                continue;
            };
            let mut pkt = Vec::new();
            write_varint(&mut pkt, 0x0a);
            pkt.extend_from_slice(&payload);
            let _ = write_frame(s, &pkt, compression);
        }
    }
    if let Ok(list) = std::env::var("MEGU_COOKIE_REQUEST") {
        for key in list.split(';').map(str::trim).filter(|k| !k.is_empty()) {
            let (_, payload) = encode_play_cookie_request(key);
            let mut pkt = Vec::new();
            write_varint(&mut pkt, 0x00);
            pkt.extend_from_slice(&payload);
            let _ = write_frame(s, &pkt, compression);
        }
    }
    let mut pushed = false;
    if let Some(payload) = resource_pack_pkt() {
        let mut pkt = Vec::new();
        write_varint(&mut pkt, 0x09);
        pkt.extend_from_slice(&payload);
        let _ = write_frame(s, &pkt, compression);
        pushed = true;
    }
    pushed
}

/// The full configuration exchange shared by initial login and the mid-play
/// `start_configuration` re-entry: replay the captured stream up to
/// `select_known_packs`, wait for the client's `0x07` answer, send the rest
/// plus the operator session packets, then `finish_configuration` (`0x03`)
/// and its acknowledgement. Throughout, the `ConfigLink` keep-alive cadence,
/// pong/cookie/pack-response servicing and rate limiting run inline — the
/// phase is connection management, not a bare replay.
fn run_config_exchange(
    s: &mut TcpStream,
    rx: &mut RxBuf,
    cfg: &[(i64, Vec<u8>)],
    compression: Option<usize>,
    rate: &mut connection_limits::PacketRateLimit,
    link: &mut ConfigLink,
    reset_chat_chain: bool,
) -> bool {
    for (pid, pkt) in cfg {
        if write_frame(s, pkt, compression).is_err() {
            return false;
        }
        if *pid == 0x01 {
            // Vanilla's order: brand, then server_links/report_details,
            // then feature_flags and the task queue.
            send_config_links_and_reports(s, compression);
        }
        if *pid == 0x0e {
            break;
        }
    }
    if !cfg.iter().any(|(id, _)| *id == 0x0e) {
        return false;
    }
    s.set_read_timeout(Some(Duration::from_millis(250))).ok();
    let t0 = Instant::now();
    let mut got_selpacks = false;
    while t0.elapsed() < Duration::from_secs(15) {
        match config_next_frame(s, rx, compression, rate, link) {
            ConfigPoll::Frame(0x07) => {
                got_selpacks = true;
                break;
            }
            ConfigPoll::Frame(..) | ConfigPoll::Serviced => continue,
            ConfigPoll::Abort => return false,
        }
    }
    if !got_selpacks {
        return false;
    }
    for (pid, pkt) in cfg {
        if matches!(*pid, 0x01 | 0x0c | 0x0e | 0x03) {
            continue;
        }
        if write_frame(s, pkt, compression).is_err() {
            return false;
        }
    }
    if reset_chat_chain && send_config_reset_chat(s, compression).is_err() {
        return false;
    }
    let pack_pushed = send_config_cookie_and_pack(s, compression);
    if pack_pushed {
        // `ServerResourcePackConfigurationTask`: the task queue — and with it
        // the finish — waits for a terminal pack status. A client that never
        // answers is reaped by the keep-alive timeout.
        let t0 = Instant::now();
        while !matches!(link.rp_status, Some(0 | 1 | 2 | 5 | 6)) {
            if t0.elapsed() > Duration::from_secs(60) {
                return false;
            }
            match config_next_frame(s, rx, compression, rate, link) {
                ConfigPoll::Abort => return false,
                _ => continue,
            }
        }
    }
    let mut fin = Vec::new();
    write_varint(&mut fin, 0x03);
    if write_frame(s, &fin, compression).is_err() {
        return false;
    }
    let t0 = Instant::now();
    loop {
        if t0.elapsed() > Duration::from_secs(15) {
            return false;
        }
        match config_next_frame(s, rx, compression, rate, link) {
            ConfigPoll::Frame(0x03) => return true,
            ConfigPoll::Frame(..) | ConfigPoll::Serviced => continue,
            ConfigPoll::Abort => return false,
        }
    }
}

/// Mid-play `start_configuration` (`0x69`): the registry-resync lane. Vanilla
/// re-enters the configuration phase when synced content has to reach a live
/// client; the client answers with play `0x0c` and the phase repeats. Here,
/// `play_content_revision_sync` marks connections whose content revision
/// carries registry data and this drives the exchange on the owning thread:
/// send `0x69`, wait for the ack, take the player off the online list while
/// their client decodes configuration frames (play-phase traffic mid-flip is
/// a desync — the same reason vanilla `removePlayerFromWorld`s first), run
/// the shared config engine, then rejoin through the respawn+chunk+teleport
/// lane the dimension switch uses. The other clients' world view is kept:
/// the player entity never leaves their screens, matching the tab entry that
/// stays listed.
fn play_reconfigure_exchange(
    me: &Arc<Client>,
    s: &mut TcpStream,
    rx: &mut RxBuf,
    compression: Option<usize>,
    rate: &mut connection_limits::PacketRateLimit,
    view: &mut i32,
) -> bool {
    let mut start = Vec::new();
    write_varint(&mut start, 0x69);
    if write_frame(s, &start, compression).is_err() {
        return false;
    }
    clients()
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .retain(|c| c.eid != me.eid);
    s.set_read_timeout(Some(Duration::from_millis(250))).ok();
    let t0 = Instant::now();
    loop {
        if t0.elapsed() > Duration::from_secs(15) {
            return false;
        }
        match rx.next(s) {
            RxOut::Closed => return false,
            RxOut::Idle => continue,
            RxOut::Frame(0x0c, _) => break,
            // Play packets that crossed the flip are legal to drop; the
            // client's `0x0c` is the only awaited answer.
            RxOut::Frame(..) => continue,
        }
    }
    reconfigure_acked()
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .insert(me.eid);
    // The chat chain does not survive a phase re-entry: `reset_chat` inside
    // the exchange tells the client, and the server-side session state goes
    // with it — a fresh `chat_session_update` arrives after the rejoin.
    chat_sessions()
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .remove(&me.eid);
    chat_ack_offsets()
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .remove(&me.eid);
    let cfg = load_config_packets();
    let mut link = ConfigLink::new(*view);
    if !run_config_exchange(s, rx, &cfg, compression, rate, &mut link, true) {
        return false;
    }
    // Configuration-phase answers merge into the play stores: a resent
    // client-information view distance, cookie responses, a pong probe.
    if link.client_view != *view {
        *view = link.client_view;
        *me.view.lock().unwrap_or_else(|e| e.into_inner()) = link.client_view;
    }
    if !link.cookies.is_empty() {
        client_cookies()
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .entry(me.eid)
            .or_default()
            .extend(link.cookies);
    }
    if let Some(pong) = link.last_pong {
        last_client_pongs()
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .insert(me.eid, pong);
    }
    // Rejoin `returnToWorld`-style: rebuild the tab list both ways (the
    // re-entering client's list was reset by the phase flip), refresh the
    // name-completion sets, then let the respawn+chunk+teleport lane rebuild
    // the world view.
    {
        let mut cls = clients().lock().unwrap_or_else(|e| e.into_inner());
        let pi = player_info_add(me);
        let mut names: Vec<String> = cls.iter().map(|c| c.name.clone()).collect();
        names.push(me.name.clone());
        let (_, all_names) = encode_play_custom_chat_completions(0, &names);
        let _ = send_packet(&mut me.sock.lock().unwrap_or_else(|e| e.into_inner()), 0x18, all_names);
        let (_, joined_name) =
            encode_play_custom_chat_completions(0, std::slice::from_ref(&me.name));
        for c in cls.iter() {
            let _ = send_packet(&mut me.sock.lock().unwrap_or_else(|e| e.into_inner()), 0x3e, player_info_add(c));
            let _ = send_packet(&mut c.sock.lock().unwrap_or_else(|e| e.into_inner()), 0x3e, pi.clone());
            let _ = send_packet(&mut c.sock.lock().unwrap_or_else(|e| e.into_inner()), 0x18, joined_name.clone());
        }
        cls.push(me.clone());
    }
    let (dim, pos) = (
        *me.dim.lock().unwrap_or_else(|e| e.into_inner()),
        *me.pos.lock().unwrap_or_else(|e| e.into_inner()),
    );
    switch_client_dimension(me, dim, (pos.0, pos.1, pos.2, pos.3, pos.4), *view);
    true
}

/// The number of chunks the current view window can hold: the exact count of
/// the vanilla rounded-square tracking region (d=2 → 45, not 25).
fn window_batch(view: i32) -> usize {
    ChunkWindow::at(0.0, 0.0, view)
        .unsent(&HashSet::new())
        .count()
}

#[derive(Clone, Copy, PartialEq, Eq)]
struct ChunkWindow {
    center: (i32, i32),
    radius: i32,
}

impl ChunkWindow {
    fn at(x: f64, z: f64, radius: i32) -> Self {
        Self {
            center: (spatial_chunk_coord(x), spatial_chunk_coord(z)),
            radius,
        }
    }

    fn contains(self, (x, z): (i32, i32)) -> bool {
        // Login's initial radius-zero window is the spawn chunk and its 3x3 ring.
        // Negotiated player views are clamped to at least two.
        if self.radius == 0 {
            return (i64::from(x) - i64::from(self.center.0)).abs() <= 1
                && (i64::from(z) - i64::from(self.center.1)).abs() <= 1;
        }
        // Vanilla 1.21.1 `ChunkTrackingView.Positioned`: the tracked region
        // is a rounded square, not a Chebyshev square — for view distance d
        // the bounding box is (2d+3)² with the four far corners cut, so
        // d=2 tracks 45 chunks (rows 5,7,7,7,7,7,5), not 25.
        let dx = (i64::from(x) - i64::from(self.center.0))
            .abs()
            .saturating_sub(1)
            .max(0);
        let dz = (i64::from(z) - i64::from(self.center.1))
            .abs()
            .saturating_sub(1)
            .max(0);
        let lo = dx.min(dz);
        let hi = dx.max(dz).saturating_sub(1).max(0);
        lo * lo + hi * hi < i64::from(self.radius) * i64::from(self.radius)
    }

    fn leaving(self, _previous: Option<Self>, sent: &HashSet<(i32, i32)>) -> Vec<(i32, i32)> {
        sent.iter()
            .copied()
            .filter(|&c| !self.contains(c))
            .collect()
    }

    fn unsent(self, sent: &HashSet<(i32, i32)>) -> impl Iterator<Item = (i32, i32)> + '_ {
        let (cx, cz) = self.center;
        // Vanilla bounding box extends one chunk past the nominal radius.
        let r = self.radius + 1;
        (cx.saturating_sub(r)..=cx.saturating_add(r))
            .flat_map(move |x| (cz.saturating_sub(r)..=cz.saturating_add(r)).map(move |z| (x, z)))
            .filter(move |c| self.contains(*c) && !sent.contains(c))
    }
}

/// Explicit bound for a connection's `sent` chunk set: the bounding box of
/// one full window at `radius` (the delivery scan extends one chunk past the
/// nominal radius, so the side is `2*radius + 3`). The `leaving` prune in
/// `stream_chunks` keeps the set exactly at the window on every call; this
/// bound is the invariant a future insert path must also respect.
fn sent_chunks_bound(radius: i32) -> usize {
    let side = (2 * radius.max(0) + 3) as usize;
    side * side
}

#[cfg(test)]
mod sent_chunks_bound_tests {
    use super::*;

    #[test]
    fn sent_chunk_set_is_explicitly_bounded_by_the_window() {
        // The bounding-box side extends one chunk past the nominal radius.
        assert_eq!(sent_chunks_bound(0), 9);
        assert_eq!(sent_chunks_bound(2), 49);
        assert_eq!(sent_chunks_bound(32), 67 * 67);
        // A set flooded far past the window prunes back to the bound: first
        // the exact `leaving` pass the stream runs, then the explicit
        // retain invariant — the result never exceeds one bounding box.
        let window = ChunkWindow {
            center: (0, 0),
            radius: 2,
        };
        let mut sent: std::collections::HashSet<(i32, i32)> = std::collections::HashSet::new();
        for x in -60..60 {
            for z in -60..60 {
                sent.insert((x, z));
            }
        }
        assert!(sent.len() > sent_chunks_bound(window.radius));
        for c in window.leaving(None, &sent) {
            sent.remove(&c);
        }
        if sent.len() > sent_chunks_bound(window.radius) {
            sent.retain(|&c| window.contains(c));
        }
        assert!(sent.len() <= sent_chunks_bound(window.radius));
        assert!(sent.iter().all(|&c| window.contains(c)));
    }
}

/// The login path sends only the spawn chunk and its immediate ring before the
/// teleport handshake. The configured view distance is filled by the ordinary
/// chunk delivery loop after the player is registered.
fn initial_chunk_window(x: f64, z: f64) -> ChunkWindow {
    ChunkWindow::at(x, z, 0)
}

/// Replace the full light lists from map_chunk's cached payload with sparse
/// lists. Block and biome palettes still carry one record per vertical section.
fn cull_chunk_light(packet: &mut Vec<u8>, dim: DimId) {
    const ARRAY_WIRE_SIZE: usize = 2 + 2048;
    let all = dim.light_mask_longs();
    let words = all.len();
    let block_count = dim.light_sections();
    let sky_count = if worldgen::has_skylight(dim) {
        block_count
    } else {
        0
    };
    // VarInt-coded `long[]` length; every count here stays under 128 except a
    // very tall dimension's array counts.
    let varint_len = |v: usize| megu_core::varint::varlong_i64_len(v as i64);
    // two full bitsets, two empty ones, the two array-count VarInts, then the
    // two counted array lists.
    let suffix_size = 2 * (1 + 8 * words)
        + 2
        + varint_len(sky_count)
        + varint_len(block_count)
        + (sky_count + block_count) * ARRAY_WIRE_SIZE;
    let Some(start) = packet.len().checked_sub(suffix_size) else {
        return;
    };
    let mut light = &packet[start..];
    let read_mask = |light: &mut &[u8]| -> Option<Vec<u64>> {
        let count = usize::try_from(read_protocol_i32(light)?).ok()?;
        if count * 8 > light.len() {
            return None;
        }
        let (raw, rest) = light.split_at(count * 8);
        *light = rest;
        Some(
            raw.as_chunks::<8>().0.iter()
                .map(|w| u64::from_be_bytes(*w))
                .collect(),
        )
    };
    // The two full-coverage masks: sky is `all` for a lit dimension and an
    // all-zero bitset (zero words, or padded zero words) for a dark one; the
    // block mask is always `all`. Anything else is not a full-coverage packet
    // this transform understands.
    let Some(sky_mask) = read_mask(&mut light) else {
        return;
    };
    let sky_ok = if sky_count == 0 {
        sky_mask.iter().all(|w| *w == 0)
    } else {
        sky_mask == all
    };
    let block_ok = read_mask(&mut light).is_some_and(|m| m == all);
    if !sky_ok || !block_ok {
        return;
    }
    if !light.starts_with(&[0, 0]) {
        return;
    }
    light = &light[2..];
    let mut lists = [Vec::with_capacity(sky_count), Vec::with_capacity(block_count)];
    for (arrays, count) in lists.iter_mut().zip([sky_count, block_count]) {
        if read_protocol_i32(&mut light) != Some(count as i32) {
            return;
        }
        for _ in 0..count {
            if read_protocol_i32(&mut light) != Some(2048) || light.len() < 2048 {
                return;
            }
            let (array, rest) = light.split_at(2048);
            arrays.push(array);
            light = rest;
        }
    }
    if !light.is_empty() {
        return;
    }
    let bands = lists.each_ref().map(|arrays| {
        let nonempty: Vec<_> = arrays
            .iter()
            .map(|section| section[0] != 0 || uniform_section(section) != Some(0))
            .collect();
        // Full light-engine band, including the two boundary sections. A
        // nonzero light array can belong to an all-air block section.
        light_sections_in_band(&nonempty, 0, arrays.len().saturating_sub(1))
    });
    let [(sky, empty_sky), (block, empty_block)] = std::array::from_fn(|layer| {
        let mut present = vec![0u64; lists[layer].len().div_ceil(64)];
        for &i in &bands[layer] {
            present[i / 64] |= 1 << (i % 64);
        }
        let full = if lists[layer].len() == block_count {
            all.clone()
        } else {
            Vec::new()
        };
        let empty = full
            .iter()
            .zip(&present)
            .map(|(a, p)| a ^ p)
            .collect::<Vec<u64>>();
        (present, empty)
    });
    let array_bytes = (bands[0].len() + bands[1].len()) * ARRAY_WIRE_SIZE;
    let mut sparse = Vec::with_capacity(4 * (1 + 8 * words) + 2 + array_bytes);
    for mask in [&sky, &block, &empty_sky, &empty_block] {
        write_light_bitset(&mut sparse, mask);
    }
    for (band, arrays) in bands.iter().zip(&lists) {
        write_varint(&mut sparse, band.len() as i64);
        for &i in band {
            write_varint(&mut sparse, 2048);
            sparse.extend_from_slice(arrays[i]);
        }
    }
    packet.truncate(start);
    packet.extend_from_slice(&sparse);
}

fn chunk_packet_cache() -> &'static Mutex<connection_limits::ChunkPacketCache> {
    static CACHE: OnceLock<Mutex<connection_limits::ChunkPacketCache>> = OnceLock::new();
    CACHE.get_or_init(|| Mutex::new(connection_limits::ChunkPacketCache::new()))
}

/// FNV-1a combine step, matching `map_chunk_sig`'s combiner.
fn chunk_packet_mix(h: u64, v: u64) -> u64 {
    (h ^ v).wrapping_mul(megu_core::hash::FNV1A64_PRIME)
}

/// The revision a shared `0x27` frame is gated on: every input the sent bytes
/// can carry. The 3x3 `chunk_versions` tuple moves on any `set_block*` write in
/// the chunk or a neighbour (block edits and the light updates they cause),
/// `map_chunk_sig` covers signs, dimension-keyed spawners, the neighbour generated
/// emitters in `gen` and the settled light revision, and the fingerprint
/// covers the live block entities `splice_chunk_block_entities` merges in.
fn chunk_packet_revision(
    versions: &[u64; 9],
    sig: u64,
    block_entities: &[ChunkBlockEntity],
) -> u64 {
    let mut h = megu_core::hash::FNV1A64_OFFSET_BASIS;
    for &v in versions {
        h = chunk_packet_mix(h, v);
    }
    h = chunk_packet_mix(h, sig);
    for ((x, y, z), wire_id, nbt) in block_entities {
        for v in [*x as u64, *y as u64, *z as u64, *wire_id as u64] {
            h = chunk_packet_mix(h, v);
        }
        for &b in nbt {
            h = chunk_packet_mix(h, u64::from(b));
        }
    }
    h
}

/// The compression threshold `s` negotiated, if any. Read once per
/// `stream_chunks` call: the frames the cache hands out are shared, so the
/// per-packet `send_packet` lookup is not repeated per chunk.
fn socket_compression(s: &TcpStream) -> Option<usize> {
    let state = wire_state(socket_key(s))?;
    let compression = state.lock().unwrap_or_else(|e| e.into_inner()).compression;
    compression
}

/// Write an already-framed packet (bytes shared from `ChunkPacketCache`) with
/// `write_frame`'s failure contract: a partial write kills the socket.
#[cfg(test)]
fn write_shared_frame(s: &mut TcpStream, frame: &[u8]) -> std::io::Result<()> {
    // Cached chunks share the exact same producer order and encryption path
    // as tracker broadcasts. The writer receives opaque, fully encoded bytes.
    write_raw_frame(s, frame)
}

fn write_shared_frame_arc(s: &mut TcpStream, frame: Arc<[u8]>) -> std::io::Result<()> {
    write_raw_frame_arc(s, frame)
}

/// The shared `0x27` frame for `(dim, cx, cz)` at its current world revision.
/// On a miss the packet is rebuilt exactly as before — `map_chunk`, the live
/// block-entity splice, the light cull — then stored under the revision the
/// build started from only when those inputs held to the end; a mid-build edit
/// gets correct bytes that are simply not cached.
///
/// `occluded` selects the anti-xray lane: `true` is the surface player's
/// masked chunk, `false` the real one. The lanes are separate cache keys, so
/// every surface reader shares one `Arc` and every underground reader another.
fn conn_prof() -> bool {
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| std::env::var_os("MEGU_CONN_PROF").is_some())
}
/// The cache key a `0x27` frame is shared under: dimension, column and the
/// anti-xray occlusion lane (`true` is the surface player's masked chunk,
/// `false` the real one — the lanes never share a frame).
type ChunkFrameKey = (DimId, i32, i32, bool);

/// Everything a `0x27` frame build needs that is fixed at request time. The
/// entities and revision are computed on the requesting thread — the revision
/// has to be taken against *its* `gen` fill state, which also makes the plan
/// the dedup contract a pool worker builds against.
struct ChunkFramePlan {
    key: ChunkFrameKey,
    generation: u64,
    revision: u64,
    entities: Vec<ChunkBlockEntity>,
}

/// The live block-entity slice a `0x27` frame splices in, with the anti-xray
/// filters the send path applies — buried entity NBT (chests, barrels,
/// suspicious sand/gravel LootTableSeed, vaults) stays hidden until exposed,
/// and the occluded lane strips everything under the ceiling — sorted so the
/// spliced bytes and their fingerprint are deterministic across readers.
fn chunk_frame_entities(dim: DimId, cx: i32, cz: i32, occluded: bool) -> Vec<ChunkBlockEntity> {
    let mut entities = live_chunk_block_entities(dim, cx, cz);
    if anti_xray_enabled() {
        entities.retain(|&((x, y, z), _, _)| block_exposed_dim(dim, x, y, z));
    }
    if occluded {
        if let Some(ceil) = underground_occlude_ceil(dim, cx, cz) {
            entities.retain(|&((_, y, _), _, _)| y >= ceil);
        }
    }
    entities.sort_by(|a, b| (a.0, a.1, &a.2).cmp(&(b.0, b.1, &b.2)));
    entities
}

/// The result of probing the shared `ChunkPacketCache` before a build.
enum ChunkFrameLookup {
    /// The wire frame, ready to write; the chunk's own emitters are already
    /// restored into `gen` exactly as a rebuild would record them.
    Hit(Arc<[u8]>),
    /// No current entry — the caller either builds inline or hands the plan to
    /// the async delivery pool.
    Miss(Box<ChunkFramePlan>),
}

/// Probe the shared `ChunkPacketCache` for `(dim, cx, cz)` at the revision the
/// caller's world state implies. Everything the sent bytes can carry is folded
/// into the revision — the 3x3 `chunk_versions`, `map_chunk_sig`, and the live
/// block entities — so a hit is byte-for-byte what a rebuild would emit.
fn chunk_frame_lookup(
    compression: Option<usize>,
    gen: &mut GenSources,
    dim: DimId,
    cx: i32,
    cz: i32,
    occluded: bool,
) -> ChunkFrameLookup {
    let key = (dim, cx, cz, occluded);
    let generation = current_gen_seq();
    let entities = chunk_frame_entities(dim, cx, cz, occluded);
    let versions = chunk_versions_3x3(dim, cx, cz);
    let revision = chunk_packet_revision(&versions, map_chunk_sig(dim, cx, cz, gen), &entities);
    if let Some((frame, emitters)) = chunk_packet_cache()
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .frame(generation, key, revision, compression)
    {
        if std::env::var_os("MEGU_CHUNK_PROF").is_some() {
            static HITS: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
            eprintln!("[chunk-cache] hit cx={cx} cz={cz} total={}", HITS.fetch_add(1, Ordering::Relaxed) + 1);
        }
        // A hit restores the chunk's own emitters into `gen` exactly as a
        // rebuild would; `light_dirty_for_dim` reads them below.
        gen.insert((cx, cz), emitters);
        return ChunkFrameLookup::Hit(frame);
    }
    if std::env::var_os("MEGU_CHUNK_PROF").is_some() {
        static MISSES: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
        eprintln!(
            "[chunk-cache] miss cx={cx} cz={cz} occ={occluded} rev={revision} sig={} vers={:?} ents={} genfill={} total={}",
            map_chunk_sig(dim, cx, cz, gen),
            versions,
            entities.len(),
            gen.len(),
            MISSES.fetch_add(1, Ordering::Relaxed) + 1,
        );
    }
    ChunkFrameLookup::Miss(Box::new(ChunkFramePlan {
        key,
        generation,
        revision,
        entities,
    }))
}

/// The inline build behind a `ChunkFrameLookup::Miss`: `map_chunk_lane`, the
/// live block-entity splice and the light cull on the calling thread, then
/// stored under the plan's revision only when its inputs held for the whole
/// build — a mid-build edit gets correct bytes that are simply not cached.
fn build_chunk_frame_inline(
    plan: ChunkFramePlan,
    gen: &mut GenSources,
    compression: Option<usize>,
) -> Arc<[u8]> {
    let (dim, cx, cz, occluded) = plan.key;
    let built = map_chunk_lane(cx, cz, dim, gen, occluded);
    let emitters = gen.get(&(cx, cz)).cloned().unwrap_or_default();
    let still_current = chunk_packet_revision(
        &chunk_versions_3x3(dim, cx, cz),
        map_chunk_sig(dim, cx, cz, gen),
        &plan.entities,
    ) == plan.revision;
    let (_, packet) = encode_play_level_chunk_with_light(built, plan.entities, dim);
    if !still_current {
        if std::env::var_os("MEGU_CHUNK_PROF").is_some() {
            static STALE: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
            eprintln!("[chunk-cache] stale cx={cx} cz={cz} rev={} total={}", plan.revision, STALE.fetch_add(1, Ordering::Relaxed) + 1);
        }
        return connection_limits::ChunkPacketCache::frame_uncached(&packet, compression);
    }
    let mut cache = chunk_packet_cache().lock().unwrap_or_else(|e| e.into_inner());
    cache.insert(plan.generation, plan.key, plan.revision, emitters, packet);
    cache
        .frame(plan.generation, plan.key, plan.revision, compression)
        .map(|(frame, _)| frame)
        .expect("a freshly inserted chunk packet must frame")
}

/// The shared `0x27` frame for `(dim, cx, cz)` at its current world revision,
/// built inline on the calling thread. The synchronous counterpart of the
/// `async_chunk_delivery` pool's worker arm — used by the lane resend, by the
/// `MEGU_ASYNC_CHUNK_DELIVERY=0` escape hatch, and as the fallback for every
/// declined or failed async build.
fn cached_chunk_frame(
    compression: Option<usize>,
    gen: &mut GenSources,
    dim: DimId,
    cx: i32,
    cz: i32,
    occluded: bool,
) -> Arc<[u8]> {
    match chunk_frame_lookup(compression, gen, dim, cx, cz, occluded) {
        ChunkFrameLookup::Hit(frame) => frame,
        ChunkFrameLookup::Miss(plan) => build_chunk_frame_inline(*plan, gen, compression),
    }
}

// ---------- async chunk-frame delivery pool ----------
//
// `stream_chunks` used to run the whole `ChunkFrameLookup::Miss` build inline:
// populate under the generator lock, the per-section encode, the light cull,
// then the first reader's zlib pass — ~a second of serial work when a moving
// player crossed into ungenerated ground, multiplied by every player crossing
// the same ground. The `async_chunk_delivery` pool runs the identical build on
// bounded workers instead: the send loop enqueues every miss up front and only
// waits on the frame it is about to write, so workers finish the rest of the
// batch while earlier frames are on the wire, and two players walking toward
// the same column share one build.

/// What one finished worker build hands back to its waiters.
enum FrameOutcome {
    /// The packet landed in the shared `ChunkPacketCache` under the revision
    /// the worker computed after generation — and the requester's negotiated
    /// wire form is primed, so the zlib pass already ran off every connection
    /// thread. The waiter's own lookup picks the entry up by its current
    /// revision.
    Cached,
    /// Fresh bytes that could not be stored — a mid-build edit invalidated
    /// the inputs — so the waiter frames them uncached exactly as the inline
    /// path does.
    Uncached {
        packet: Vec<u8>,
        own_emitters: Vec<((i32, i32, i32), u8)>,
    },
}

/// One queued frame build. `gen` is the requester's 3x3 emitter snapshot — the
/// only `GenSources` window `map_chunk_sig` and the unsettled-light fallback
/// read — cloned so the worker touches no per-connection state.
struct FrameJob {
    plan: ChunkFramePlan,
    gen: GenSources,
    compression: Option<usize>,
    gen_ticket: Option<stream_gen::Ticket>,
}

/// The worker arm: wait for the chunk's streamed generation (the ticket the
/// requester already took out, so terrain is ready or `pop_done` on arrival),
/// then run the byte-identical build `build_chunk_frame_inline` performs —
/// `map_chunk_lane`, splice, light cull — and store it under the post-build
/// revision only while the inputs still hold.
fn run_frame_job(job: FrameJob) -> Option<FrameOutcome> {
    let (dim, cx, cz, occluded) = job.plan.key;
    // A worldgen re-init between request and build makes the plan's inputs
    // stale: decline so the waiter rebuilds against live state, the same
    // escape `stream_gen`'s generation tag gives its waiters.
    if job.plan.generation != current_gen_seq() {
        return None;
    }
    if let Some(ticket) = job.gen_ticket {
        let _ = ticket.wait();
    }
    let mut gen = job.gen;
    // The entity/revision fingerprint is taken here, not carried from the
    // requester's plan: populate can place the signs, generated spawners and
    // block entities a pre-generation scan cannot see, so the revision must
    // describe the world this frame actually encodes — the same inputs a
    // post-generation `chunk_frame_lookup` computes on the send loop.
    let entities = chunk_frame_entities(dim, cx, cz, occluded);
    let revision = chunk_packet_revision(
        &chunk_versions_3x3(dim, cx, cz),
        map_chunk_sig(dim, cx, cz, &gen),
        &entities,
    );
    // A racing requester's build may have landed while this job queued or
    // generated — the dedup window ends at job completion, not request.
    {
        let mut cache = chunk_packet_cache().lock().unwrap_or_else(|e| e.into_inner());
        if cache
            .frame(job.plan.generation, job.plan.key, revision, job.compression)
            .is_some()
        {
            return Some(FrameOutcome::Cached);
        }
    }
    let built = map_chunk_lane(cx, cz, dim, &mut gen, occluded);
    let own_emitters = gen.get(&(cx, cz)).cloned().unwrap_or_default();
    let still_current = chunk_packet_revision(
        &chunk_versions_3x3(dim, cx, cz),
        map_chunk_sig(dim, cx, cz, &gen),
        &entities,
    ) == revision;
    let (_, packet) = encode_play_level_chunk_with_light(built, entities, dim);
    if !still_current {
        return Some(FrameOutcome::Uncached {
            packet,
            own_emitters,
        });
    }
    let mut cache = chunk_packet_cache().lock().unwrap_or_else(|e| e.into_inner());
    cache.insert(
        job.plan.generation,
        job.plan.key,
        revision,
        own_emitters,
        packet,
    );
    // Prime the negotiated wire form off the connection thread: with
    // compression on, this `frame` call is where the chunk's single zlib pass
    // now runs, so no reader ever compresses on its own socket loop. A
    // generation bump or eviction between insert and frame only costs the
    // primed form — the next reader rebuilds it exactly as before.
    let _ = cache.frame(
        job.plan.generation,
        job.plan.key,
        revision,
        job.compression,
    );
    Some(FrameOutcome::Cached)
}

/// The pool's dedup key: the cache key plus the requester's revision. Two
/// requests share one build only when they would share one frame — a pair
/// whose `gen` fills fingerprint differently (unsettled light reads `gen`)
/// builds separately exactly as the synchronous path does, while requesters
/// seeing the same world revision merge no matter which asked first.
type FramePoolKey = (DimId, i32, i32, bool, u64);

fn chunk_frame_pool() -> &'static async_chunk_delivery::Pool<FramePoolKey, FrameJob, FrameOutcome> {
    static POOL: OnceLock<
        async_chunk_delivery::Pool<FramePoolKey, FrameJob, FrameOutcome>,
    > = OnceLock::new();
    POOL.get_or_init(|| {
        async_chunk_delivery::Pool::new(
            async_chunk_delivery::worker_count(),
            async_chunk_delivery::ASYNC_FRAME_CAP,
            run_frame_job,
        )
    })
}

/// The emitter window a frame build actually reads: `map_chunk_sig` and the
/// unsettled-light fallback only ever touch the 3x3 around `(cx, cz)`, so the
/// worker's `GenSources` is that slice of the requester's map rather than the
/// whole connection-side fill.
fn gen_neighborhood(gen: &GenSources, cx: i32, cz: i32) -> GenSources {
    let mut out = GenSources::new();
    for dx in -1..=1 {
        for dz in -1..=1 {
            if let Some(emitters) = gen.get(&(cx + dx, cz + dz)) {
                out.insert((cx + dx, cz + dz), emitters.clone());
            }
        }
    }
    out
}

/// One pending slot in the batch send order.
enum FrameSlot {
    /// The shared cache already holds the frame — write it now, ~0 ms.
    Ready(Arc<[u8]>),
    /// The build is queued on the delivery pool; wait only when this chunk's
    /// turn to send arrives.
    Pending(async_chunk_delivery::Ticket<FrameOutcome>),
    /// The pool declined (stopped or full): the inline build the pre-pool code
    /// always ran, preceded by the same streamed-generation ticket wait.
    Inline,
}

/// The async delivery arm of `stream_chunks`: cache hits write immediately,
/// misses are enqueued on the delivery pool so they build on background
/// workers, and the send loop then walks `news` in order — `0x0d`/`0x0c`
/// framing, `sent` bookkeeping, dirty-light resend inputs and sign packets all
/// identical to the synchronous arm. Returns `false` on a socket error.
#[allow(clippy::too_many_arguments)]
fn stream_chunk_frames_async(
    s: &mut TcpStream,
    sent: &mut std::collections::HashSet<(i32, i32)>,
    gen: &mut GenSources,
    dirty: &mut std::collections::HashSet<(i32, i32)>,
    dim: DimId,
    news: &[(i32, i32)],
    compression: Option<usize>,
    occluded: bool,
    allow_generate: bool,
) -> bool {
    // Keep only one build group queued per client — the same fairness bound
    // the synchronous arm applies to `stream_gen` and `prefetch_terrain_group`:
    // enqueueing the whole batch would let one client's outer rings sit ahead
    // of every later client's initial window in the delivery pool's FIFO. The
    // group is the same `terrain_group` shape: enough lookahead that workers
    // finish the rest of the group while its first frames go out.
    let group = terrain_group(async_chunk_delivery::worker_count());
    for chunk_group in news.chunks(group.max(1)) {
        // Phase 1 — lookups and enqueues. Nothing here blocks: a cache hit is
        // an immediate `Arc`, a miss takes out the streamed-generation ticket
        // and a pool slot, both non-blocking.
        let mut slots: Vec<FrameSlot> = Vec::with_capacity(chunk_group.len());
        for &(cx, cz) in chunk_group {
            match chunk_frame_lookup(compression, gen, dim, cx, cz, occluded) {
                ChunkFrameLookup::Hit(frame) => slots.push(FrameSlot::Ready(frame)),
                ChunkFrameLookup::Miss(plan) => {
                    // Warm the generation pool whether or not the frame pool
                    // accepts the job — an `Inline` slot waits on the same
                    // ticket the worker would have.
                    let gen_ticket = allow_generate
                        .then(|| stream_gen::request(dim, cx, cz))
                        .flatten();
                    let pool_key = (dim, cx, cz, occluded, plan.revision);
                    let job = FrameJob {
                        plan: *plan,
                        gen: gen_neighborhood(gen, cx, cz),
                        compression,
                        gen_ticket,
                    };
                    match chunk_frame_pool().request(pool_key, job) {
                        Some(ticket) => slots.push(FrameSlot::Pending(ticket)),
                        None => slots.push(FrameSlot::Inline),
                    }
                }
            }
        }
        // Phase 2 — the ordered send. Chunks leave in `news` order exactly as
        // the serial path wrote them; a `Pending` slot waits on a build that
        // has been running since phase 1, so the wait is only ever for the
        // head of the line, not the whole batch.
        for ((cx, cz), slot) in chunk_group.iter().zip(slots) {
            let frame = match slot {
                FrameSlot::Ready(frame) => frame,
                FrameSlot::Inline => {
                    // `stream_gen::request` dedups by key, so this hands back
                    // the same live ticket phase 1 took out — the inline build
                    // keeps the synchronous arm's exact wait-then-build shape.
                    if allow_generate {
                        if let Some(ticket) = stream_gen::request(dim, *cx, *cz) {
                            let _ = ticket.wait();
                        }
                    }
                    cached_chunk_frame(compression, gen, dim, *cx, *cz, occluded)
                }
                FrameSlot::Pending(ticket) => match ticket.wait().as_deref() {
                    Some(FrameOutcome::Uncached {
                        packet,
                        own_emitters,
                    }) => {
                        gen.insert((*cx, *cz), own_emitters.clone());
                        connection_limits::ChunkPacketCache::frame_uncached(packet, compression)
                    }
                    // `Cached` — the build landed in the shared cache primed
                    // for this socket's compression — a declined generation, a
                    // failed build, or a shared ticket resolved under inputs
                    // that no longer hold: every one of them takes the normal
                    // lookup, which hits the frame this build (or another
                    // requester's) just stored, or rebuilds inline — the same
                    // path the synchronous arm runs per chunk.
                    _ => cached_chunk_frame(compression, gen, dim, *cx, *cz, occluded),
                },
            };
            if write_shared_frame_arc(s, frame).is_err() {
                return false;
            }
            note_chunk_delivered(s, sent, gen, dirty, dim, *cx, *cz);
        }
    }
    true
}

/// Bookkeeping after one `0x27` frame is on the wire: mark the column held,
/// collect the light-dirty neighbours the resend pass recomputes, and emit one
/// block-entity packet per sign position. Identical for both delivery arms.
fn note_chunk_delivered(
    s: &mut TcpStream,
    sent: &mut std::collections::HashSet<(i32, i32)>,
    gen: &mut GenSources,
    dirty: &mut std::collections::HashSet<(i32, i32)>,
    dim: DimId,
    cx: i32,
    cz: i32,
) {
    sent.insert((cx, cz));
    for n in light_dirty_for_dim(dim, gen, cx, cz) {
        dirty.insert(n);
    }
    // one block-entity packet per sign position; it carries both
    // sides' lines plus dye/glow/wax state from `sign_entity_pkt`
    let snap = signs_in_chunk(dim, cx, cz);
    let mut positions: Vec<(i32, i32, i32)> = Vec::new();
    for ((_, sx, sy, sz, _), _) in snap {
        if !positions.contains(&(sx, sy, sz)) {
            positions.push((sx, sy, sz));
        }
    }
    for (sx, sy, sz) in positions {
        let _ = send_packet(s, 0x07, sign_entity_pkt(dim, sx, sy, sz));
    }
}

/// The pre-pool synchronous arm of `stream_chunks`, kept byte-for-byte for the
/// `MEGU_ASYNC_CHUNK_DELIVERY=0` escape hatch and as the documented fallback
/// shape the async arm mirrors: one terrain group of lookahead per batch, then
/// the serial per-chunk build/write loop.
#[allow(clippy::too_many_arguments)]
fn stream_chunk_frames_sync(
    s: &mut TcpStream,
    sent: &mut std::collections::HashSet<(i32, i32)>,
    gen: &mut GenSources,
    dirty: &mut std::collections::HashSet<(i32, i32)>,
    dim: DimId,
    news: &[(i32, i32)],
    compression: Option<usize>,
    occluded: bool,
    allow_generate: bool,
) -> bool {
    // Terrain is pure per chunk, so a group of the batch is built off the lock before the
    // send loop touches it; everything after it (features, overlays, encoding) stays
    // sequential in the order the client is served. The group size is bounded so the base
    // rows in `terr_c` cannot outgrow their store.
    let mut failed = false;
    let delivery_workers = delivery_prefetch_jobs();
    let delivery_round = (delivery_workers > 1).then(crate::feature::starts_round_begin);
    if let Some(round) = delivery_round {
        let _ = worldgen::with_gen(|g| g.starts_round = Some(round));
    }
    // Keep only one terrain group queued per client. Enqueueing an entire
    // delivery batch lets an early client's outer rings sit ahead of every
    // later client's initial window in stream_gen's ordered commit lane.
    // Group-sized lookahead still overlaps terrain preparation with encoding,
    // while giving other connection threads a chance to enqueue closer chunks.
    // The terrain rows stop one section below the dimension's own ceiling: a Nether/End
    // window is 0..256 (16 sections), not the Overworld's -64..320.
    let (lo, hi) = (dim.min_y(), dim.min_y() + dim.height() - 16);
    'delivery: for chunk_group in news.chunks(terrain_group(delivery_workers)) {
        let ticket_group: Vec<Option<stream_gen::Ticket>> = if allow_generate {
            chunk_group
                .iter()
                .map(|&(cx, cz)| stream_gen::request(dim, cx, cz))
                .collect()
        } else {
            chunk_group.iter().map(|_| None).collect()
        };
        // A queued chunk carries its own terrain prefetch inside the worker job,
        // so the group prefetch only covers the chunks the pool declined.
        let uncovered: Vec<(i32, i32)> = chunk_group
            .iter()
            .zip(&ticket_group)
            .filter(|(_, t)| t.is_none())
            .map(|(&c, _)| c)
            .collect();
        let __pf = Instant::now();
        prefetch_terrain_group_dim(dim, &uncovered, lo, hi, delivery_workers, delivery_round);
        let __pfe = __pf.elapsed();
        if conn_prof() && __pfe > Duration::from_millis(50) {
            eprintln!("[conn-prof] prefetch_terrain {:?}", __pfe);
        }
        for ((cx, cz), ticket) in chunk_group.iter().zip(&ticket_group) {
            if let Some(ticket) = ticket {
                // A false wait means the worker could not generate it; the
                // frame builder's own `ensure_populated` covers that chunk
                // inline exactly as before.
                let _ = ticket.wait();
            }
            let __cf = Instant::now();
            let frame = cached_chunk_frame(compression, gen, dim, *cx, *cz, occluded);
            let __cfe = __cf.elapsed();
            if conn_prof() && __cfe > Duration::from_millis(50) {
                eprintln!("[conn-prof] chunk_frame ({cx},{cz}) {:?}", __cfe);
            }
            if write_shared_frame_arc(s, frame).is_err() {
                failed = true;
                break 'delivery;
            }
            note_chunk_delivered(s, sent, gen, dirty, dim, *cx, *cz);
        }
    }
    if let Some(round) = delivery_round {
        let _ = worldgen::with_gen(|g| g.starts_round = None);
        crate::feature::starts_round_end(round);
    }
    !failed
}

#[allow(clippy::too_many_arguments)]
fn stream_chunks(
    s: &mut TcpStream,
    sent: &mut std::collections::HashSet<(i32, i32)>,
    gen: &mut GenSources,
    ack: &mut ChunkFeedback,
    dim: DimId,
    window: ChunkWindow,
    yaw: f32,
    // the centre is announced when the window moves (spawn, view request,
    // player crossing a chunk) - not on every batch, or a client pacing its own
    // batches would see the centre move while nothing did
    announce_center: bool,
    // The first batch is sent before the shared Play writer has been registered.
    initial_delivery: Option<&mut connection_limits::ChunkDelivery>,
    // Anti-xray lane for this player: `true` masks deep sections to solid host
    // rock for a surface player, `false` sends the real chunk. Decided by
    // `update_underground_lane` before the stream, never per chunk.
    occluded: bool,
    // `spectatorsGenerateChunks`: `false` while a spectator streams under the
    // rule switched off — only chunks already generated may enter the batch,
    // so the stream never tickets fresh worldgen on their behalf.
    allow_generate: bool,
) {
    let tick = TICK_IDX.load(Ordering::Relaxed);
    let select = |delivery: &mut connection_limits::ChunkDelivery| {
        let previous = delivery.window();
        let news = delivery.next_batch(window, sent, yaw, ack, tick);
        (previous, news)
    };
    let (previous, news) = if let Some(delivery) = initial_delivery {
        select(delivery)
    } else {
        with_play_wire(s, |play| select(&mut play.chunk_delivery))
            .unwrap_or_else(|| select(&mut connection_limits::ChunkDelivery::default()))
    };
    let news = if allow_generate {
        news
    } else {
        news.into_iter()
            .filter(|&(cx, cz)| spectator_chunk_allowed(dim, cx, cz))
            .collect::<Vec<_>>()
    };
    // MEGA-W2 §3.1 VelocityViewGovernor: under mod-suite the governor orders
    // this tick's batch — for a fast-moving player (window centre advancing
    // ≥ a chunk between streams ≈ elytra speed) the dead-ahead chunks send
    // first. The batch set itself is unchanged; only send order shifts.
    #[cfg(feature = "mod-suite")]
    let news = {
        let (vx, vz) = previous
            .map(|p| {
                (
                    (window.center.0 - p.center.0) as f32 * 16.0,
                    (window.center.1 - p.center.1) as f32 * 16.0,
                )
            })
            .unwrap_or((0.0, 0.0));
        let plan = live_plan_velocity_chunks(
            window.radius.clamp(0, 32) as u8,
            window.center.0,
            window.center.1,
            vx,
            vz,
            1.0,
            news.len(),
        );
        let mut rank: HashMap<(i32, i32), usize> = HashMap::with_capacity(plan.len());
        for (i, c) in plan.into_iter().enumerate() {
            rank.insert(c, i);
        }
        let mut n = news;
        n.sort_by_key(|c| rank.get(c).copied().unwrap_or(usize::MAX));
        n
    };
    // chunks leaving the window get an explicit unload — vanilla keeps
    // client memory bounded and the set now means exactly "chunks the
    // client holds" (updates must only target holders).
    for c in window.leaving(previous, sent) {
        let mut p = Vec::with_capacity(8);
        p.extend_from_slice(&c.1.to_be_bytes()); // wire order: chunkZ, chunkX
        p.extend_from_slice(&c.0.to_be_bytes());
        if send_packet(s, 0x21, p).is_err() {
            return;
        }
        sent.remove(&c);
        gen.remove(&c);
    }
    // Defense-in-depth bound: `sent` may never hold more than one window
    // bounding box. The prune above already enforces it exactly; this retain
    // is the explicit invariant against any path that could insert outside
    // the window without pruning.
    if sent.len() > sent_chunks_bound(window.radius) {
        sent.retain(|&c| window.contains(c));
    }
    // The centre update is not part of a batch, but it is the answer a view
    // request waits for even when nothing new is to be sent.
    if announce_center || previous.is_some_and(|old| old != window) {
        let mut vp = Vec::new();
        write_varint(&mut vp, i64::from(window.center.0));
        write_varint(&mut vp, i64::from(window.center.1));
        if send_packet(s, 0x54, vp).is_err() {
            return;
        }
    }
    if news.is_empty() {
        return;
    }
    let batch = news.len();
    if send_packet(s, 0x0d, vec![]).is_err() {
        return;
    }
    let mut dirty: std::collections::HashSet<(i32, i32)> = std::collections::HashSet::new();
    let compression = socket_compression(s);
    // The default arm builds misses on the bounded async delivery pool: cache
    // hits write immediately, misses build on background workers while earlier
    // frames go out, and the send loop only waits on the chunk it is about to
    // write. `MEGU_ASYNC_CHUNK_DELIVERY=0` restores the fully synchronous loop
    // for deterministic tests and serial CPU comparisons.
    let delivered = if async_chunk_delivery::enabled() {
        stream_chunk_frames_async(
            s,
            sent,
            gen,
            &mut dirty,
            dim,
            &news,
            compression,
            occluded,
            allow_generate,
        )
    } else {
        stream_chunk_frames_sync(
            s,
            sent,
            gen,
            &mut dirty,
            dim,
            &news,
            compression,
            occluded,
            allow_generate,
        )
    };
    if !delivered {
        return;
    }
    // A neighbour lit before this batch could not see the emitters generated now, so its light is
    // recomputed and re-sent. `light_dirty_for` limits this to held chunks a new emitter can
    // actually reach, and the set deduplicates the chunks several new neighbours all touch.
    for (cx, cz) in dirty {
        if !sent.contains(&(cx, cz)) {
            continue;
        }
        let __t = chunkprof::enabled().then(std::time::Instant::now);
        let pkt = update_light_packet_lane(
            dim,
            cx,
            cz,
            gen,
            occluded.then(|| underground_occlude_ceil(dim, cx, cz)).flatten(),
        );
        if let Some(t) = __t {
            use std::sync::atomic::Ordering;
            chunkprof::add(&chunkprof::RE_LIGHT, t);
            chunkprof::RE_LIGHT_N.fetch_add(1, Ordering::Relaxed);
        }
        if send_packet(s, 0x2a, pkt).is_err() {
            return;
        }
    }
    let mut bf = Vec::new();
    write_varint(&mut bf, batch as i64);
    if send_packet(s, 0x0c, bf).is_ok() {
        ack.sent_batch(Instant::now(), batch);
    }
}

// ---------- PARITY-58-C2S: remaining protocol-767 C2S play packets ----------

/// A bounds-checked cursor over one C2S body. Same contract as `P3bReader`
/// (every read fails closed on truncation) plus the VarLong `set_structure_block`
/// carries — the reader lives here so it cannot drift from the decoders.
struct C2sReader<'a> {
    data: &'a [u8],
    p: usize,
}
#[allow(dead_code)]
impl<'a> C2sReader<'a> {
    fn new(data: &'a [u8]) -> Self {
        C2sReader { data, p: 0 }
    }
    fn done(&self) -> bool {
        self.p == self.data.len()
    }
    fn byte(&mut self) -> Option<u8> {
        let b = *self.data.get(self.p)?;
        self.p += 1;
        Some(b)
    }
    fn bytes(&mut self, n: usize) -> Option<&'a [u8]> {
        let body = self.data.get(self.p..self.p.checked_add(n)?)?;
        self.p += n;
        Some(body)
    }
    /// Java `readVarInt`: LEB128, at most five payload bytes, u32 envelope.
    fn varint(&mut self) -> Option<i64> {
        let (v, used) = megu_core::varint::read_varint_i32(&self.data[self.p..]).ok()?;
        self.p += used;
        Some(i64::from(v as u32))
    }
    /// Java `readVarLong`: same LEB128 body, up to ten payload bytes.
    fn varlong(&mut self) -> Option<i64> {
        let (v, used) = megu_core::varint::read_varlong_i64(&self.data[self.p..]).ok()?;
        self.p += used;
        Some(v)
    }
    /// `FriendlyByteBuf.readUtf(max)`: VarInt length bounded at `max * 4`
    /// bytes, then at most `max` decoded chars of strict UTF-8.
    fn utf(&mut self, max: usize) -> Option<String> {
        let len = self.varint()?;
        if !(0..=max as i64 * 4).contains(&len) {
            return None;
        }
        let body = self.data.get(self.p..self.p.checked_add(len as usize)?)?;
        self.p += len as usize;
        let s = std::str::from_utf8(body).ok()?;
        if s.chars().count() > max {
            return None;
        }
        Some(s.to_owned())
    }
}

